D.LocalClientValues[40]="红色的雷象从未在纳格兰出现过，第一只红色的雷象幼崽出生于艾泽拉斯，就在埃索达降落后不久。有些饲养员推断说，这种独特的颜色是由破坏了秘血岛的辐射造成的。"
D.LocalClientValues[41]="这种变种的裂蹄牛蹄子上布满细小的缺口，使它能够安全地翻山越岭寻找食物。"
