D.LocalClientValues[226]="暗色作战塔布羊"
D.LocalClientValues[227]="梵尼莫·奎格利被认为是第一个给骆驼挤奶的人，他还打破了“最长时间非自主飞行”的记录。这两件事都发生在同一个下午。"
D.LocalClientValues[228]="在和宇宙中的腐蚀战斗了无数代之后，曾经在艾泽拉斯盛极一时的寻觅者现在只剩下三只了。"
