D.LocalClientValues[232]="当死去的英雄们被复活为亡灵时，他们的战马也一起复活了。"
D.LocalClientValues[233]="|cFFFFD200任务|r|n"
D.LocalClientValues[234]="有人说骑上灰皮穆山兽能给你带来健康和财富。这些人被称为“坐骑商人”。"
D.LocalClientValues[235]="“我还记得我的第一张飞毯……用雪人毛和粗麻布织成的。还不如这张漂亮。”——鼎鼎有名的佛罗佐"
D.LocalClientValues[236]="战歌氏族的成员长年猎杀这些裂蹄牛，用它们猩红色的皮做成战旗。"
D.LocalClientValues[237]="“科多兽是我们人民的脊梁。无论部落走到哪里——不管因为生意、定居还是战争——你都能看到强大的科多兽。”——哈布·爪蹄"
