D.LocalClientValues[3047]="这支狂放不羁的兽人氏族曾经在死亡之翼的授意下奴役了红龙军团和红龙女王阿莱克丝塔萨。如今龙喉氏族的数量和实力都已不如往昔，他们在暮光高地上建立了家园。"
