D.LocalClientValues[3226]="在潘达利亚战役期间，联盟搏击俱乐部的第一赛季拉开了帷幕。"
D.LocalClientValues[3227]="德拉诺战役期间的部落搏击俱乐部第二赛季活动。"
D.LocalClientValues[3228]="纳特是全世界最负盛名的钓鱼大师与美酒爱好者，在他暴躁易怒的外表下藏着一颗好为人师的心。"
D.LocalClientValues[3229]="要想守护艾泽拉斯，就必须在德拉诺取得决定性胜利。为此，部落酋长沃金召集了麾下最最精锐的勇士在塔纳安丛林建立据点，只为打倒古尔丹等邪恶势力。"
D.LocalClientValues[3230]="黑海岸雄鹿"
D.LocalClientValues[3231]="大地之环，旧世界"
D.LocalClientValues[3232]="益友"
D.LocalClientValues[3233]="由无情的贸易巨子加里维克斯控制的锈水财阀是科赞岛上最强大的贸易公司。他们的总部坐落在锈水码头，整片南海的贸易都被他们所掌控。"
D.LocalClientValues[3234]="由德拉诺的众多兽人氏族勉强联合而成的脆弱联盟，由格罗玛什·地狱咆哮领导。"
