D.LocalClientValues[3248]="你的私人保镖，驻扎在你的兵营里。你可以通过邀请艾萝娜一起战斗，与她建立起友谊。"
D.LocalClientValues[3249]="吉尔尼斯是一个幸存者的国度。当他们最后的人性也被剥去后，吉尔尼斯面临着来自内部的全新威胁。"
D.LocalClientValues[3250]="塞纳里奥议会"
D.LocalClientValues[3251]="神盾守备军"
D.LocalClientValues[3252]="在提里奥·弗丁与达里安·莫格莱尼的共同协议下，银色北伐军与黑锋骑士团决定暂时放下分歧、统一战线，合力攻入冰冠堡垒，击败巫妖王。"
D.LocalClientValues[3253]="初级驻院医师"
D.LocalClientValues[3254]="授人以鱼不如授人以渔，这群名为垂钓翁的熊猫人不光想着填饱族人的肚子，还希望能够提高自己的钓鱼本领。"
D.LocalClientValues[3255]="抗魔联军"
D.LocalClientValues[3256]="白鬼"
D.LocalClientValues[3257]="塞拉赞恩和她的石领主子嗣们统治着土元素位面深岩之洲。在见证了死亡之翼及其追随者对她的国度造成的伤害后，塞拉赞恩对所有外来者都充满了敌意。"
