D.LocalClientValues[3376]="集合织梦者：麦托克劳"
D.LocalClientValues[3377]="有些术士本意是好的，但经常做过头。区区几个术士对末日领主的抑制力还远远不够。"
D.LocalClientValues[3378]="戈隆多"
D.LocalClientValues[3379]="奥尔高格"
D.LocalClientValues[3380]="噩梦小鬼占领了月爪谷，他们正在亵渎这片静怡的森林。除掉那里的小鬼，恢复山谷的平衡。"
D.LocalClientValues[3381]="墓地中发现了一条黑暗的裂口。天知道有什么在那里等着我们呢。"
D.LocalClientValues[3382]="古特里克"
D.LocalClientValues[3383]="圣光法令"
D.LocalClientValues[3384]="害虫！我们的补给品里，兵营里，到处都是这些掠食者的身影！在被它们彻底淹没之前，快去毁掉它们位于阿兰卡峰林的巢穴吧。"
D.LocalClientValues[3385]="审判官奇尔班"
D.LocalClientValues[3386]="地狱火在塔拉多非常少见。我们希望这种情况能保持下去。去干掉那些地狱火，越多越好。"
D.LocalClientValues[3387]="邪能之池"
D.LocalClientValues[3388]="我看见了死食人魔"
D.LocalClientValues[3389]="使用陵墓作为驻地是彻头彻尾的无礼行径。快去让逝者带着微笑安息吧。"
D.LocalClientValues[3390]="这位船员阅历丰富并有能力证明这一点。任务成功率提高。"
D.LocalClientValues[3391]="|CFFFFFFF0首领|R\r\n若无法应对，则会降低任务成功率。"
