D.LocalClientValues[3408]="绿色 - 任务消耗"
D.LocalClientValues[3409]="影月谷到处都是迷茫和愤怒的兽人幽灵。在他们安息之前，所有人都处在危险之中。"
D.LocalClientValues[3410]="危害"
D.LocalClientValues[3411]="派一名追随者执行这个任务，以在瓦尔莎拉地区获得额外的支援。"
D.LocalClientValues[3412]="至高岭的部族有非常优秀的战士、猎人和萨满。但他们最不擅长隐匿和潜行。监视每个部族的营地。"
D.LocalClientValues[3413]="血鬃主母"
D.LocalClientValues[3414]="乐娜拉需要帮助"
