D.LocalClientValues[3416]="英雄"
D.LocalClientValues[3417]="熔化眼棱"
D.LocalClientValues[3418]="浩劫恶魔猎手"
D.LocalClientValues[3419]="用于解决一名危险的对手。有时还能令他们打破基本的物理法则，真古怪。"
D.LocalClientValues[3420]="精灵一族"
D.LocalClientValues[3421]="黑暗契约"
D.LocalClientValues[3422]="骑手萨拉纳尔需要伟大的托马斯爵士，也就是无头骑士曾用过的鞍座。那个鞍座被埋藏在血色修道院的墓地中。"
