D.LocalClientValues[3424]="高塔之影"
D.LocalClientValues[3425]="老兵"
D.LocalClientValues[3426]="一个党羽众多的敌人。容易受到范围效果的伤害。"
D.LocalClientValues[3427]="佐提·轮怒是大法师瓦格斯最好的朋友和知己。派一名勇士前往大法师卡德加在塔拉多的法师塔，看看佐提是否还在那里。"
D.LocalClientValues[3428]="提高在雪地中赢得战斗的几率。"
D.LocalClientValues[3429]="暗礁领主"
D.LocalClientValues[3430]="法师之主"
D.LocalClientValues[3431]="纠缠根须"
D.LocalClientValues[3432]="强风冲击"
D.LocalClientValues[3433]="毁灭者X2"
D.LocalClientValues[3434]="钢铁部落的切割者正在毁灭塔拉多的森林。这群混蛋。如果说谁有资格那么干，那也得是我们的人。"
D.LocalClientValues[3435]="碾碎挖矿时挖出的废石可获得额外材料，可用于修路、制造水泥等。"
D.LocalClientValues[3436]="营救行动"
D.LocalClientValues[3437]="解锁一名私人工程师，每天为你制作一种强力发明。全都是优秀的杰作！"
D.LocalClientValues[3438]="破碎海滩到处都是战斗所留下的杂物，其中有大量的流明石供我们收集。要小心，恶魔依然在这片区域进行巡逻。"
D.LocalClientValues[3439]="燃烧军团的猎人正在阿尔诺花园肆虐。快去查清他们的企图，并阻止他们。"
D.LocalClientValues[3440]="海底符文"
D.LocalClientValues[3441]="获取高品质皮革的过程是很乏味的，但部落计划剥制这里的多头蛇皮革。这个活儿可不轻松，我们正好来个黄雀在后，赚它个盆满钵满。"
D.LocalClientValues[3442]="查明纳迦的秘密。"
D.LocalClientValues[3443]="食怨者"
D.LocalClientValues[3444]="废墟中的法罗纳尔"
D.LocalClientValues[3445]="开启沙塔尔城防军或嘲颅氏族阵营声望。同时解锁一个新技能，可让你从德拉诺各地收集零件制造一名拍卖师。"
D.LocalClientValues[3446]="燃烧的塔拉多"
D.LocalClientValues[3447]="工坊可以为勇敢的工匠生产出各种实用的小玩意儿和零件，还可以制造神奇的机械设备。"
D.LocalClientValues[3448]="珠光宝气的哈莉娅"
D.LocalClientValues[3449]="荧光夹竹桃"
D.LocalClientValues[3450]="风剪"
D.LocalClientValues[3451]="汽痕强盗"
D.LocalClientValues[3452]="可以在要塞水域内钓到小型德拉诺鱼类。同时开启德拉诺每日钓鱼任务。"
D.LocalClientValues[3453]="冰喉双头飞龙"
D.LocalClientValues[3454]="幼龙摔跤手"
D.LocalClientValues[3455]="吞噬的虚空"
D.LocalClientValues[3456]="暗影大师"
D.LocalClientValues[3457]="未知敌人"
D.LocalClientValues[3458]="邪焰火雨"
D.LocalClientValues[3459]="缚血者斯丁特"
D.LocalClientValues[3460]="格罗玛什尔的北方住着刃喉氏族，他们是一群臭名昭著的强盗。去干掉他们的首领灵牙，狠狠打击他们的士气吧。"
D.LocalClientValues[3461]="如果我们的部队需要经历战火洗礼，那么没有比那头巨大的戈隆，毁灭者多弗更合适的练手对象了。"
D.LocalClientValues[3462]="每天用德拉诺种子种植出药材，并使药圃中出现草药点。"
D.LocalClientValues[3463]="燃烧军团在维库人中有个强力的盟友，神王斯科瓦尔德。也许他们把马迪亚斯·肖尔关押在了勇者之门。"
D.LocalClientValues[3464]="进入黑石塔并不容易，可我们有秘密武器：钻探机。黑铁杂碎们永远不会知道是谁袭击了他们。"
D.LocalClientValues[3465]="神器 - 死亡骑士任务"
D.LocalClientValues[3466]="达拉然下水道守卫"
D.LocalClientValues[3467]="汽痕战士"
D.LocalClientValues[3468]="就连灰谷的森林里，也有人发现了堕落者瑞萨扎尔所率领的萨特。他们可能很快就会对我们发动全面进攻。"
D.LocalClientValues[3469]="碎潮者阿奎里斯"
D.LocalClientValues[3470]="纳斯拉克斯要塞有一箱邪能水晶，可以用来给我们的防御工事供能。潜入军团的基地，把水晶取回来吧。"
D.LocalClientValues[3471]="天台上的符文"
D.LocalClientValues[3472]="能够驾驭元素的施法者，使用自然的毁灭之力打击敌人，可以应对某些|C00b3ffff首领|R。"
