D.LocalClientValues[3488]="提高独自执行任务的成功率。"
D.LocalClientValues[3489]="巡逻队报告说有一群刃牙虎人正在到处伏击纳格兰的商队。去找到并阻止他们吧。"
D.LocalClientValues[3490]="一群变节者想要逃出钢铁部落！让我们帮他们肃清道路吧。"
