D.LocalClientValues[3510]="基尔萨克斯"
D.LocalClientValues[3511]="为了偷袭毫无防备的航母，我们特意设计出了潜水艇。我们已经在海湾里准备了一艘航母，去看看你能不能偷袭到它吧。"
D.LocalClientValues[3512]="配合守望者：法斯尼尔"
D.LocalClientValues[3513]="军事思想"
D.LocalClientValues[3514]="塞拉赞恩特使"
D.LocalClientValues[3515]="啸风双头飞龙"
D.LocalClientValues[3516]="摧毁战车"
D.LocalClientValues[3517]="部落军队驶向霜火岭时，他们的船只几乎是完好无损地抵达了目的地。兽人或许并不是没脑子的莽夫，虽然他们还是丢下了许多值钱的货物。"
D.LocalClientValues[3518]="夜之子破坏者"
D.LocalClientValues[3519]="我们得派一支队伍去侦察一下萨格拉斯之墓的大门。小心，执行这个的任务的人很可能有去无回。"
