D.LocalClientValues[3539]="防御"
D.LocalClientValues[3540]="邪能机器"
D.LocalClientValues[3541]="风暴峡湾的某处有一座强大的圣光信标。我们得找到它。"
D.LocalClientValues[3542]="海妖之歌"
D.LocalClientValues[3543]="封锁线：消逝之海"
D.LocalClientValues[3544]="至高岭的部族害怕在夜里离开家门，因为有只巨大的猫科野兽潜行在他们村庄的边境附近。"
D.LocalClientValues[3545]="多亏了指挥中心发来的情报，我们发现了一箱燃烧军团的补给品。只有你最精锐的勇士和部队才有可能抓住这个机会。"
D.LocalClientValues[3546]="钢铁部落运输舰"
D.LocalClientValues[3547]="恶魔已经潜入了英灵之庭，它们显然不是来欣赏风景的。快去弄清它们的阴谋吧。"
D.LocalClientValues[3548]="|cFFFFD200职业：|r猎人|n|n|cFFFFD200任务：|r勇士：雷克萨|n|n|cFFFFD200地区：|r至高岭"
D.LocalClientValues[3549]="混乱畸体"
D.LocalClientValues[3550]="德鲁伊们担心始祖幼龙的数量会急剧减少。快去黑石塔上层，从督军扎伊拉的大军手中抢救始祖龙蛋吧。"
D.LocalClientValues[3551]="没有额外战利品。"
D.LocalClientValues[3552]="投戟者泰德里斯"
D.LocalClientValues[3553]="虽然达拉然的法师知道怎样让一座城市浮起来，但他们有时也会忘记地基的裂缝。潜在的能量在那里获得了生命。"
D.LocalClientValues[3554]="瓦尔莎拉的夜晚充满着焦躁生物的嚎叫。调查清楚原因，然后结束它们的痛苦。"
D.LocalClientValues[3555]="焦血"
D.LocalClientValues[3556]="裂地者库尔"
D.LocalClientValues[3557]="激荡的天神之力将力量、重生与野性赋予他们选中的盟友。"
D.LocalClientValues[3558]="淬毒倒钩"
D.LocalClientValues[3559]="毒性之咬"
D.LocalClientValues[3560]="孵化中的蛛卵"
D.LocalClientValues[3561]="传说马上就要举办辣椒烹饪大赛了，而老实说，我已经受够了每天喝稀粥的日子了。快派个人去随便赢点什么回来吧。"
D.LocalClientValues[3562]="雷霆打击"
D.LocalClientValues[3563]="我们已经招募了一些部队，可以用来为勇士提供增援。派他们去执行例行的侦察任务。"
