D.LocalClientValues[3584]="杀掉地下的鸦人。"
D.LocalClientValues[3585]="永燃烈焰"
D.LocalClientValues[3586]="很少有野兽会像焦羽那样危险而恐怖，它是鹰头猫的领袖，从不畏惧任何猎人。干掉焦羽。"
