D.LocalClientValues[3588]="任务消耗提高。"
D.LocalClientValues[3589]="织雾武僧"
D.LocalClientValues[3590]="傲慢的食人魔"
D.LocalClientValues[3591]="奴役法术"
D.LocalClientValues[3592]="“这里居然有决斗场？无论如何都要堕落成赌鬼的话，不如当个能打的赌鬼。”——乔拉齐·拉文霍德"
D.LocalClientValues[3593]="恶魔卫士军团士兵"
D.LocalClientValues[3594]="穿越敌人的传送门"
D.LocalClientValues[3595]="是时候篡改一下钢铁部落的指令了。如果能干掉那些守卫，我们就能改写历史。"
D.LocalClientValues[3596]="影谷喷毒者"
D.LocalClientValues[3597]="奥蕾莉亚请你搜索奥罗纳尔废墟，寻找还没被暗影吞噬的克罗库。"
D.LocalClientValues[3598]="积怨唤雷者"
D.LocalClientValues[3599]="厚皮裂蹄母牛"
D.LocalClientValues[3600]="希萨莉·黑鸦遇到了大麻烦。海巨人抓住了她，逼她参与他们的地下搏击擂台。我们得把她救出来！"
D.LocalClientValues[3601]="奇怪的能量球"
D.LocalClientValues[3602]="缚血者特里隆"
D.LocalClientValues[3603]="阿兰卡峰林"
D.LocalClientValues[3604]="你的炼金实验室开始招收学徒，他们可以每天为你提供一些药水。"
D.LocalClientValues[3605]="海盗"
D.LocalClientValues[3606]="玄牛武僧坚毅果敢，只有在试炼中克服了自己最大恐惧的最强者才能晋升为大师。"
