D.LocalClientValues[3629]="追踪蔑潮：永不安息的亡者"
D.LocalClientValues[3630]="一般（7.0）"
D.LocalClientValues[3631]="神圣屏障"
D.LocalClientValues[3632]="黑鸦刺客正在攻击鲑鱼溪，杀害家畜，偷窃庄稼。快去保护那些无辜的村民。"
D.LocalClientValues[3633]="脱轨的车站"
D.LocalClientValues[3634]="由于风力不足且风帆破损，一艘敌方航母正在护航舰队的掩护下缓慢前行。我们决不能让他们的部队和物资登陆。"
D.LocalClientValues[3635]="在戈尔隆德新近形成的焦油坑附近出现了一群魔荚人。如果我们击败他们，就可以抽取那里的燃料了。"
D.LocalClientValues[3636]="7.0 提示假人 - 装备 - 绿色 - 世界任务金币"
D.LocalClientValues[3637]="能召唤先祖之魂的治疗者，使用水之净化能量来治愈盟友的创伤，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[3638]="怨恨的阿格希尔德"
D.LocalClientValues[3639]="训犬师苏沃克"
D.LocalClientValues[3640]="通天峰的黄金殿堂"
D.LocalClientValues[3641]="为了联盟的荣耀，干掉部落的敌人！"
D.LocalClientValues[3642]="赛法努斯"
D.LocalClientValues[3643]="制空权"
D.LocalClientValues[3644]="针锋相对"
D.LocalClientValues[3645]="阿苏纳的海狮占据了大部分可栖息的海岸线，把其他动物都赶走了。赶走拉文达斯，其他海狮也会跟随而去。"
D.LocalClientValues[3646]="食魂者泰兰特"
D.LocalClientValues[3647]="军团必败"
D.LocalClientValues[3648]="瑞瓦塔丝夫人"
D.LocalClientValues[3649]="这些驱逐舰打算去攻击钢铁码头附近的一座嘲颅村庄。那是我们对抗钢铁部落的前线阵地，我们决不能失去它。"
D.LocalClientValues[3650]="隔绝之海"
D.LocalClientValues[3651]="潮爪"
D.LocalClientValues[3652]="|cFFFFD200职业：|r死亡骑士|n|n|cFFFFD200任务：|r我心永向黑锋骑士团|n|n|cFFFFD200地区：|r阿苏纳"
D.LocalClientValues[3653]="|cFFFFD200职业：|r恶魔猎手|n|n|cFFFFD200任务：|r提拔勇士|n|n|cFFFFD200地区：|r邪能之槌号"
D.LocalClientValues[3654]="末日领主瓦兹克"
D.LocalClientValues[3655]="北边出现了雷神狩猎小队的踪影。我们要在悬崖那里设下埋伏，让他们看看真正部落的实力！"
D.LocalClientValues[3656]="奥术弹幕"
D.LocalClientValues[3657]="神器 - 德鲁伊任务"
D.LocalClientValues[3658]="炉渣矿井里的奴隶已经准备起义了。去帮帮他们，顺便问问他们最近有没有挖到什么强大的圣物。谨慎行事。"
D.LocalClientValues[3659]="这些混蛋一直在跟我们的部队捉迷藏，不断偷袭，躲避反击。这不但会造成伤亡，更会打击士气。"
D.LocalClientValues[3660]="法力吸取"
D.LocalClientValues[3661]="快速用脚踢目标，应对|C00b3ffff法术|R。"
D.LocalClientValues[3662]="梦境林地的守护者都是从小招募和训练的。他们远离家人，与林地本身产生了紧密的联系。只要有任何威胁靠近林地，都会让他们感受到切肤之痛。"
D.LocalClientValues[3663]="爆炸陷阱"
D.LocalClientValues[3664]="让偶尔抓到的盗贼缴纳罚款或者提供有用情报来赎罪。"
D.LocalClientValues[3665]="热辣的远征"
D.LocalClientValues[3666]="说服老扬希"
D.LocalClientValues[3667]="至高岭牛头人请求我们提供帮助，保护他们的边界不受邪能图腾的侵害。作为回报，他们的仪祭师会给我们提供强力的药水。"
D.LocalClientValues[3668]="导师"
D.LocalClientValues[3669]="阻止围攻"
D.LocalClientValues[3670]="刀塔占卜师"
D.LocalClientValues[3671]="牧羊人卡沃斯"
D.LocalClientValues[3672]="一潭死水"
D.LocalClientValues[3673]="采矿"
D.LocalClientValues[3674]="降低成功機率。"
D.LocalClientValues[3675]="缚魂者尼娅米"
D.LocalClientValues[3676]="钢铁部落的火炮部队正驻扎在战栗壕沟上方的山脊上。这个威胁已经再清楚不过了！"
D.LocalClientValues[3677]="执行任务时有几率带回治疗之泉图腾，用于为部队回复1点活力。"
D.LocalClientValues[3678]="鲁尔夫·断骨"
D.LocalClientValues[3679]="格里伏塔"
D.LocalClientValues[3680]="堕落者"
D.LocalClientValues[3681]="只要采集到足够的元素样本，我们就不用再打扰纳格兰的元素生物了。"
D.LocalClientValues[3682]="死亡也无法让阿苏纳的灵魂得到安息。邪恶的吉拉摩尔培养了一群幽灵法师。阻止她，让那些灵魂安息吧。"
D.LocalClientValues[3683]="投掷利刃"
D.LocalClientValues[3684]="沉船海湾的沼岩鱼人长久以来一直会从沉船中捕获幸存者，然后将他们拖回到自己的村庄。"
D.LocalClientValues[3685]="老练的生存专家"
D.LocalClientValues[3686]="钢铁部落的攻城武器在远处很有威力，可一旦靠近就破绽百出。派出一支精英小队去破坏他们的军备或许是个明智的方法。"
D.LocalClientValues[3687]="噢，废物！"
D.LocalClientValues[3688]="沼岩泽地行者大军"
D.LocalClientValues[3689]="奥术内爆"
D.LocalClientValues[3690]="为了帮助哈顿，我们的勇士必须有精良的装备。命令他们去搜索克罗库恩，寻找合适的装备吧。"
D.LocalClientValues[3691]="道路风险"
