D.LocalClientValues[3706]="成功完成任务有几率带回一件勇士武器或装备。"
D.LocalClientValues[3707]="|cFFFFD200职业：|r德鲁伊|n|n|cFFFFD200任务：|r|n|n|cFFFFD200地区：|r"
