D.LocalClientValues[3773]="石槌守卫"
D.LocalClientValues[3774]="血槌食人魔开始袭击部落的岗哨了。我们损失了许多士兵和补给。我们认为，这都是他们的新督军造成的。"
D.LocalClientValues[3775]="对荒野了如指掌，能够驯服多种多样的野兽协助作战，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[3776]="侏儒船员"
D.LocalClientValues[3777]="我们在山底扎营，但这里是凶猛的双头怪的家园。在上山之前，我们必须得赶走他们。"
D.LocalClientValues[3778]="雅努"
D.LocalClientValues[3779]="雷神兽人越来越大胆了：他们的斥候竟敢大摇大摆地跟踪部落的队伍。对于这种傲慢的行为，我们要坚决予以回击。"
D.LocalClientValues[3780]="邪能流星"
D.LocalClientValues[3781]="秘法会传说"
D.LocalClientValues[3782]="一地鸦毛"
D.LocalClientValues[3783]="刀叶"
D.LocalClientValues[3784]="迷失者提普托格"
D.LocalClientValues[3785]="邪恶魔犬"
D.LocalClientValues[3786]="我们的敌人吹嘘说他们在钢铁码头内的巨舰是永不沉没的。这箱闪闪发亮的全新爆盐炸弹会让他们明白自己错得有多离谱。"
D.LocalClientValues[3787]="畜棚可以捕捉动物，为要塞提供皮革、鲜肉和毛皮。"
