D.LocalClientValues[3790]="黑锋圣物"
D.LocalClientValues[3791]="暗夜的祝福"
D.LocalClientValues[3792]="羽鬃最近正在被猎杀。一只名叫劳伦的唱歌鹰头猫一直试图把羽鬃赶走。"
D.LocalClientValues[3793]="不死族遭遇戰1"
D.LocalClientValues[3794]="鬼母法崔达"
D.LocalClientValues[3795]="危险的平原"
D.LocalClientValues[3796]="黑锋勇士"
D.LocalClientValues[3797]="我们的斥候报告说，维库人已经获得了一箱流明石武器，准备将它们熔铸，为他们的幼龙打造护甲。"
D.LocalClientValues[3798]="无奸不商"
D.LocalClientValues[3799]="神圣命运"
D.LocalClientValues[3800]="神圣恳求"
D.LocalClientValues[3801]="神圣之星"
