D.LocalClientValues[3804]="噩梦"
D.LocalClientValues[3805]="既然你已经进入了俱乐部，你的勇士也应该有资格参加比赛，这样才算公平。"
D.LocalClientValues[3806]="信徒飞翼卫士"
