D.LocalClientValues[3808]="|cFFFFD200任务：|r好啦！|n|cFFFFD200地区：|r塔拉多|n"
D.LocalClientValues[3809]="这里的血槌食人魔和他们的独眼魔主子生活在一起。后者正日夜用巨石锤打大地。总之，这会是一个不错的度假休闲之所。"
D.LocalClientValues[3810]="喷发"
D.LocalClientValues[3811]="征募官乐娜拉"
D.LocalClientValues[3812]="魔咒"
D.LocalClientValues[3813]="最后一座矿坑，可开启富矿矿点。此外，要塞守卫会巡视矿井，确保它不被敌对的鬣蜥人破坏。并允许同时接受最多21份产品订单。"
D.LocalClientValues[3814]="部落精锐战列舰"
D.LocalClientValues[3815]="邪恶计谋"
D.LocalClientValues[3816]="瓦拉加尔唤雷者"
D.LocalClientValues[3817]="陈的友情"
D.LocalClientValues[3818]="在邪火军械库工作的虫语者工程师很容易就会被财宝引诱。好好利用这一点。"
D.LocalClientValues[3819]="精锐打击：失落的神殿"
D.LocalClientValues[3820]="可怕的虚空生物正源源不断地从墓地的裂口处涌出。裂口下面可能还会有一些值钱的东西。"
D.LocalClientValues[3821]="暗野亵渎者"
D.LocalClientValues[3822]="副官忒利厄斯"
D.LocalClientValues[3823]="要担心的不仅仅是至高岭的道路，在你不注意的时候，最大的危险就会降临。"
D.LocalClientValues[3824]="小鬼淤泥"
D.LocalClientValues[3825]="一个古老而危险的物种。"
