D.LocalClientValues[3839]="由潜行者施放，可避免严重的伤害。"
D.LocalClientValues[3840]="白日恐惧"
D.LocalClientValues[3841]="骑手萨拉纳尔需要瑞文戴尔曾经的坐骑死亡战马的鞍座。自从他被击败后，鞍座被送回了斯坦索姆。"
D.LocalClientValues[3842]="沁影追猎者之心"
D.LocalClientValues[3843]="我们在基地附近发现了一艘部落潜水艇。快派出你的新型驱逐舰击沉它吧。"
