D.LocalClientValues[3856]="一鸟在手"
D.LocalClientValues[3857]="碎手氏族的部队刚刚派出了这些船只，头也不回地冲进了暴风雨中。他们的鲁莽对我们来说可是好事。"
D.LocalClientValues[3858]="白鬼审讯者"
D.LocalClientValues[3859]="凝结虚空"
D.LocalClientValues[3860]="夺宝奇兵"
D.LocalClientValues[3861]="巡逻"
D.LocalClientValues[3862]="水产品"
D.LocalClientValues[3863]="尖啸的森林"
D.LocalClientValues[3864]="大幅提高任务成功率。"
D.LocalClientValues[3865]="注邪军团雕像"
D.LocalClientValues[3866]="你的斥候报告说我们在影月谷的部队需要支援。"
D.LocalClientValues[3867]="久经沙场的战斗大师，擅使双手武器，利用灵活的移动和压制性的攻击来摧垮敌人，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[3868]="古代召焰者的陪伴"
D.LocalClientValues[3869]="我们的要塞需要物资，所以又到收获的时候了。去善意提醒一下这棵野蛮的植物和它的爪牙，让它们知道为什么我们才是食物链的顶端。"
D.LocalClientValues[3870]="怒火释放"
D.LocalClientValues[3871]="木精守望者"
D.LocalClientValues[3872]="任务时间缩短50%。"
D.LocalClientValues[3873]="尼索格"
D.LocalClientValues[3874]="允许生产附魔物品，并可以让非附魔专业的玩家分解物品，并可接受产品订单。"
D.LocalClientValues[3875]="贝恩的复仇号"
D.LocalClientValues[3876]="一簇金色风暴乌鸦的羽绒，能将追随者的移动速度提升到史诗级别。"
D.LocalClientValues[3877]="实验厨房成果"
