D.LocalClientValues[3883]="|cFFFFD200职业：|r牧师|n|n|cFFFFD200任务：|r|n|n|cFFFFD200地区：|r"
D.LocalClientValues[3884]="|cFFFFD200任务：|r奇娅娜·月影|n|cFFFFD200地区：|r影月谷"
D.LocalClientValues[3885]="附魔研究室可以制造用于附魔的魔法材料以及实用的附魔产品。"
D.LocalClientValues[3886]="塔底的秘密"
D.LocalClientValues[3887]="遵循白虎之道的大师们迅捷而沉着，拥有无人能及的力量与耐心。他们驾驭内在的力量服务他人。"
D.LocalClientValues[3888]="监狱"
D.LocalClientValues[3889]="集合织梦者：塔尔扎"
D.LocalClientValues[3890]="阿莱利要你派出部队，侦查位于苏拉玛的邪魂堡垒。到了那里以后，他们要找到可能的俘虏目标。"
D.LocalClientValues[3891]="炎夏将至"
D.LocalClientValues[3892]="迪菲亚传承"
D.LocalClientValues[3893]="熔渣车间"
D.LocalClientValues[3894]="分选者泰瑞克在石化森林搜捕克罗库驯兽师。快去终结他的暴行。"
D.LocalClientValues[3895]="放贷者号"
D.LocalClientValues[3896]="想要吸引更多的恶棍、盗贼和其他各色歹徒，你需要给洛妮卡·静刃提供一个她无法拒绝的提议。派梵妮莎·范克里夫前往吧。"
D.LocalClientValues[3897]="在上古海滩上，巨大的海龟在古代废墟中四处游荡。他们的肉可以为我们的部队提供大量补给。对了，要小心纳迦。"
D.LocalClientValues[3898]="拳击"
D.LocalClientValues[3899]="提高这个区域的任务成功几率。"
D.LocalClientValues[3900]="要塞物资"
D.LocalClientValues[3901]="大法师瓦格斯的旅行：泰安诺的学者"
D.LocalClientValues[3902]="释放地狱火"
D.LocalClientValues[3903]="解锁奖励大量要塞资源的任务。"
D.LocalClientValues[3904]="阿苏纳的术士们又开始行动了，召唤一些他们根本无力控制的恶魔。我们不能总是这样以火攻火。"
D.LocalClientValues[3905]="变形为致命的猎豹形态，利用撕咬和流血造成大量伤害，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[3906]="焦翼喷邪蝠"
D.LocalClientValues[3907]="磐牛式"
D.LocalClientValues[3908]="我们追踪蔑潮的踪迹一路追到了勇者之门附近一座戒备森业的庞大营地。找到任何与被绑架的囚徒有关的消息。"
D.LocalClientValues[3909]="钢铁切割者"
D.LocalClientValues[3910]="啮岩碎石者"
D.LocalClientValues[3911]="踏风武僧"
D.LocalClientValues[3912]="疯狂的伊德拉"
D.LocalClientValues[3913]="瓦尔莎拉南部的纳迦们使用的武器是由流明石锻造而成。我们必须说服纳迦放弃那些武器。"
D.LocalClientValues[3914]="邪能散播器"
D.LocalClientValues[3915]="超脱"
D.LocalClientValues[3916]="灵牙"
D.LocalClientValues[3917]="灵魂链接"
D.LocalClientValues[3918]="在这种糟糕的天气下，地狱咆哮还派出潜艇来骚扰我们的舰队。我们应该果断出击，决不能让他们有重见天日的机会。"
D.LocalClientValues[3919]="我们在基地附近发现了一艘联盟潜水艇。快派出你的新型驱逐舰击沉它吧。"
D.LocalClientValues[3920]="我们的勇士可以把燃烧军团牵制在漆黑峡谷。别让他们通过。"
D.LocalClientValues[3921]="艾克西安的碎片"
D.LocalClientValues[3922]="执行任务时有几率带回灵魂残片，用于为部队回复1点活力。"
D.LocalClientValues[3923]="马迪亚斯被关押的地方不停变化。迪瑟洛克是个很聪明的恐惧魔王。种种线索都在指向黑鸦堡垒。真可惜，你们之前都没发现他。"
D.LocalClientValues[3924]="你怕黑吗？"
D.LocalClientValues[3925]="碎手兽人享受痛苦，因为他们认为这能增强他们的力量。那就让他们变得空前强大，然后死得不能再死吧。"
D.LocalClientValues[3926]="刃月原祖荆兽"
D.LocalClientValues[3927]="打断施法，应对|C00b3ffff法术|R。"
D.LocalClientValues[3928]="指挥中心报告说，失落的神殿地下有一个收藏古代卷轴的图书馆。只有你最精锐的勇士和部队才有可能抓住这个机会。"
D.LocalClientValues[3929]="铁城港"
D.LocalClientValues[3930]="骨园暴食者"
D.LocalClientValues[3931]="宝贝儿，你的钱归我了"
D.LocalClientValues[3932]="由讨厌的小鬼施放，可移除一个有害魔法效果。"
D.LocalClientValues[3933]="|cFFFFD200职业：|r德鲁伊|n|n|cFFFFD200任务：|r崛起吧，勇士|n|n|cFFFFD200地区：|r德鲁伊战役"
D.LocalClientValues[3934]="莫尔葛碾压者"
D.LocalClientValues[3935]="从燃烧军团那里缴获的武器可以熔铸成圣光道具。去把敌人的军械库洗劫一空吧。"
D.LocalClientValues[3936]="德拉诺的深海见证过无数死亡以及珍贵而短暂的安宁。这艘船和它的船员注定要在大海上永世徘徊。"
D.LocalClientValues[3937]="法罗纳尔的恶魔已经把影响力扩散到了阿苏纳的深处，腐蚀一切能腐蚀的目标。搜索并消灭任何受到军团腐蚀的目标。"
D.LocalClientValues[3938]="御风卡利鸟"
D.LocalClientValues[3939]="必须阻止幽影谷的影卫虚灵。派勇士去阻止他们的仪式吧。"
D.LocalClientValues[3940]="你可以下达一个战争号角的工作订单，使用后可释放一个瓦格里先锋，立即完成你地图上的一个非精英类世界任务。每18个小时可以使用一次。"
D.LocalClientValues[3941]="蔑潮斧枪兵"
D.LocalClientValues[3942]="随意开火"
D.LocalClientValues[3943]="钢铁部落在戈尔隆德建造了一座港口，他们称其为钢铁码头。去让我们的敌人瞧瞧，他们所吹嘘的“钢铁”是多么不堪一击吧。"
