D.LocalClientValues[3957]="提高战胜畸变怪和亡灵的几率。"
D.LocalClientValues[3958]="加速"
D.LocalClientValues[3959]="邪能图腾破城者"
D.LocalClientValues[3960]="我们的前沿岗哨绘制了新的图纸并制造了一艘舰船样品。派出你的运输舰把东西运回来吧。"
D.LocalClientValues[3961]="伊利达雷恶魔猎手接受了恶魔之力，为了更有效地猎杀燃烧军团的恶魔，他们牺牲了原本的精灵外貌。"
