D.LocalClientValues[3973]="危险区域"
D.LocalClientValues[3974]="一位奥拉基尔从前的军官已经站在燃烧军团一边。必须阻止这位名为阿拉克里斯的军官，防止他在天空之墙内部发动叛乱。"
