D.LocalClientValues[3978]="生产一批弹簧齿轮。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n当建筑达到2级或以上时，你可以通过建筑设计桌指派一名追随者在其中工作，以提高产量。"
D.LocalClientValues[3979]="攻破钢铁部落的封锁线，将他们赶出南海，获取纳格兰的原生资源。"
D.LocalClientValues[3980]="允许你捕捉裂蹄牛、雷象、狼和塔布羊，获取制皮和裁缝配方所需的皮革和毛皮。"
D.LocalClientValues[3981]="树妖是塞纳留斯的女儿，同时具有精灵与神鹿的血统。她们在和平年代开朗温柔，但若有谁敢破坏自然，她们会毫不留情地将其猎杀。"
