D.LocalClientValues[4012]="冰冠冰川"
D.LocalClientValues[4013]="想当年……"
D.LocalClientValues[4014]="我们的炼金师发现鸦人羽毛分泌出的油脂很有用处。尽力去多收集一些来吧——无论你采用什么手段都行。"
