D.LocalClientValues[4045]="辛利"
D.LocalClientValues[4046]="亮晶晶！"
D.LocalClientValues[4047]="奥秘学宫里流淌着能量，死去的奥古雷启迪者还在施放着魔法，必须清除他们。"
D.LocalClientValues[4048]="要想攻下被钢铁部落占领的黑石塔，我们必须解决那些龙人和始祖龙。它们神秘的饲养者也得死。"
