D.LocalClientValues[4067]="这艘船上装满了给联盟在泽库尔的战士配备的皮甲。好皮子可不能浪费在他们身上。他们更适合蕾丝，对吧？"
D.LocalClientValues[4068]="开饭了"
D.LocalClientValues[4069]="古尔丹已派出反潜舰船来破坏你的行动。把它们引到陷阱里去！"
D.LocalClientValues[4070]="弗蕾亚之泉：山丘"
D.LocalClientValues[4071]="高里亚奥术师"
D.LocalClientValues[4072]="有传言说，一个白鬼兽人热衷于伏击所有毫无防备的旅人，夺走他们身上所有亮晶晶的东西。你或许能在西南边的洞穴里找到他。"
