D.LocalClientValues[4074]="邪能之河"
D.LocalClientValues[4075]="地面目标"
D.LocalClientValues[4076]="有很多路都能通往至高岭山中巨大的洞穴，但有些尤为危险。去进行探索，看看里面是否会有更好的路径。"
D.LocalClientValues[4077]="大法师瓦格斯的旅行：灰谷的森林"
D.LocalClientValues[4078]="据说，恶魔丹塔利纳克斯能吸干凡人心中所有的希望。必须让我们的部队消灭他。"
D.LocalClientValues[4079]="闪电之盾"
D.LocalClientValues[4080]="肃霜食人魔会定期掠夺霜狼兽人，并将战利品作为祭品献给吞噬者布罗克。让我们拿回他们偷走的东西吧。"
