D.LocalClientValues[4096]="荆棘"
D.LocalClientValues[4097]="啸魂者"
D.LocalClientValues[4098]="前往燃烧裂口，试探一下燃烧军团的防线。"
D.LocalClientValues[4099]="魔环"
D.LocalClientValues[4100]="自从燃烧军团入侵以来，艾泽拉斯各地的牧师都一直在前线为我们的盟友提供救助。是时候派人过去减轻他们的压力了。"
D.LocalClientValues[4101]="苍白的卡拉"
D.LocalClientValues[4102]="使用混乱魔法的大师，能够降下灾厄的烈焰，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[4103]="白水台风元素"
D.LocalClientValues[4104]="战列舰克制驱逐舰，航母克制战列舰，潜水艇克制航母，而驱逐舰又克制潜水艇。因此，技战术将成为这场战斗的决定因素。"
D.LocalClientValues[4105]="大卫·环球"
D.LocalClientValues[4106]="每个人都知道海巨人会带来海难，但有一个海巨人做得过头了。他会把所有船只拉到多岩的阿苏纳海滩。"
