D.LocalClientValues[4127]="邪恶阴谋"
D.LocalClientValues[4128]="燃烧军团会从纳斯拉克斯要塞送出物资，穿过漆黑峡谷，最后送往破碎之野。快去收缴他们的下一批货物，或者干脆毁掉。"
