D.LocalClientValues[4392]="7.0 职业大厅 - 宝藏任务"
D.LocalClientValues[4393]="瓦尔基拉会挑选最强大的女武神为泰坦监护者艾尔效力。如果瓦尔基拉女武神英勇战死，则将会被选为传说的瓦格里。"
D.LocalClientValues[4394]="降低购买建筑和更改专精的成本。"
