D.LocalClientValues[4399]="污染者卡迪洛斯"
D.LocalClientValues[4400]="传说驻扎在洛克拉斯的战歌氏族收藏了一种奇怪的货币。它或许具有重大的历史意义。"
D.LocalClientValues[4401]="征调大量恶魔卫士为你执行任务。\r\n\r\n|cFFFFD200建造时间：1小时|r"
D.LocalClientValues[4402]="苍白的捕食者"
D.LocalClientValues[4403]="湮灭级战列舰"
D.LocalClientValues[4404]="虫语搜亡者"
D.LocalClientValues[4405]="萨尼恩"
D.LocalClientValues[4406]="钢铁部落重型巡逻队"
D.LocalClientValues[4407]="允许你捕捉野猪和淡水兽，获取制作强力食品的稀有肉类。"
D.LocalClientValues[4408]="火焰之地余烬"
D.LocalClientValues[4409]="有传言称，一群洗劫了某个流亡者小屋的强盗得到了一张有趣的地图。趁他们还没回到通天峰，快去拦下这些鸦人吧！"
D.LocalClientValues[4410]="狂热者"
D.LocalClientValues[4411]="沃尔蒂萨、贝加里斯塔兹和伊特努斯不愿亲自返回魔环。不过，只要我们扫清道路，他们最强大的一些幼龙就会来帮我们。"
D.LocalClientValues[4412]="几十年来，堕暗岭一直是一片安稳的定居地。只要打跑燃烧军团，你就能在那找到工具和补给。"
D.LocalClientValues[4413]="清道夫岗哨里充斥着寻找珍贵物资的虫语者。我们要抢在他们前面。"
D.LocalClientValues[4414]="塔纳安海峡"
D.LocalClientValues[4415]="影月暗法师"
D.LocalClientValues[4416]="为了训练破碎者战士来应对新的燃烧军团，战争领主加尔顿要你去收集恶魔的工具。"
D.LocalClientValues[4417]="堕落的古树"
D.LocalClientValues[4418]="敌人的力量"
D.LocalClientValues[4419]="她的邪恶"
D.LocalClientValues[4420]="钢铁狂潮号"
D.LocalClientValues[4421]="夜之子正在把一大批流明石运到城墙的后方。在黑暗的掩护下发动攻击，为我们夺回那些金属！"
D.LocalClientValues[4422]="由武僧施放，可显著提高爆发性伤害。味道也非常不错。"
D.LocalClientValues[4423]="兽人死亡骑士"
D.LocalClientValues[4424]="危险的有害效果，需要被驱散。"
D.LocalClientValues[4425]="疯疯癫癫的魔荚人偷走了我们的一箱增长药剂。在这些怪物喝下药水并开始发疯前，快去夺回它们。"
D.LocalClientValues[4426]="该任务涉及珠宝加工专业。"
D.LocalClientValues[4427]="防护骑士披萨店"
D.LocalClientValues[4428]="军团大举入侵阿苏纳！我们需要立即派出援军对抗这一威胁。"
D.LocalClientValues[4429]="开始召唤瓦格里，你可以把她们部署出去，完成一个世界任务。"
D.LocalClientValues[4430]="由猎人施放，可迫使敌人攻击其他目标。"
D.LocalClientValues[4431]="暗影猎手艾瑞库斯"
D.LocalClientValues[4432]="堕落之书"
D.LocalClientValues[4433]="酋长哈顿请求你取回藏在堕暗岭的物资。作为报答，克罗库山岭猎手会帮助你的军队摸清阿古斯的荒凉地貌。"
D.LocalClientValues[4434]="霜壁走廊"
D.LocalClientValues[4435]="乌合之众"
D.LocalClientValues[4436]="一个首领，法术和危害。"
D.LocalClientValues[4437]="我们已经招募了一些部队，可以用来为勇士提供增援。多余的部队能让我们解救一名被俘虏的囚犯。"
D.LocalClientValues[4438]="黑爪"
D.LocalClientValues[4439]="天降横财"
D.LocalClientValues[4440]="浓雾"
D.LocalClientValues[4441]="恶魔们遗留的流明石武器散布在破碎海滩各处。如果我们动作快点，还可以回收那些武器。"
D.LocalClientValues[4442]="奥术法师"
D.LocalClientValues[4443]="打破枷锁"
D.LocalClientValues[4444]="奥术陷阱"
D.LocalClientValues[4445]="成功完成任务有几率带回一件物品，可以召唤强力部队库斯卡蛮兵。"
