D.LocalClientValues[4459]="险境：阿什兰"
D.LocalClientValues[4460]="混淆视听：阿苏纳"
D.LocalClientValues[4461]="恐轨车站的效率全靠那些地精和兽人监工维持。杀了他们，你就摧毁了它向远方的营地运输武器的能力。"
D.LocalClientValues[4462]="无数恶魔正从污染小径鱼贯而出，向我们的堡垒进军。挡住这如潮的恶魔。"
D.LocalClientValues[4463]="毁灭术士"
D.LocalClientValues[4464]="冥狱来客"
D.LocalClientValues[4465]="魔鳞蜥蜴被赶出了巢穴，他们的石化凝视会把任何人变成石头，也包括野生生物。"
D.LocalClientValues[4466]="灵体形态"
D.LocalClientValues[4467]="铁枝"
D.LocalClientValues[4468]="地下城"
D.LocalClientValues[4469]="要摆脱军情七处的追踪，我们得演出戏。先从我们的大法师卡德加开始吧。"
D.LocalClientValues[4470]="割颅者"
D.LocalClientValues[4471]="暗魔劫掠者"
D.LocalClientValues[4472]="戈隆伐树者"
D.LocalClientValues[4473]="他们肯定挡不住的。他们会知道我们的计划。钢铁部落会以为我们在痴心妄想，但这只是一次破坏行动。"
D.LocalClientValues[4474]="废灵者达库尔已经躲藏得够久了。是时候将他绳之以法，彻底解决这个破魔者了。"
