D.LocalClientValues[4479]="一只海怪正瑟缩地漂浮在海面上，周围是钢铁部落的舰队。快去把它从钢铁部落的魔爪中救出来，它或许会愿意帮助我们。"
D.LocalClientValues[4480]="你可以下达一个白银之手的工作订单，使用后可以释放白银之手先锋，立即完成你地图上的一个非精英类世界任务。每18个小时可以使用一次。"
