D.LocalClientValues[4577]="一辆钢铁部落的巨型油罐车就停在北边的铁路桥旁。去打开油罐，放点炸药进去吧。轰！"
D.LocalClientValues[4578]="斯库瓦克斯"
D.LocalClientValues[4579]="作为一艘布雷舰，这艘舰船会在身后布下大量水雷，令追踪变得危机四伏。"
D.LocalClientValues[4580]="强力气流"
