D.LocalClientValues[4582]="克罗库山岭猎手"
D.LocalClientValues[4583]="这些高大的恶魔女祭司俯视战场，用六条手臂挥舞长剑，在敌阵中杀出一条血路。在面对这些怪物时，对于战斗稍有概念的人都该懂得放弃。"
