D.LocalClientValues[4588]="亡灵牧师"
D.LocalClientValues[4589]="几个光铸装甲驾驶员被困在了破碎之野的敌军后方，一定要救出他们。"
D.LocalClientValues[4590]="地精潜行者"
D.LocalClientValues[4591]="虚空风暴肯定是从某处刮来的。快乘上小船，驶向东北方，并想办法带点好东西回来。"
D.LocalClientValues[4592]="邪火欺诈者"
D.LocalClientValues[4593]="哈尔弗丹"
D.LocalClientValues[4594]="由牧师施放，可治疗一群盟友。"
D.LocalClientValues[4595]="钢铁部落的帐篷都是用结实的皮革制成的。我们可以把它们做成优质的皮甲。"
D.LocalClientValues[4596]="奥古雷审查官之杖"
D.LocalClientValues[4597]="魔荚背刺者"
D.LocalClientValues[4598]="能够发动空中打击。"
D.LocalClientValues[4599]="大领主的命令：宿敌"
D.LocalClientValues[4600]="有些魔导师已经闻不到永茂林地的玫瑰花香了。喔唷。如果我们动作快点，或许还能拯救几个。"
D.LocalClientValues[4601]="鱼鳞天平"
D.LocalClientValues[4602]="酒仙武僧"
D.LocalClientValues[4603]="邪能图腾缚血者"
D.LocalClientValues[4604]="忠诚的管家"
D.LocalClientValues[4605]="暗影议会占据了要塞西边纵横交错的洞穴网络。我们不能让它在这一区域站稳脚跟！"
D.LocalClientValues[4606]="艾默松"
D.LocalClientValues[4607]="黑锋骑士由巫妖王亲自复活，他们存在的目的只有一个：杀戮或死亡。"
D.LocalClientValues[4608]="这些训练有素的卫兵曾发誓保护肯瑞托，是战场上不容忽视的可怕力量。他们能够极其精准地对敌方阵列发动强大的协同攻击。"
D.LocalClientValues[4609]="暗影议会的强盗们一直在洗劫圣光之墓里的奥金尼墓穴。"
D.LocalClientValues[4610]="伪酱油党……"
D.LocalClientValues[4611]="丛林之王"
D.LocalClientValues[4612]="集合织梦者：格拉哈姆·银爪"
D.LocalClientValues[4613]="我们已经招募了一些部队，可以用来为我们的事业添砖加瓦。这样我们可以去一个效忠海拉的村庄，解救那里的一名囚犯。"
D.LocalClientValues[4614]="掠食者成灾"
D.LocalClientValues[4615]="先祖传说"
D.LocalClientValues[4616]="使用强大的自然法术治愈盟友，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[4617]="魔力风暴"
D.LocalClientValues[4618]="弗鲁菲顿博士"
D.LocalClientValues[4619]="狂缚首领"
D.LocalClientValues[4620]="神器 - 猎人任务"
D.LocalClientValues[4621]="邪能装备"
D.LocalClientValues[4622]="死去的恐惧魔王，污染者拉瑟莱克回到了这个世界。奇怪的是，有时候他会四处晃荡，杀死其他的恶魔。"
D.LocalClientValues[4623]="废土行者"
D.LocalClientValues[4624]="马里恩·夜怒"
D.LocalClientValues[4625]="|cFFFFD200任务：|r考戈尔的斧子|n|cFFFFD200地区：|r戈尔隆德|n|n"
D.LocalClientValues[4626]="游击队员"
D.LocalClientValues[4627]="谣传并不存在，没有任何依据。"
D.LocalClientValues[4628]="在千光神殿中，远古的法师们以灵体和女妖的形态徘徊不去。杀死奥术师淡鹬，消灭她的上古召焰者。"
D.LocalClientValues[4629]="风暴使者瓦里亚卡"
D.LocalClientValues[4630]="阿古斯古董"
D.LocalClientValues[4631]="老练的空气萨满能够化身成为元素之力的导体，将身体包裹在狂怒的风暴中，化身为空气升腾者。"
D.LocalClientValues[4632]="邪能图腾偷猎集团"
D.LocalClientValues[4633]="我们已经对邪魂堡垒中军团目标观察了一段时间，是时候派出你最得力的人手去抓捕他们了。"
D.LocalClientValues[4634]="潜行者C部队"
D.LocalClientValues[4635]="医疗急救"
D.LocalClientValues[4636]="死木邪能法师"
D.LocalClientValues[4637]="鹰身人喜欢一切闪亮的东西，至高岭的天空女巫们偷走了容器的一块碎片。把它找回来，这样我们才能布置针对哈卡的陷阱。"
D.LocalClientValues[4638]="最周密的计划……"
D.LocalClientValues[4639]="两台巨型邪能火炮正在削弱维迪卡尔的护盾。快把它们干掉！"
D.LocalClientValues[4640]="一批元素符文已经被偷运到了钢铁军工厂。想要夺回它们无异于自杀。所以还是派你最讨厌的追随者去吧。"
D.LocalClientValues[4641]="炎鳞"
D.LocalClientValues[4642]="赫米特·奈辛瓦里会对它的脑袋非常感兴趣的。"
D.LocalClientValues[4643]="好事多磨"
D.LocalClientValues[4644]="鼠王"
D.LocalClientValues[4645]="该任务涉及工程学专业。"
D.LocalClientValues[4646]="“大嗓门”"
D.LocalClientValues[4647]="妖花汲命者"
D.LocalClientValues[4648]="|cFFFFD200任务：|r烈焰飞舞|n|cFFFFD200地区：|r阿兰卡峰林"
D.LocalClientValues[4649]="拥抱之颅"
D.LocalClientValues[4650]="突袭铸造厂，摧毁钢铁部落的战争机器。我们的部队在等候你的指令。"
D.LocalClientValues[4651]="奉献"
D.LocalClientValues[4652]="提高在丛林中赢得战斗的几率。"
D.LocalClientValues[4653]="克拉戈"
D.LocalClientValues[4654]="日常祷告"
D.LocalClientValues[4655]="无云之夜"
D.LocalClientValues[4656]="暗夜诅咒"
D.LocalClientValues[4657]="生产一批炼金催化剂。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n当建筑达到2级或以上时，你可以通过建筑设计桌指派一名追随者在其中工作，以提高产量。"
D.LocalClientValues[4658]="全知者萨纳里安"
D.LocalClientValues[4659]="贪婪的噬铁者"
D.LocalClientValues[4660]="虫爪鹰身人占据了影沼村，之前居住在那里的居民正在想方设法找回他们被偷走的贵重物品，同时也在寻求复仇。我们来把这两个问题都解决掉。"
D.LocalClientValues[4661]="酒吧老板考特尔"
D.LocalClientValues[4662]="赤翼钉刺者"
D.LocalClientValues[4663]="奥蕾莉亚发现了一个被遗忘艾瑞达军火库。我们应该派勇士去调查一下。"
D.LocalClientValues[4664]="邪能领主奥布利维昂"
D.LocalClientValues[4665]="|CFFFFFFF0法术|R\r\n若无法应对，高伤害法术会对部队造成越来越高的伤害。"
D.LocalClientValues[4666]="据说深岩之洲出现了新的威胁，而石母塞拉赞恩没有出现在元素领主的协商会议上。我们需要进行相关调查。"
D.LocalClientValues[4667]="要塞的战利品"
D.LocalClientValues[4668]="毁诺之地"
D.LocalClientValues[4669]="出现在这一海域的海怪可以让你在成功完成任务后获得埃匹希斯水晶。"
D.LocalClientValues[4670]="在冥狱深渊的深水中，有一只可怕的、名叫吸魂者的冥界鱿鱼，它会捕食任何踏入到这片水域中的不幸灵魂。消灭这条鱿鱼。"
D.LocalClientValues[4671]="重要囚犯"
D.LocalClientValues[4672]="启蒙圣契"
D.LocalClientValues[4673]="迎头痛击"
D.LocalClientValues[4674]="丛林之地"
D.LocalClientValues[4675]="强拆大队"
D.LocalClientValues[4676]="来自月花谷的坠月渡鸦攻击了我们的补给车队。我们必须保证物流通畅！"
D.LocalClientValues[4677]="势不可挡"
D.LocalClientValues[4678]="被奴役的能量"
D.LocalClientValues[4679]="蜥蜴的凝视"
D.LocalClientValues[4680]="绝对的力量造成绝对的堕落，因此我们必须消灭这个强大的术士。快派人去刺杀这个家伙吧。"
D.LocalClientValues[4681]="苦水袭击者"
D.LocalClientValues[4682]="守望者乔艾尔"
D.LocalClientValues[4683]="灭世级航母"
D.LocalClientValues[4684]="舰船-总攻（联盟）"
D.LocalClientValues[4685]="舰船-总攻（部落）"
D.LocalClientValues[4686]="每天可以使用一次风暴烈酒旅店中的冒泡的桶。\r\n\r\n从冒泡的桶喝酒可以获得宝贵的增益，协助你在破碎群岛完成任务。"
D.LocalClientValues[4687]="大量的敌人躲藏在瓦尔莎拉的森林中。"
D.LocalClientValues[4688]="即使最强大的德鲁伊也在沙拉尼尔的梦魇面前屈从了。利拉斯·月羽就是其中的一员，她曾经是平衡与和谐的化身。"
D.LocalClientValues[4689]="黑鸦堡垒的财物"
D.LocalClientValues[4690]="由萨满祭司施放，可打断施法。"
D.LocalClientValues[4691]="虽然狡猾的基拉斯曾打出过许多经典的伏击战，却因为沉迷赌博而声名狼藉。据说直到现在，他还是离不开纸牌和骰子。"
D.LocalClientValues[4692]="神器 - 战士任务"
D.LocalClientValues[4693]="|cFFFFD200成就：|r前有鸦后有虎"
