D.LocalClientValues[4700]="扰乱"
D.LocalClientValues[4701]="邪恶的吉拉摩尔"
D.LocalClientValues[4702]="德莱尼船员"
D.LocalClientValues[4703]="联合抗魔"
D.LocalClientValues[4704]="有一群偷猎者威胁着至高岭的野生动物们。让他们感受下被狩猎的滋味！"
D.LocalClientValues[4705]="毒血"
D.LocalClientValues[4706]="天神眷顾"
D.LocalClientValues[4707]="第一位通灵师萨泰尔挥舞着逆风收割者，在逆风小径夺取了无数生命，这也是那把神器名字的来源。在被深藏了几个世纪之后，有人发现乌萨勒斯在黑暗骑士的手上——必须找到他们的下落。"
D.LocalClientValues[4708]="黑石铸造厂会定期将新造好的火炮运往塔纳安，用以加固地狱火堡垒的防御。我们每击沉一艘运输舰，都能拯救数千条生命。"
D.LocalClientValues[4709]="钢铁部落驱逐舰"
D.LocalClientValues[4710]="破碎海滩的威胁"
D.LocalClientValues[4711]="大幅提高独自执行任务的成功率。"
D.LocalClientValues[4712]="大法师欧妮娅拉"
D.LocalClientValues[4713]="|cFFFFD200成就：|r想活命的话就跟我走|n|cFFFFD200地区：|r血槌炉渣矿井（英雄难度）"
D.LocalClientValues[4714]="魔核焚化者"
D.LocalClientValues[4715]="可以获得火焰领主、大地领主、风之领主和水之领主的帮助。每天会有一个随机的元素领主出现在你的职业大厅中，给你提供一个强大的战斗增益。"
