D.LocalClientValues[4717]="青铜龙军团的祝福"
D.LocalClientValues[4718]="由武僧施放，可移除一个有害魔法效果。"
D.LocalClientValues[4719]="弹药测试"
D.LocalClientValues[4720]="深渊魔王"
D.LocalClientValues[4721]="乌达罗格"
D.LocalClientValues[4722]="蔚蓝之光蓝宝石"
D.LocalClientValues[4723]="影爆"
D.LocalClientValues[4724]="刃拳氏族正在到处搜捕白鬼。我们怀疑他们和卡德加一样，也在寻找那些元素符文。"
D.LocalClientValues[4725]="能够在毫无预兆的情况下进行急转弯，这类目标很难击中。"
D.LocalClientValues[4726]="点燃术士周围的区域，应对|C00b3ffff爪牙|R。"
D.LocalClientValues[4727]="坠月船坞"
D.LocalClientValues[4728]="奥术起源"
D.LocalClientValues[4729]="拉文霍德公爵提供了相当数量的金币，引诱温斯顿·沃尔菲为无冕者效力。“孤狼”正呆在拉文霍德庄园中。"
D.LocalClientValues[4730]="疯狂之触"
D.LocalClientValues[4731]="达拉然的法师看上去值得信任……但真的如此吗？"
D.LocalClientValues[4732]="阿洛迪的圣杖黑檀之寒曾经是燃烧军团恶魔的克星。在阿洛迪从守护者的位置上退下来后，这把法杖传给了他的徒弟，并最终在时间的长河中失去了踪迹。也许除了阿洛迪本人，没人知道它现在的下落。"
D.LocalClientValues[4733]="邪魂的末日"
D.LocalClientValues[4734]="战争之矛钓鱼之旅"
D.LocalClientValues[4735]="白骨之盾"
D.LocalClientValues[4736]="一滴都不能洒"
D.LocalClientValues[4737]="燃烧恶徒"
D.LocalClientValues[4738]="驯犬者"
D.LocalClientValues[4739]="山脉之心"
D.LocalClientValues[4740]="审判官提沃斯"
D.LocalClientValues[4741]="图腾雷霆"
D.LocalClientValues[4742]="敌人之血：至高岭"
D.LocalClientValues[4743]="酒坊"
D.LocalClientValues[4744]="抚慰焦镜"
D.LocalClientValues[4745]="钢铁部落做的饭菜简直就是泔水，可难民们需要食物。去找到兽人的营地，偷走他们的干粮。最好再准备点薄荷。"
D.LocalClientValues[4746]="使坐骑在德拉诺的速度提高20%。"
D.LocalClientValues[4747]="石怒崖"
D.LocalClientValues[4748]="雷尔瓦将军正在终端船坞协调着燃烧军团的行动。去把他干掉。"
D.LocalClientValues[4749]="机械狂人"
D.LocalClientValues[4750]="无尽之海"
D.LocalClientValues[4751]="纳迦蛮兵"
D.LocalClientValues[4752]="我们得再次激怒那些戈隆。去杀掉当地的食肉动物，看看饥饿能不能让它们对附近的钢铁部落产生兴趣。"
D.LocalClientValues[4753]="邪脉叛逃者"
D.LocalClientValues[4754]="堕落梦魇"
D.LocalClientValues[4755]="唤醒亡者"
D.LocalClientValues[4756]="训练场"
D.LocalClientValues[4757]="这艘驶向暴风之盾的航母上满载着生力军和补给品。但从影月谷到阿什兰的航路可不短。"
D.LocalClientValues[4758]="复仇之怒"
D.LocalClientValues[4759]="夜之子已经渗透得太远了。必须不计一切代价阻止他们。"
D.LocalClientValues[4760]="增强萨满祭司"
D.LocalClientValues[4761]="去把运往邪火军械库的原材料拦截下来，带回维迪卡尔处理。"
D.LocalClientValues[4762]="营救游侠"
