D.LocalClientValues[4766]="自然传说"
D.LocalClientValues[4767]="清洁时间"
D.LocalClientValues[4768]="积怨深海歌者"
D.LocalClientValues[4769]="冰凉美味"
D.LocalClientValues[4770]="雪羽尖啸"
D.LocalClientValues[4771]="刃牙虎人正持续威胁我们在戈尔隆德的岗哨。让他们明白这个世界为什么不叫刃牙诺吧。"
D.LocalClientValues[4772]="联盟航母"
D.LocalClientValues[4773]="战歌唤地者"
D.LocalClientValues[4774]="极大提高任务成功率。"
D.LocalClientValues[4775]="冰翼双头飞龙主母"
D.LocalClientValues[4776]="邪魂堡垒正在制造大量的地狱火，速度之快远不是我们所能应对的。必须削减它们的数量，否则就要面对铺天盖地的地狱火雨了。"
D.LocalClientValues[4777]="解锁制皮任务，并允许同时接受最多21份产品订单。"
