D.LocalClientValues[4779]="但碎无妨"
D.LocalClientValues[4780]="危急时刻"
D.LocalClientValues[4781]="覆羽徘徊者"
D.LocalClientValues[4782]="玄牛高手擅长和对手打持久战，能拖垮大多数对手。倾尽全力保护弱者是他们的庄严使命。"
D.LocalClientValues[4783]="专业船长"
D.LocalClientValues[4784]="一队轰炸机，可以从空中实施打击。"
D.LocalClientValues[4785]="无敌斗士"
D.LocalClientValues[4786]="冷牙"
D.LocalClientValues[4787]="获得邀请"
D.LocalClientValues[4788]="战争之潮"
D.LocalClientValues[4789]="督军扎伊拉"
