D.LocalClientValues[4792]="烹饪大锅"
D.LocalClientValues[4793]="暗魔大军"
D.LocalClientValues[4794]="物归原主"
D.LocalClientValues[4795]="英勇号"
D.LocalClientValues[4796]="血帆海盗无论在海上还是陆地、无论清醒还是喝醉状态下都能战斗。他们的对手远远看到血红色的船帆时，通常就会吓得放弃抵抗直接投降。"
D.LocalClientValues[4797]="一去不回"
D.LocalClientValues[4798]="火焰之王的试炼"
D.LocalClientValues[4799]="在至高岭的山巅，一头独行的双头怪在给旅行者制造灾难。清除碾压者奥布多布。"
D.LocalClientValues[4800]="恶魔猎手可以释放自己的心魔，以击败最强大的对手。"
D.LocalClientValues[4801]="提高在沼泽中赢得战斗的几率。"
