D.LocalClientValues[4803]="威慑"
D.LocalClientValues[4804]="萬年青"
D.LocalClientValues[4805]="狂怒的厚皮母牛"
D.LocalClientValues[4806]="月光孢子蝠"
D.LocalClientValues[4807]="奇怪，我们的斥候说影月氏族的一座营地在夜里总是变得格外脆弱。你还以为他们会更习惯黑暗呢。"
D.LocalClientValues[4808]="森林受到威胁时，树木们变成树人保护家园。"
D.LocalClientValues[4809]="重生"
D.LocalClientValues[4810]="烧灼驱魔"
D.LocalClientValues[4811]="邪能之槌号的上一次全负荷作战已经是很多年前的事了。杰斯要求船上的所有人都去帮忙，进行必要的维修。"
D.LocalClientValues[4812]="清除恐惧之根中扭曲的守卫者。"
D.LocalClientValues[4813]="自然之力"
D.LocalClientValues[4814]="积怨者还有张王牌藏在袖子里——如果纳迦有袖子的话。他们还有一只巨大的生物，以供随时召唤。消灭贡尔扎。"
D.LocalClientValues[4815]="耐奥祖和他的同党逃入了氏族的墓地，这真是太方便了。这下他们连墓地都不用选了。"
