D.LocalClientValues[4839]="热砂保护协会的管理层要求肃清岩壁峡谷挖掘场里的食人魔，否则他们的工人就拒绝工作。如果我们肯帮忙，他们愿意分一部分收入给我们。"
D.LocalClientValues[4840]="雪盲台地的牛头人正在应对来犯的卓格巴尔。他们请求我们提供帮助，并表示可以提供住所作为交换。"
