D.LocalClientValues[4863]="泰克图斯，活体之山"
D.LocalClientValues[4864]="在梦魇到来之前，瓦尔莎拉的生物的秉性已经算是非常暴烈，现在腐蚀的能量让它们更具危险。"
D.LocalClientValues[4865]="毒语者大军"
D.LocalClientValues[4866]="冰川海湾"
D.LocalClientValues[4867]="巨额的财富反而导致了这艘驱逐舰的灭亡。船员们自相残杀，最后变成被诅咒的幽灵，再也没法花用他们拿命换来的黄金了。"
D.LocalClientValues[4868]="|cFFFFD200职业：|r德鲁伊|n|n|cFFFFD200任务：|r主母的命令|n|n|cFFFFD200地区：|r德鲁伊战役"
D.LocalClientValues[4869]="一只巨型岩虫正盘踞在戈尔隆德的海岸上，吞食当地的龙虾人。"
D.LocalClientValues[4870]="虽然已经有一半成了废墟，苏拉玛中潜藏的能量依然吸引着各类生物的到来。探索废墟，找到那些以这些能量为食的生物。"
D.LocalClientValues[4871]="狂野的魔蝠"
D.LocalClientValues[4872]="拆成碎片"
D.LocalClientValues[4873]="维库之魂"
D.LocalClientValues[4874]="恶魔猎手的盟友，由纳迦、破碎者甚至恶魔构成，他们会使用多种技能，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[4875]="王牌猎人"
D.LocalClientValues[4876]="一片污秽的区域，你最好别去。"
D.LocalClientValues[4877]="神圣圣骑士"
D.LocalClientValues[4878]="雪鬃村正在遭到攻击！快派援兵过去。"
D.LocalClientValues[4879]="看在仇恨的份上"
D.LocalClientValues[4880]="雷神勇士"
D.LocalClientValues[4881]="黑暗之影"
D.LocalClientValues[4882]="三叉攻击"
D.LocalClientValues[4883]="永恒法师"
D.LocalClientValues[4884]="休眠的守卫之熊"
D.LocalClientValues[4885]="在梦魇的边缘，萨特正在扩散他们的影响力，甚至已经来到了玛洛恩的庇护所门前。干掉他们的首领，狡猾的卡拉苏斯。"
D.LocalClientValues[4886]="夜之子名流"
D.LocalClientValues[4887]="部落航母"
D.LocalClientValues[4888]="武器走私"
D.LocalClientValues[4889]="魔刃打击"
D.LocalClientValues[4890]="|cFFFFD200职业：|r战士|n|n|cFFFFD200要塞任务：|r老兵|n|n|cFFFFD200地区：|r英灵殿"
D.LocalClientValues[4891]="心灵冰冻"
D.LocalClientValues[4892]="居然敢惹羊"
D.LocalClientValues[4893]="虚空生物。"
D.LocalClientValues[4894]="由萨满祭司施放，可同时伤害许多敌人。"
D.LocalClientValues[4895]="强壮的执行者"
D.LocalClientValues[4896]="人类战士"
D.LocalClientValues[4897]="守护者圣殿已经建好了，但我们还需要帮助。著名的元素召唤者大法师欧妮娅拉刚刚受到了攻击！"
D.LocalClientValues[4898]="影月墓地"
D.LocalClientValues[4899]="火焰法师"
D.LocalClientValues[4900]="偶遇"
D.LocalClientValues[4901]="允许生产锻造物品并接受产品订单。"
D.LocalClientValues[4902]="通缉：领巢者伊里克斯"
D.LocalClientValues[4903]="阿古斯老兵"
D.LocalClientValues[4904]="警戒步伐"
D.LocalClientValues[4905]="大锤的陨落"
D.LocalClientValues[4906]="我们的一位盟友认为，苏拉玛的一只巨型蟾蜍阿纳克斯会分泌一些非常有用的毒液。找到阿纳克斯，看看会有什么发现。"
D.LocalClientValues[4907]="战友"
D.LocalClientValues[4908]="艾尔提格之赐"
D.LocalClientValues[4909]="利瑟隆暗鳞兽"
D.LocalClientValues[4910]="血槌食人魔发现了一件强大的神器，他们的督军正在亲自监督发掘工作。去伏击那个督军，夺走神器。"
D.LocalClientValues[4911]="克罗库恩"
D.LocalClientValues[4912]="肃霜虐狼者"
D.LocalClientValues[4913]="一艘敌方战列舰偏离了航线，并不断释放出强大的魔力。这其中必有古怪。快去调查一下。最重要的是，把那种魔力弄回来。"
D.LocalClientValues[4914]="雪地里的亡灵"
D.LocalClientValues[4915]="|cFFFFD200职业：|r恶魔猎手|n|n|cFFFFD200任务：|r|n|n|cFFFFD200地区：|r邪能之槌号"
D.LocalClientValues[4916]="大法师阿鲁高的灵魂"
D.LocalClientValues[4917]="附近的一个洞穴被一只打盹的巨熊占领了。把这个洞穴清空，让我们自己可以在里面舒舒服服休息下。"
D.LocalClientValues[4918]="塔隆戈尔"
D.LocalClientValues[4919]="使用魔法护盾保护盟友不受伤害，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[4920]="萨格雷锢魂者"
D.LocalClientValues[4921]="急救"
D.LocalClientValues[4922]="苏拉玛啸狼群"
D.LocalClientValues[4923]="炽燃萨满"
D.LocalClientValues[4924]="这艘驱逐舰似乎是在远离陆地的海面上抛锚了。但我们的斥候报告说这只是假象：在这艘驱逐舰周围的水面下，还有一艘潜水艇在盘旋着。"
D.LocalClientValues[4925]="暴风之怒号"
D.LocalClientValues[4926]="可自动收获药圃中的草药。"
D.LocalClientValues[4927]="梦魇的部队靠近了一口神圣的月亮井。我们绝不能让它受到黑暗势力的污染。"
D.LocalClientValues[4928]="当你在德拉诺的野外区域时，非战斗状态下的恢复速度提高，并可以从你击败的敌方玩家身上收集到破碎骨骼（可换取胜利者的礼物）。"
D.LocalClientValues[4929]="弓箭手箭术高超，通常用来给步兵提供远程支援。集群的弓箭手能有效压制单个目标或成群的敌人。"
D.LocalClientValues[4930]="钢铁部落的部队已经登陆了丛林之心，威胁到了那里肥沃的土地和丰富的木材资源，以及那些强大的古树。它们已经非常愤怒了。"
D.LocalClientValues[4931]="混淆视听：风暴峡湾"
D.LocalClientValues[4932]="提高在沙漠中赢得战斗的几率。"
D.LocalClientValues[4933]="炉石锦标赛"
D.LocalClientValues[4934]="脆弱的忠诚"
D.LocalClientValues[4935]="袭击者的威胁"
D.LocalClientValues[4936]="战争大师布格索尔"
D.LocalClientValues[4937]="风行者之赐"
D.LocalClientValues[4938]="“疯王”斯波隆"
D.LocalClientValues[4939]="美好的夜晚"
D.LocalClientValues[4940]="调查深岩之洲"
D.LocalClientValues[4941]="持久耐力"
D.LocalClientValues[4942]="虽然熔岩采石场里鬣蜥人肆虐，但那里的铁矿石依然相当充足。可是那里的联盟渣滓也不少。别让那艘驱逐舰帮助他们霸占了那片区域。"
D.LocalClientValues[4943]="幸运女神"
D.LocalClientValues[4944]="燃烧之眼"
D.LocalClientValues[4945]="冰风雪原东面的肃霜食人魔竟敢公然虐待霜狼。这种行为决不能接受！"
D.LocalClientValues[4946]="黑暗侍僧"
D.LocalClientValues[4947]="|cFFFFD200地区：|r戈尔隆德"
D.LocalClientValues[4948]="勇士成功完成任务后有几率带回一张宝库赠品券。"
D.LocalClientValues[4949]="生不如死"
D.LocalClientValues[4950]="隐蔽斗篷"
D.LocalClientValues[4951]="对满级追随者使用"
D.LocalClientValues[4952]="漩涡乱流的出现毫无预兆，会对途径的任何船只造成毁灭性的破坏。"
D.LocalClientValues[4953]="德莱尼萨满祭司"
D.LocalClientValues[4954]="该任务涉及裁缝专业。"
D.LocalClientValues[4955]="攻击猎犬"
D.LocalClientValues[4956]="密林"
D.LocalClientValues[4957]="在苏拉玛，一个名叫赫萨·格里姆多迪的维库人战士一直在伏击过往旅行者。干掉她。"
D.LocalClientValues[4958]="激活"
D.LocalClientValues[4959]="隆莫格大师"
D.LocalClientValues[4960]="斯科瓦尔德仆从部队"
D.LocalClientValues[4961]="破碎的冰块从天而降击中目标区域，应对|C00b3ffff爪牙|R。"
D.LocalClientValues[4962]="佳奈的著名烈焰煎蛋"
D.LocalClientValues[4963]="由术士施放，可同时伤害许多敌人。"
D.LocalClientValues[4964]="噬人的黑暗"
D.LocalClientValues[4965]="神器 - 术士任务"
D.LocalClientValues[4966]="单手挥砍"
D.LocalClientValues[4967]="蠢货们的黄金"
D.LocalClientValues[4968]="祝福之茶"
D.LocalClientValues[4969]="斯坦索姆"
D.LocalClientValues[4970]="海王子药水"
D.LocalClientValues[4971]="试炼竞技场"
D.LocalClientValues[4972]="夜不能寐"
D.LocalClientValues[4973]="步步为营"
D.LocalClientValues[4974]="由战士施放，可同时伤害多个敌人。也用来描述竞技场队伍。"
D.LocalClientValues[4975]="恐惧高塔"
D.LocalClientValues[4976]="我们在街道中与他们作战"
D.LocalClientValues[4977]="快看天上！"
D.LocalClientValues[4978]="冰川之牙"
D.LocalClientValues[4979]="奇兰尼斯·暮语怨毒的鬼魂俯瞰着鲑鱼溪，任何胆敢阻碍他守望的人都会付出代价。"
D.LocalClientValues[4980]="回归火焰"
D.LocalClientValues[4981]="海军上将咕咕噜"
D.LocalClientValues[4982]="石化"
D.LocalClientValues[4983]="双手各持一柄武器的暴怒狂战士，掀起的暴力飓风能够轻易将敌人切碎，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[4984]="疲倦的旅行者"
D.LocalClientValues[4985]="滑行者瑟莉丝"
D.LocalClientValues[4986]="阻止浩劫"
D.LocalClientValues[4987]="囤积者博达什"
D.LocalClientValues[4988]="我们得找一个擅长召唤大恶魔的术士。搜索一下达拉然城，留意任何有潜力的人。"
D.LocalClientValues[4989]="法力燃烧"
D.LocalClientValues[4990]="魔力之爪"
D.LocalClientValues[4991]="灌林追猎者"
D.LocalClientValues[4992]="不幸的后果"
D.LocalClientValues[4993]="爱咬人的小东西"
D.LocalClientValues[4994]="基尔加丹的战舰坠毁在阿古斯时，爆炸炸出的洞穴网络里有丰富的矿产。在军团赶到之前，我们有一天的时间探索这九个洞窟。"
D.LocalClientValues[4995]="你的斥候报告说我们在戈尔隆德的部队需要支援。"
D.LocalClientValues[4996]="最近对深岩之洲的探索中，我们队伍中的一名成员记录下了奇怪的地震活动。这些可不是普通的震动……我们需要进行深入的调查。"
D.LocalClientValues[4997]="爪牙（诅咒）"
D.LocalClientValues[4998]="传送门守卫者克伦托斯"
D.LocalClientValues[4999]="允许你捕捉精英野兽，获取锻造史诗护甲和武器所需的狂野之血。"
D.LocalClientValues[5000]="全神贯注药剂"
D.LocalClientValues[5001]="接收补给"
D.LocalClientValues[5002]="抢在鲁克玛信徒之前获取鸦人之神的力量。"
D.LocalClientValues[5003]="钢铁卫队长"
D.LocalClientValues[5004]="由潜行者施放，可同时伤害许多敌人。"
D.LocalClientValues[5005]="疫病使者基兹法克斯"
D.LocalClientValues[5006]="在瓦尔莎拉森林的深处，一只独行刃豹会伏击任何靠近它巢穴的旅行者。消灭巴哈加。"
D.LocalClientValues[5007]="石鳞"
D.LocalClientValues[5008]="奥术碎地者"
D.LocalClientValues[5009]="祖传武器"
D.LocalClientValues[5010]="先祖恩赐"
D.LocalClientValues[5011]="水晶扭曲"
D.LocalClientValues[5012]="石质图腾"
D.LocalClientValues[5013]="纳斯拉克森末日使徒"
D.LocalClientValues[5014]="召亡者秘法师"
D.LocalClientValues[5015]="在远离海岸的大洋深处，有一艘驱逐舰因为引擎损坏而抛锚了。谁要是一味重视战士和战利品，这种事就是难免的啦。但那些黄金可不能浪费了。"
D.LocalClientValues[5016]="血精灵船员"
D.LocalClientValues[5017]="血精灵法师"
D.LocalClientValues[5018]="女猎手艾丝蒂德"
D.LocalClientValues[5019]="|cFFFFD200职业：|r法师|n|n|cFFFFD200任务：|r意外的英雄|n|n|cFFFFD200地区：|r达拉然"
D.LocalClientValues[5020]="诅咒大军"
D.LocalClientValues[5021]="癫狂呓语"
D.LocalClientValues[5022]="山地之王乌格跟他的父亲简直一模一样，他注定要成为至高岭中危险的山岭双头怪部族领主。我们必须对他发起攻击。"
D.LocalClientValues[5023]="过载的攻城车"
D.LocalClientValues[5024]="巨大的问题"
D.LocalClientValues[5025]="资助反抗军"
D.LocalClientValues[5026]="裂隙怨灵"
D.LocalClientValues[5027]="被亵渎的巡林者大军"
D.LocalClientValues[5028]="憔悴的维克"
D.LocalClientValues[5029]="淡水长鳍鱼"
D.LocalClientValues[5030]="金色香蕉"
D.LocalClientValues[5031]="维库船长"
D.LocalClientValues[5032]="钢铁攻城火炮"
D.LocalClientValues[5033]="布罗克的弄臣"
D.LocalClientValues[5034]="探查德拉诺：阿兰卡峰林"
D.LocalClientValues[5035]="妖纹布"
D.LocalClientValues[5036]="这些部落船只正绕过悬槌堡前往北方。如果他们运送的板甲没有被食人魔劫走，那么很快就会出现在我们的敌人身上了。快去阻止他们。"
D.LocalClientValues[5037]="影月氏族的部分宝藏守卫十分松懈。我们要拿走能拿走的一切，然后毁掉剩下的东西！"
D.LocalClientValues[5038]="不择手段"
D.LocalClientValues[5039]="虫语者大军"
D.LocalClientValues[5040]="激流"
D.LocalClientValues[5041]="堕落的月羽"
D.LocalClientValues[5042]="战争给补给的供应带来了巨大的压力，部队渴望新鲜的肉。一只名叫潮爪的巨型河蟹可以提供足够的肉，让大家吃上一段时间。"
D.LocalClientValues[5043]="熊猫人船员"
D.LocalClientValues[5044]="地精车间"
D.LocalClientValues[5045]="熊猫人僧侣"
D.LocalClientValues[5046]="所有猎人都有一定的野外生存技能，而探路者更是其中的佼佼者。他们不仅自愿在荒野中生存，利用地形对付敌人的本领更是无人能及。"
D.LocalClientValues[5047]="不朽者埃格尔"
D.LocalClientValues[5048]="征调一批勇士武器和装备物资。"
D.LocalClientValues[5049]="卫兵索艾尔守卫着苏拉玛的边境，他发誓要干掉任何胆敢靠近这座城市的敌人。攻击这名卫兵，扫清进城的道路。"
D.LocalClientValues[5050]="标枪手蓟足"
D.LocalClientValues[5051]="主管索戈尔"
D.LocalClientValues[5052]="军团传送门"
D.LocalClientValues[5053]="虚空之光神殿"
D.LocalClientValues[5054]="阿坎图斯"
D.LocalClientValues[5055]="为了喂养它们的原祖荆兽，魔荚人劫掠了我们盟友的墓地。去夺回那些尸体。如果他们需要肥料，就让他们自己变成肥料吧！"
D.LocalClientValues[5056]="强化受你战斗的召唤技能影响的部队，可造成更多伤害。"
D.LocalClientValues[5057]="凋零使徒号"
D.LocalClientValues[5058]="由武僧施放，可迅速躲避伤害。"
D.LocalClientValues[5059]="警卫永远都在蔚蓝之光广场巡逻。去把还能获得净化的警卫带回来，没救的干掉。"
D.LocalClientValues[5060]="新的阴谋"
D.LocalClientValues[5061]="海军准尉纳沃格"
D.LocalClientValues[5062]="灾花"
D.LocalClientValues[5063]="风暴天空"
D.LocalClientValues[5064]="永生者多姆拉"
D.LocalClientValues[5065]="石血掠夺者"
D.LocalClientValues[5066]="我们知道独眼魔很快就要进攻了，因为他们自己已经告诉我们了。从来没人说过他们聪明。在他们造成真正的伤害之前，快去阻止他们吧。"
D.LocalClientValues[5067]="霜火小戈隆"
D.LocalClientValues[5068]="由法师施放，可暂时抵挡大量伤害。"
D.LocalClientValues[5069]="致命孢子"
D.LocalClientValues[5070]="利针戳刺者"
D.LocalClientValues[5071]="邪脉惩罚者"
