D.LocalClientValues[5073]="|cFFFFD200职业：|r武僧|n|n|cFFFFD200任务：|r重建教派|n|n|cFFFFD200地区：|r武僧战役"
D.LocalClientValues[5074]="派一名追随者执行这个任务，以在至高岭地区获得额外的支援。"
D.LocalClientValues[5075]="艾瑞达裂隙制造者"
D.LocalClientValues[5076]="這是麥特的測試任務 *喇叭和號角吹起勝利的曲調*"
D.LocalClientValues[5077]="仓库可以妥善保存你和要塞所生产的物品。"
D.LocalClientValues[5078]="敌人的目标是我们的光铸装甲。保护好它们，别让军团的尖啸者破坏了。"
D.LocalClientValues[5079]="拉格萨"
D.LocalClientValues[5080]="上佳手气"
D.LocalClientValues[5081]="一群野生小鬼"
D.LocalClientValues[5082]="掠行魔蛛"
D.LocalClientValues[5083]="解锁第二座食人魔传送门，最多可解锁2座。"
D.LocalClientValues[5084]="在这片维库人的坟地中，要担心的问题可不仅仅只是君王和英雄的亡灵。还有“墓穴冰魔”弗约拉格，他是徘徊于生死之间的幽灵。"
D.LocalClientValues[5085]="肮脏的玛卡拉"
D.LocalClientValues[5086]="巨熊马克"
D.LocalClientValues[5087]="野生裂蹄牛"
D.LocalClientValues[5088]="索姆瓦尔的兽人正源源不断地向部落输送优质的毛皮和上好的皮革。让我们那些粗鲁的敌人来穿它们真是太糟蹋东西了。"
D.LocalClientValues[5089]="汗流如涌"
D.LocalClientValues[5090]="苦水宝藏"
D.LocalClientValues[5091]="固执的泽苏莱妮"
D.LocalClientValues[5092]="邪能水晶"
D.LocalClientValues[5093]="窒息邪雾"
D.LocalClientValues[5094]="戴兜帽的祭司"
D.LocalClientValues[5095]="冰封水域"
D.LocalClientValues[5096]="海蟹骑手格姆尔"
D.LocalClientValues[5097]="我们必须攻克黑鸦堡垒，派部队去削弱他们的防御。"
D.LocalClientValues[5098]="怪异预感"
D.LocalClientValues[5099]="大法师卡德加非常担心达拉然居民的安全。他已经请求隐秘通途为这座城市提供保护，但要我们低调行事。"
D.LocalClientValues[5100]="别抱怨了。谁知道呢，没准它们也没有那么臭呢。"
D.LocalClientValues[5101]="邪能之槌的怒火"
D.LocalClientValues[5102]="混淆视听：苏拉玛"
D.LocalClientValues[5103]="要寻找马迪亚斯·肖尔大师，我们显然应该从破碎海滩开始。必须确定燃烧军团把他关押在哪里。"
D.LocalClientValues[5104]="恐惧冲锋"
D.LocalClientValues[5105]="力量与荣耀号"
D.LocalClientValues[5106]="部落精锐潜水艇"
D.LocalClientValues[5107]="血色修道院"
D.LocalClientValues[5108]="鸦人喜欢用名贵的宝石装点自己的武器和护甲。快去弄点回来，让我们的珠宝匠把它们制作成有用的东西吧。"
D.LocalClientValues[5109]="稳定虚空"
D.LocalClientValues[5110]="空设备舱位"
D.LocalClientValues[5111]="恐惧之根"
D.LocalClientValues[5112]="暂用爪牙"
D.LocalClientValues[5113]="割喉者斯塔乌斯"
D.LocalClientValues[5114]="触礁"
D.LocalClientValues[5115]="传说荆棘大王菲里的权杖能指引你找到一个隐藏的宝箱。这是传说吗？"
D.LocalClientValues[5116]="海洋之心"
D.LocalClientValues[5117]="法兰纳尔废墟是个危险的地方，特别是对于那些害怕蜘蛛的人而言。消灭一些那里的潜伏者，减少它们的数量。"
D.LocalClientValues[5118]="逃出生天"
D.LocalClientValues[5119]="阿苏纳的精灵废墟中隐藏着我们无法理解的秘密。搜索这里，重新发现那些被岁月掩盖的遗产。"
D.LocalClientValues[5120]="我们有理由怀疑，有个燃烧军团的特工成功渗透进了达拉然城，现在扮作了一个普通的水果商人。"
D.LocalClientValues[5121]="瘟疫使者帕斯图鲁斯"
D.LocalClientValues[5122]="邪能领主萨瑞姆斯"
D.LocalClientValues[5123]="一个名叫希尔赛的鹰身人主母在瓦尔莎拉的森林中建造了栩栩如生的雕像。"
D.LocalClientValues[5124]="安托兰废土"
D.LocalClientValues[5125]="影障暗影奔马"
D.LocalClientValues[5126]="神圣马驹"
D.LocalClientValues[5127]="神圣风暴"
D.LocalClientValues[5128]="阿苏纳 - 伊利达雷哨所"
D.LocalClientValues[5129]="有一些工人失踪了。我们担心鸦人会在献祭中活活烧死他们。我们必须拯救他们！"
D.LocalClientValues[5130]="接受挑战"
D.LocalClientValues[5131]="天须拳手"
D.LocalClientValues[5132]="|cFFFFD200任务：|r沉睡者|n|cFFFFD200地区：|r要塞战役"
D.LocalClientValues[5133]="白色海怪"
D.LocalClientValues[5134]="血精灵圣骑士"
D.LocalClientValues[5135]="疯狂的灾翼蝠"
D.LocalClientValues[5136]="邪能之乱"
D.LocalClientValues[5137]="夜之子渗透者大军"
D.LocalClientValues[5138]="不存在的搏击俱乐部"
D.LocalClientValues[5139]="轨道指挥员洛卡尔"
D.LocalClientValues[5140]="这艘船上运载了大量板甲；这都是准备送给联盟士兵去穿的。干嘛要让联盟的渣滓穿你们的盔甲呢？"
D.LocalClientValues[5141]="烂水果"
D.LocalClientValues[5142]="玛拉纳战士大军"
D.LocalClientValues[5143]="生产一批真钢锭。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n当建筑达到2级或以上时，你可以通过建筑设计桌指派一名追随者在其中工作，以提高产量。"
