D.LocalClientValues[5147]="难闻的莫格莫克"
D.LocalClientValues[5148]="刃牙虎人开始疯狂进攻了。他们以为自己有九条命。去告诉他们这种想法有多么可笑吧。"
D.LocalClientValues[5149]="在我们忙着破坏黑暗之门时，布林顿已经设法累积了一大笔财富。快去找到他的宝库！"
