D.LocalClientValues[5151]="夜之子猎人"
D.LocalClientValues[5152]="强化防线"
D.LocalClientValues[5153]="把组织的力量引导到聚焦水晶中，让你可以释放达拉然之力，完成一个世界任务。"
D.LocalClientValues[5154]="群体传送"
D.LocalClientValues[5155]="邪恶者的精华"
D.LocalClientValues[5156]="新招募的黑锋骑士变为黑锋掠夺者。\r\n\r\n黑锋掠夺者获得一个随机专精，可以应对|C00b3ffff首领|R。"
D.LocalClientValues[5157]="阿古斯之友"
D.LocalClientValues[5158]="黑潮盗贼"
D.LocalClientValues[5159]="在风暴峡湾的高山之巅，风暴之翼的巨龙女王构筑了巢穴。我们要杀了她和她的子嗣。"
D.LocalClientValues[5160]="恶魔的入侵开始了。"
D.LocalClientValues[5161]="逝网爬行者"
D.LocalClientValues[5162]="咒术师饰品"
D.LocalClientValues[5163]="以阿达尔之光为名"
D.LocalClientValues[5164]="索卡什船长发现自己被一群联盟舰船火力压制了。如果你帮他一把，他愿意镇守北方，提高你的舰队所获得的经验值。"
D.LocalClientValues[5165]="法术（致命）"
D.LocalClientValues[5166]="运输护航"
D.LocalClientValues[5167]="通缉：戈图尔"
