D.LocalClientValues[5169]="最大的舞台"
D.LocalClientValues[5170]="藏宝图"
D.LocalClientValues[5171]="被兄弟从山中逐出之后，迷路的葛诺斯只会四处游荡和猎杀。我们必须找到他，然后消灭他。"
D.LocalClientValues[5172]="执行任务时有几率带回野性蘑菇，用于为部队回复1点活力。"
D.LocalClientValues[5173]="满怀恶意"
D.LocalClientValues[5174]="缝补憎恶"
D.LocalClientValues[5175]="净化之潮"
D.LocalClientValues[5176]="蓟叶林精会把那些看似无人看守的宝藏放在开阔的地带，引诱那些轻率的旅行者进入他们的林地中。"
D.LocalClientValues[5177]="在失落果园里，幽灵们酿出了用奥术陈化的葡萄酒，味道差得简直可以充当上佳的毒药。中断他们那可怕的行动。"
D.LocalClientValues[5178]="折铁者高尔山"
D.LocalClientValues[5179]="野兽控制"
D.LocalClientValues[5180]="完成任务可奖励额外的要塞物资。"
D.LocalClientValues[5181]="闪电奔涌"
D.LocalClientValues[5182]="我们需要援军的帮助来击败哈卡！大多数盟友都响应了我们的召唤，但珊蒂斯·羽月依然深陷在和纳迦的战斗中。去帮帮她，作为回报，她也会给我们提供帮助。"
D.LocalClientValues[5183]="步入深渊"
D.LocalClientValues[5184]="Mk II型湮灭级战列舰"
D.LocalClientValues[5185]="这些具有辐射的危险水结晶吸收了珍贵的海底宝石的魔法成分。这块宝石可以制作出一条强大的项链。"
D.LocalClientValues[5186]="战列舰以毁灭性的远程舰炮著称，在公海上所向披靡。\r\n\r\n|cffb2f0ff应对舰船：|r\r\n|TInterface\\ICONS\\Ships_ABILITY_Bombers.blp:24:24:0:0|t |cffffffff航母|r"
D.LocalClientValues[5187]="召唤地狱火"
D.LocalClientValues[5188]="贝拉祖斯"
D.LocalClientValues[5189]="晴日峰"
D.LocalClientValues[5190]="|cFFFFD200任务：|r变换之风|n|cFFFFD200地区：|r霜火岭|n"
D.LocalClientValues[5191]="新招募的部队有几率提升一个等级，使其更为强大。\r\n\r\n弟子有几率会变为高手，高手有几率变为大师。"
D.LocalClientValues[5192]="邪恶技艺：憎恨精华"
D.LocalClientValues[5193]="伟大的杜鲁"
D.LocalClientValues[5194]="快去支援暗影广场，不能让虚灵在幽影谷和影卫入侵营地之间自由行动。"
D.LocalClientValues[5195]="桑德兰的敌人：阿拉克里斯"
D.LocalClientValues[5196]="黑手"
D.LocalClientValues[5197]="黑石"
D.LocalClientValues[5198]="配合守望者：腐蚀者马尔戴斯"
D.LocalClientValues[5199]="拉哈，魔刃豹领主"
D.LocalClientValues[5200]="让你可以使用末日仪式，你和四个同僚可以召唤强大的恶魔来寻求强化魔法和恶魔宝藏。"
D.LocalClientValues[5201]="部队饿了，去买点吃的。"
D.LocalClientValues[5202]="利爪德鲁伊是变形大师，他们能召唤熊的力量，变身成为力大无比又皮糙肉厚的野兽痛击敌人。"
D.LocalClientValues[5203]="被指派到制革厂时可制造各种帐篷，并提高产品订单的产量，以及制皮任务的成功率。"
D.LocalClientValues[5204]="牢固营帐"
D.LocalClientValues[5205]="只有最强大的萨满才能召唤并支配巨型元素。换做其他人，很可能会命丧巨型元素之手。"
D.LocalClientValues[5206]="你的身体需要足够的能量才能发挥出全部实力！"
D.LocalClientValues[5207]="顽石之后"
D.LocalClientValues[5208]="湿地雾气"
D.LocalClientValues[5209]="一个海巨人在四处横行，希望他的体型不会给你造成麻烦。"
D.LocalClientValues[5210]="高等食人魔战士正在排兵布阵，叫嚣着要“消灭入侵者”。你说他们指的会不会是我们？"
D.LocalClientValues[5211]="烂脸拖住了我们的一小队盟友，他们携带着从黑石铸造厂弄来的原油。快去帮他们把原油运回我们要塞吧。"
D.LocalClientValues[5212]="当联盟部队驶向影月谷时，他们的船只都安然到港了。或许德莱尼也没我们想的那么该死。没准他们船上还带着黄金呢。"
D.LocalClientValues[5213]="百密一疏"
D.LocalClientValues[5214]="苦水吐毒者"
D.LocalClientValues[5215]="调查守望者地窟"
D.LocalClientValues[5216]="索卡什船长的命令"
D.LocalClientValues[5217]="杰德尼勇士沃鲁斯克"
D.LocalClientValues[5218]="暴风城巡逻兵"
D.LocalClientValues[5219]="钢铁码头已经从我们上次的突袭行动中恢复过来，又重新开始运转。去让他们明白，和我们的韧性相比，他们的钢铁是多么脆弱吧。"
D.LocalClientValues[5220]="漆黑的阿卡"
D.LocalClientValues[5221]="熔化护甲"
D.LocalClientValues[5222]="隐秘通途的神射手大师箭术已登峰造极，就算视野很差或根本没有视野，他们也能射中敌人。"
D.LocalClientValues[5223]="隐藏的威胁"
D.LocalClientValues[5224]="一列装满火炮和炸药的列车即将出站。只要引爆一个炸弹，应该就能摧毁整辆列车了。"
D.LocalClientValues[5225]="残余疫病"
D.LocalClientValues[5226]="很多船只在风暴峡湾的海岸边搁浅，而鲨鱼对幸存者造成了威胁。消灭一些鲨鱼，让水手们能够幸存下来。"
