D.LocalClientValues[5228]="铭文"
D.LocalClientValues[5229]="刃拳堡"
D.LocalClientValues[5230]="未知的海域对这些水手来说显然是致命的，如今他们已化身凶残的幽灵，在这一带游荡。据说，他们在死前都是富翁。"
D.LocalClientValues[5231]="魔刃毁灭者"
