D.LocalClientValues[5252]="战歌萨满创造了一种法术，能在我们脚下撕开一道深渊！在沙漏中的沙子流完之前，快去干掉他们！"
D.LocalClientValues[5253]="军团大举入侵瓦尔莎拉！我们需要立即派出援军对抗这一威胁。"
