D.LocalClientValues[5279]="指挥中心末世祭坛漂浮在阿苏纳的法罗纳尔上空。突破进去，然后四处看看。"
D.LocalClientValues[5280]="塔拉多西北方的海域里有一块坚固的岛礁，叫做巨人之拳。钢铁部落还没有发现它。快去了解一下吧。"
D.LocalClientValues[5281]="夜之子的贵族们计划要捕猎一只稀有而且行踪飘忽的狐狸，可能是它的族类中仅存的最后一只了。派出你的勇士，找到更多信息。"
