D.LocalClientValues[5300]="还剩下最后一条线索，然后你就可以去阻止夜之子的猎狐行动了。派出你的勇士，去会见驯犬者布里托玛。"
D.LocalClientValues[5301]="卖出要塞物资，换取追随者的升级和护甲碎片。\r\n\r\n你可以在要塞报告中查看订单进度。\r\n\r\n当生产完成后，再回来接收货物。"
