D.LocalClientValues[5320]="五光十色"
D.LocalClientValues[5321]="邪缚之魂"
D.LocalClientValues[5322]="我们派了一位法师去对付一群充满敌意的原祖荆兽。结果他却站到了它们一边。他肯定是被感染了。是时候派出援军了。"
D.LocalClientValues[5323]="被指派到药圃时可提供草药学加成，还能提高产品订单的产量。"
D.LocalClientValues[5324]="新的一天，新一批的联盟货物也将运往阿什兰了。他们以为往东边绕了那么大一个圈子，就能偷偷把东西运回暴风之盾了吗？可怜虫。"
