D.LocalClientValues[5491]="梦境林地防御者"
D.LocalClientValues[5492]="冻结对手的思维，打断施法。"
D.LocalClientValues[5493]="食腐者废料场位于燃烧军团在安托兰废土的要塞的下方。派遣你的勇士去偷袭在各个要塞之间巡逻的燃烧军团部队吧。"
D.LocalClientValues[5494]="圣光军团需要援军守卫泽尼达尔的残骸。去帮助他们守住阵线吧。"
D.LocalClientValues[5495]="莎达尼尔树根附近的地下生长着不少力量强大的花朵。"
D.LocalClientValues[5496]="黑暗风暴依然汇集在萨格拉斯之墓上方，燃烧军团的部队在那里集结。我们要把勇士们派到破碎海滩去侦察那片区域并寻找生还者。"
D.LocalClientValues[5497]="由潜行者施放，可躲避伤害。还可以用来在邮箱和拍卖行之间快速往返。"
D.LocalClientValues[5498]="至高岭中的邪能图腾部族饲养着恶魔猎犬，用它们来看家护院。我们必须削减它们的数量。"
D.LocalClientValues[5499]="钢铁守望者"
D.LocalClientValues[5500]="缩短任务的行动时间。"
D.LocalClientValues[5501]="你可以下达一个充能的裂隙之核的工作订单，使用后可释放邪能之槌的怒火，立即完成你地图上的一个非精英类世界任务。每18个小时可以使用一次。"
D.LocalClientValues[5502]="海拉加尔护魂者"
D.LocalClientValues[5503]="弗蕾亚之泉：鹰身人主母"
D.LocalClientValues[5504]="梦魇融合怪"
D.LocalClientValues[5505]="萨格雷束缚者"
D.LocalClientValues[5506]="卓格巴尔在苏拉玛的山中挖掘了无数地道，让这一带的建筑结构不太稳定。必须把他们根除。"
D.LocalClientValues[5507]="阿苏纳 - 肯瑞托海滩"
D.LocalClientValues[5508]="入侵准备：武器改良"
D.LocalClientValues[5509]="影月谷的联盟部队过得太舒坦了。繁茂的森林，温和的气候，充足的补给……没准还有新鲜的培根。快去让那些混蛋付出代价吧。"
D.LocalClientValues[5510]="制革厂"
D.LocalClientValues[5511]="|cFFFFD200任务：|r胜者为王|n|cFFFFD200地区：|r霜火岭"
D.LocalClientValues[5512]="地精工程师们正在为黑石和雷神兽人设计武器。好吧，我们也有武器。去恐轨车站使用它们吧。"
D.LocalClientValues[5513]="赤精的回响能用美妙的歌声恢复盟友的士气，给他们活力和希望。"
D.LocalClientValues[5514]="|cFFFFD200任务：|r木头，我都不认识你！|n|cFFFFD200地区：|r戈尔隆德|n"
D.LocalClientValues[5515]="烬网爬虫群"
D.LocalClientValues[5516]="愤怒的余烬"
D.LocalClientValues[5517]="训练中的部队"
D.LocalClientValues[5518]="炼魂熔炉"
D.LocalClientValues[5519]="鲁克拉"
D.LocalClientValues[5520]="正在影月谷肆虐的空灵领主和虚空召唤者是被某个人召唤来的。无论这是谁干的，去找出这个家伙并干掉他。"
D.LocalClientValues[5521]="称霸阿兰卡峰林"
D.LocalClientValues[5522]="造食术"
D.LocalClientValues[5523]="失落的记忆"
D.LocalClientValues[5524]="被虚空撕裂的灵魂"
D.LocalClientValues[5525]="启迪"
D.LocalClientValues[5526]="风暴幼龙的子嗣"
D.LocalClientValues[5527]="开始对你的神器进行附加研究。获得的知识会提高你获得神器能量的速度。"
D.LocalClientValues[5528]="灭虫行动"
D.LocalClientValues[5529]="入侵 - 瓦尔莎拉"
D.LocalClientValues[5530]="地狱之口缚魂者"
D.LocalClientValues[5531]="从休眠中醒来"
D.LocalClientValues[5532]="在这里装备物品。"
D.LocalClientValues[5533]="邪能之槌号"
D.LocalClientValues[5534]="白鬼都是专业拾荒者。让我们帮他们分担一些战利品吧。"
D.LocalClientValues[5535]="血缚混血战士"
D.LocalClientValues[5536]="喋喋不休"
D.LocalClientValues[5537]="时空裂痕"
D.LocalClientValues[5538]="在纳格兰，有一位战歌氏族老萨满的灵魂受到了惊扰。如果我们能让他重新安息，那里的食人魔愿意向我们提供一些补给作为报酬。"
D.LocalClientValues[5539]="显而易见的真相"
D.LocalClientValues[5540]="斥候报告说，一只有许多脑袋，叫做脓花的野兽正在劫掠阴郁沼泽里过往的旅人。为了大家的安全，去肃清道路吧。"
D.LocalClientValues[5541]="毁灭者城镇"
D.LocalClientValues[5542]="地区支援 - 至高岭"
D.LocalClientValues[5543]="女巫苏薇西娅"
D.LocalClientValues[5544]="残梦树妖"
D.LocalClientValues[5545]="元素萨满祭司"
D.LocalClientValues[5546]="混乱之焰"
D.LocalClientValues[5547]="占领铁拳港并拷问俘虏，了解古尔丹的旗舰下落。"
D.LocalClientValues[5548]="达洛克将军"
D.LocalClientValues[5549]="维库人使用符文石召唤强大的元素生物，包括被侵蚀的崩岩，它能够截断河流，让峡谷的生存遭到威胁。"
D.LocalClientValues[5550]="提高与地精一起执行任务的成功率。"
D.LocalClientValues[5551]="玛戈隆和鬣蜥人的皮肤上长着具有魔法力量的岩石板。去收集这些石板供我们使用。"
D.LocalClientValues[5552]="掠夺者多恩"
D.LocalClientValues[5553]="巨灵之殁"
D.LocalClientValues[5554]="巴鲁恩"
D.LocalClientValues[5555]="尽管很多白银之手的侍从都渴望着有朝一日能成为骑士，他们中也有不少人以服侍全身心投入圣光的骑士为荣。"
D.LocalClientValues[5556]="森林之友"
D.LocalClientValues[5557]="猎头"
D.LocalClientValues[5558]="战歌氏族是钢铁部落的力量象征。在夜色的掩护下，烧毁战歌氏族的营地。这能够打击他们的士气。"
D.LocalClientValues[5559]="黑石铸造厂的深处出现了一群燃烬狼崽。如果我们能救出它们，它们或许就会在要塞里住下了。"
D.LocalClientValues[5560]="野蛮三魔"
D.LocalClientValues[5561]="被指派到工坊时可出售工程学装置，并提高产品订单的产量，以及工程学任务的成功率。"
D.LocalClientValues[5562]="英勇飞跃"
D.LocalClientValues[5563]="混乱不堪"
D.LocalClientValues[5564]="利拉斯·月羽"
D.LocalClientValues[5565]="由于至高岭最近的动荡局面，琥珀碎片元素生物从洞穴中倾泻而出，威胁着至高岭的各个部族。"
D.LocalClientValues[5566]="沼泽里的元素之怒"
D.LocalClientValues[5567]="梦魇已经腐蚀了沙拉达希尔的根基，也腐蚀了瓦尔莎拉的许多生物。找到并消灭那些扭曲的元素。"
D.LocalClientValues[5568]="海龟汤"
D.LocalClientValues[5569]="永不停歇的威胁"
D.LocalClientValues[5570]="世界之树莎拉达希尔的根系下方渗出了奇怪的魔法。我们必须派出勇士调查这个异象。"
D.LocalClientValues[5571]="熔岩元素"
D.LocalClientValues[5572]="消逝之海"
D.LocalClientValues[5573]="一群占山为王的元素占据了我们位于霜火岭补给线的周边地区。去杀掉它们，收集丢失的补给。"
D.LocalClientValues[5574]="女武神"
D.LocalClientValues[5575]="|cFFFFD200地区：|r阿兰卡峰林|n"
D.LocalClientValues[5576]="神圣武器"
D.LocalClientValues[5577]="这名守护者能唤起古老的冲突中被遗忘的能量，令自然展现出可怕的一面，并再现支配万物的生死循环。"
D.LocalClientValues[5578]="正义降临"
D.LocalClientValues[5579]="低阶斗士"
D.LocalClientValues[5580]="调查魔法回廊"
D.LocalClientValues[5581]="黑石信使正在这一带流窜。他们所携带的任何文件都可能对我们有着极大的帮助。"
D.LocalClientValues[5582]="刃喉之心"
D.LocalClientValues[5583]="浓雾将这一区域彻底笼罩在黑暗之中。"
D.LocalClientValues[5584]="由圣骑士施放，可解决一个危险的敌人。"
D.LocalClientValues[5585]="燃烧地狱犬"
D.LocalClientValues[5586]="世界树底部的德鲁伊林地沙拉尼尔已经被萨特和他们的首领灾蹄所攻占。派出我们的勇士，前去杀掉灾蹄。"
D.LocalClientValues[5587]="突袭影月岗哨"
D.LocalClientValues[5588]="在你的舰船周围放出烟幕，干扰敌方视野以避免受到先发打击。"
D.LocalClientValues[5589]="崎岖峭壁"
D.LocalClientValues[5590]="魔力巨兽"
D.LocalClientValues[5591]="尼托格·雷塔"
D.LocalClientValues[5592]="祖尔金之魂"
D.LocalClientValues[5593]="食人魔的困境"
D.LocalClientValues[5594]="你必须去沃尔拉斯山顶找剑圣姚素莱，挑战他，聆听他的教诲，得到启迪后再回来。"
D.LocalClientValues[5595]="愿你安息"
D.LocalClientValues[5596]="征服者格古尔"
D.LocalClientValues[5597]="杜隆坦之傲号"
D.LocalClientValues[5598]="邪舌双头飞龙"
D.LocalClientValues[5599]="有了纳特的知识，你在德拉诺的钓鱼技术使你能够不用鱼饵就钓到大鱼。"
D.LocalClientValues[5600]="失落的启示之书"
D.LocalClientValues[5601]="痛苦压制"
D.LocalClientValues[5602]="为传送门供能：阿苏纳"
D.LocalClientValues[5603]="神器：逆风收割者"
D.LocalClientValues[5604]="我们发现的这本魔法书籍很可能来自于泰安诺。如果你能派出一名勇士，也许我们可以了解更多关于大法师瓦格斯在那里旅行的情况。"
D.LocalClientValues[5605]="钢铁部落的旗舰就停在钢铁码头。它很恐怖，可只要被开进暗礁群，它就会像其它船只一样沉没了。"
D.LocalClientValues[5606]="自然学家"
D.LocalClientValues[5607]="暗影死神"
D.LocalClientValues[5608]="赫尔努拉斯"
D.LocalClientValues[5609]="蔚蓝之光集市上曾经贩卖过各种上古珍宝。在废墟里好好搜寻一下。"
D.LocalClientValues[5610]="牛头人船员"
D.LocalClientValues[5611]="黎明新兵"
D.LocalClientValues[5612]="暗影魔"
D.LocalClientValues[5613]="阿苏纳的海滩上到处都是遇难船只的残骸，以及当地那些恶意的居民造成的危险。搜索并消灭任何徘徊的威胁。"
D.LocalClientValues[5614]="联盟战列舰"
D.LocalClientValues[5615]="复活一支部队，可以陪勇士一起进行任务，从而提高成功率。"
D.LocalClientValues[5616]="霜钓海湾充斥着各种样子恶心的海洋生物。但只要你烹制得当，它们都非常美味。快去捞一批水产回来吧。"
D.LocalClientValues[5617]="邪魂复仇者"
D.LocalClientValues[5618]="一个首领，一支军队。"
D.LocalClientValues[5619]="攻城大师艾丁"
D.LocalClientValues[5620]="毁灭者号"
D.LocalClientValues[5621]="如果我们希望对破碎海滩的突袭能成功，就必须与艾泽拉斯的其他势力结盟。"
D.LocalClientValues[5622]="一艘当地的私掠船正为敌人效力，攻击影月谷附近的部落船只。你要做的就是越过钢铁部落在南海的封锁线，将一批货物偷运过去。"
D.LocalClientValues[5623]="碧火魔导师"
D.LocalClientValues[5624]="传说雷神氏族在使用一种奇怪的、可以改变大小的“预兆之刃”。有可能的话，去摧毁这些武器吧。"
D.LocalClientValues[5625]="掠夺者朱瓦尔"
D.LocalClientValues[5626]="黑暗风暴"
D.LocalClientValues[5627]="暗影圣物"
D.LocalClientValues[5628]="纳萨拉斯的学院曾经有一座巨大的图书馆，里面保存着丰富的知识。试试能否找到它。"
D.LocalClientValues[5629]="可怕的萨尼法克斯"
D.LocalClientValues[5630]="暗影火炬"
D.LocalClientValues[5631]="墓穴的召唤"
D.LocalClientValues[5632]="迫使敌人攻击圣骑士。"
D.LocalClientValues[5633]="成功完成任务有几率带回寒冬号角。可以将寒冬号角给予勇士，增加成功几率。"
D.LocalClientValues[5634]="掠夺者艾格罗萨"
D.LocalClientValues[5635]="鲁克玛"
D.LocalClientValues[5636]="鲁克兰"
D.LocalClientValues[5637]="提升你在任务中回收到废品的几率。此外，你现在还可以在废品站中发现追随者用品。"
D.LocalClientValues[5638]="被俘的部落潜水艇"
D.LocalClientValues[5639]="鸦爪祭司佐卡拉"
D.LocalClientValues[5640]="野兽控制猎人"
D.LocalClientValues[5641]="逃跑"
D.LocalClientValues[5642]="通天峰的住民已经阻碍了我们在鸦人领土的战争行动。是时候采取新的战略了：开放式打击阶段。"
D.LocalClientValues[5643]="死亡低语"
D.LocalClientValues[5644]="石头石脑"
D.LocalClientValues[5645]="月光林地"
D.LocalClientValues[5646]="魔术"
D.LocalClientValues[5647]="蔑潮篡符者大军"
D.LocalClientValues[5648]="奪魂者是一群有組織的黑爾拉亞維酷人，打算要盜掠他們自己國王的墳墓。阻止他們，別讓他們造成更多的破壞。"
D.LocalClientValues[5649]="暴风雪"
D.LocalClientValues[5650]="现代人类学家希望德拉诺能揭示剥石者的起源。可他们失望了。"
D.LocalClientValues[5651]="惩戒"
D.LocalClientValues[5652]="优等生"
D.LocalClientValues[5653]="原始的德拉诺古代生物。"
D.LocalClientValues[5654]="称霸戈尔隆德"
D.LocalClientValues[5655]="战争工具"
D.LocalClientValues[5656]="暴怒的琥珀碎片"
D.LocalClientValues[5657]="无尽回忆项链"
D.LocalClientValues[5658]="公主之吻"
D.LocalClientValues[5659]="破冰器"
D.LocalClientValues[5660]="下达订单，用要塞物资换取追随者的武器和护甲。同时解锁新的护甲幻化物品。"
D.LocalClientValues[5661]="积怨纳迦激怒了盐目鱼人，鱼人们现在威胁着纳萨拉斯废墟。我们得把他们赶回去。"
D.LocalClientValues[5662]="“死水”德斯克斯会定期逼疯戈尔隆德的元素生物。让我们看看能对此做点什么吧。"
D.LocalClientValues[5663]="奇怪的感觉"
D.LocalClientValues[5664]="热砂保护协会的差事"
D.LocalClientValues[5665]="是安睡还是哀号"
D.LocalClientValues[5666]="吞噬者芬鲁斯"
D.LocalClientValues[5667]="在山丘之王的大厅里，卓格巴尔和维库人进行着各种奇怪的仪式，驾驭山岭的力量。阻止他们！"
D.LocalClientValues[5668]="巴哈加"
D.LocalClientValues[5669]="月之翼"
D.LocalClientValues[5670]="饥饿的克劳舒克"
D.LocalClientValues[5671]="神圣之地：乌瑟尔之墓"
D.LocalClientValues[5672]="|cFFFFD200任务：|r目的地：未知|n|cFFFFD200地区：|r塔拉多|n"
D.LocalClientValues[5673]="无可争议的重量级选手"
D.LocalClientValues[5674]="展示你碾压德拉诺其他敌对玩家的实力，并磨练你在浸满鲜血的竞技场内的实力。击杀你的敌人，带回他们死亡的证据以换取强大的礼物！"
D.LocalClientValues[5675]="虚空之触"
D.LocalClientValues[5676]="平衡"
D.LocalClientValues[5677]="精灵灾星"
D.LocalClientValues[5678]="“大锤”伊赛尔"
D.LocalClientValues[5679]="空气中充满的了邪恶的味道。"
D.LocalClientValues[5680]="暴风雨中的骑士"
D.LocalClientValues[5681]="邪魂魔导师"
D.LocalClientValues[5682]="瓦尔基拉候选者"
D.LocalClientValues[5683]="啮岩集壳者"
D.LocalClientValues[5684]="潮汐萨满大军"
D.LocalClientValues[5685]="部队出勤"
D.LocalClientValues[5686]="由德鲁伊施放，可解决一个危险的敌人。"
D.LocalClientValues[5687]="死亡动力"
D.LocalClientValues[5688]="夜之子保留了延续数千年的文化，然而并非一切都是文明而淳朴的。前去调查这背后隐藏着什么。"
D.LocalClientValues[5689]="钢铁部落正使用潜水艇在西海岸来回运送黄金。只要击沉一艘潜艇，就能重创地狱咆哮的经济，顺便让我们赚得盆满钵满。"
D.LocalClientValues[5690]="莎拉·魔息"
D.LocalClientValues[5691]="黄金储备"
D.LocalClientValues[5692]="阿苏纳的居民，无论是自然的还是非自然的产物，都非常危险。在这片区域行动时务必要小心。"
D.LocalClientValues[5693]="魔化防御者"
D.LocalClientValues[5694]="钢铁部落正源源不断地向黑暗之门运送工人和补给品。我们会大发慈悲让他们的船过去，好让他们完成重建工作吗？显然不会。"
D.LocalClientValues[5695]="神圣裁决"
D.LocalClientValues[5696]="充能之核"
D.LocalClientValues[5697]="守门人"
D.LocalClientValues[5698]="克罗库想要营救纳斯拉克斯要塞的同胞，防止他们被邪能转化。如果你成功了，军团对这片地区的影响力就会被削弱。"
D.LocalClientValues[5699]="蔑潮工人"
D.LocalClientValues[5700]="许多光铸者被维农的巢穴里的蛛网缠住了。去解救他们。"
D.LocalClientValues[5701]="梦魇的邪恶魔法已经渗入到瓦尔莎拉的河流中，将水中的生命变得极为恐怖。"
D.LocalClientValues[5702]="实验室专研炼金催化反应，提高炼金催化剂的日产量。"
D.LocalClientValues[5703]="他把它藏哪儿了？"
D.LocalClientValues[5704]="|cFFFFD200成就：|r别叫我二世"
D.LocalClientValues[5705]="暗影掠夺者"
