D.LocalClientValues[5717]="部落驱逐舰"
D.LocalClientValues[5718]="一、二……好多！"
D.LocalClientValues[5719]="暗影议会的密探计划用敌人的骨头铺设出一条横穿塔纳安的道路。我们决不能容忍这种暴行的发生。"
D.LocalClientValues[5720]="艾露尼斯最著名的经历是作为提瑞斯法守护者中唯一的女性成员艾格文的武器。但据很多故事中说，这把法杖的历史要比艾格文古老得多。在离开她的手中之后，这把法杖被藏在一个秘密的地窟里，一直尘封未动。"
D.LocalClientValues[5721]="打倒食人魔"
D.LocalClientValues[5722]="阴影中的追猎者，擅长在最恰当的时机对毫无戒备的猎物发起致命的伏击，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[5723]="向面前喷吐火焰，应对|C00b3ffff爪牙|R。"
