D.LocalClientValues[5726]="亡者之息"
D.LocalClientValues[5727]="烬网蛛后"
D.LocalClientValues[5728]="扭曲虚空"
D.LocalClientValues[5729]="黑角鹿皮对我们的部队来说是价值极高的材料。"
D.LocalClientValues[5730]="提高战胜毁灭者及其爪牙的几率。"
D.LocalClientValues[5731]="影月兽人俘虏了一些游侠和联盟部队。快潜入他们的营地救出这些俘虏！"
