D.LocalClientValues[5784]="恢复德鲁伊"
D.LocalClientValues[5785]="用你的机械化力量碾压敌人！"
D.LocalClientValues[5786]="苏拉玛城是个建筑界的奇迹，但它的伟大之处不仅仅只是地面上闪光的尖塔和街道。我们需要对下方进行深入调查。"
D.LocalClientValues[5787]="外卖披萨"
D.LocalClientValues[5788]="我们收到了消息称神谕者泰德瑞丝，一个强大的纳迦女巫，一直在与暗魔萨特会面了。杀掉她和她的同伙。"
D.LocalClientValues[5789]="龙血"
D.LocalClientValues[5790]="巨龙冲撞"
D.LocalClientValues[5791]="指挥官泰克拉兹"
D.LocalClientValues[5792]="由圣骑士施放，可治疗一群盟友。"
D.LocalClientValues[5793]="由潜行者施放，可打断施法（超级讨厌）。"
D.LocalClientValues[5794]="强大的恶魔领主组成了燃烧军团先锋，通过恶魔小径打过来了。我们必须击败他们。"
D.LocalClientValues[5795]="备战就绪"
D.LocalClientValues[5796]="王者祝福"
D.LocalClientValues[5797]="天灾宿敌号"
D.LocalClientValues[5798]="我们最近收到报告，居住在林荫瀑布附近的牛头人部族请求帮助。萨特的斥候营地开始攻击他们的村庄了。"
D.LocalClientValues[5799]="欢笑姐妹"
D.LocalClientValues[5800]="|cFFFFD200职业：|r圣骑士|n|n|cFFFFD200任务：|r反击之时|n|n|cFFFFD200地区：|r圣光秘殿"
D.LocalClientValues[5801]="雌鸟哈米"
D.LocalClientValues[5802]="力量祝福"
D.LocalClientValues[5803]="派些部队去烛照岩清理掉那边的蓝烛矿工。我们需要那里的矿产资源。"
D.LocalClientValues[5804]="协作的竞技场"
D.LocalClientValues[5805]="我们在野外的斥候会有些消息，可以帮我们确定当前的重点。我们需要收集他们的报告。"
D.LocalClientValues[5806]="钢铁部落战列舰"
D.LocalClientValues[5807]="恐怖的战刃大师，使用邪能魔法的破灭之力，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[5808]="保持船体的稳定端正，使其能够轻松地穿越漩涡乱流。"
D.LocalClientValues[5809]="艾默松早已被人遗忘在塔拉多幽深的洞穴中。他的水晶非常珍贵。"
D.LocalClientValues[5810]="命令头盔"
