D.LocalClientValues[5821]="使命终结"
D.LocalClientValues[5822]="能对多名队员造成伤害的技能。"
D.LocalClientValues[5823]="地狱火"
D.LocalClientValues[5824]="如果想让四骑士回归，需要有合适的战马。给骑手萨拉纳尔发出消息，让他来阿彻鲁斯。"
D.LocalClientValues[5825]="耐奥祖"
D.LocalClientValues[5826]="破碎群岛隐藏着许多奥术秘密。我们必须派出法师过去，发掘尽可能多的秘密！"
D.LocalClientValues[5827]="塞纳留斯的祝福"
D.LocalClientValues[5828]="大规模杀伤性原料"
D.LocalClientValues[5829]="你我都知道鸦人是富豪。只要从他们的墙上凿点碎片下来，就够我们吃一辈子了。"
D.LocalClientValues[5830]="实验室专研物质的转化属性，提高质变水晶的日产量。"
D.LocalClientValues[5831]="矮人地堡"
D.LocalClientValues[5832]="真钢锭"
D.LocalClientValues[5833]="石槌威吓者"
D.LocalClientValues[5834]="一个名叫驯犬者伊莱的狼人猎手坚持追捕被遗忘者，已经违反了上级的直接命令。"
D.LocalClientValues[5835]="温德索尔，斗犬"
D.LocalClientValues[5836]="隐秘保护：卓格巴尔佳肴"
D.LocalClientValues[5837]="有一定几率在完成任务后获得一个奇怪的能量球，使用后可提高一名勇士执行下一个任务的成功率。"
D.LocalClientValues[5838]="影月兽人为了召唤虚空兽，仓促地开启了许多传送门。这可能会再次撕裂德拉诺。快阻止他们！"
D.LocalClientValues[5839]="积怨纳迦一直在在阿苏纳沿海捕捉水手，强迫他们为海湾的海巨人工作。"
D.LocalClientValues[5840]="一名稀有坐骑商人在你要塞的兽栏中开设了商店。"
D.LocalClientValues[5841]="这些舰船在离开铁城港前装满了未经加工的邪能。无论它们要去哪里，我们都得摧毁它们以及那些致命的货物。"
D.LocalClientValues[5842]="奇幻之旅"
D.LocalClientValues[5843]="钢铁部落的黑石"
D.LocalClientValues[5844]="捉迷藏"
D.LocalClientValues[5845]="邪能之潮"
D.LocalClientValues[5846]="在我们能够突破到另一边之前，得找到个最合适的地方来偷取燃烧军团的传送门。邪魂堡垒就是个待选的目标。"
D.LocalClientValues[5847]="巨大的飞行啮齿动物"
D.LocalClientValues[5848]="烈焰之友"
D.LocalClientValues[5849]="熔岩射线"
D.LocalClientValues[5850]="军团蛮兵"
D.LocalClientValues[5851]="在恐惧之根的枝干下，有一个名为松达克斯的强大萨特，他在利用腐林的力量进行梦魇仪式。"
D.LocalClientValues[5852]="恐怖阴影"
D.LocalClientValues[5853]="许多强大的食人魔督军都是钢铁部落的可怕盟友。快去说服他们离开吧——如有必要，可以使用武力。"
D.LocalClientValues[5854]="克拉卡图"
D.LocalClientValues[5855]="被污染的自来水"
D.LocalClientValues[5856]="一艘敌方航母控制了黑潮海峡。一旦失去那条航道，就会危及部落在全世界的航运业。我们的目标已经很清楚了。"
D.LocalClientValues[5857]="测试-追随者满级"
D.LocalClientValues[5858]="黑暗中的烛光"
D.LocalClientValues[5859]="兽行成群"
D.LocalClientValues[5860]="菲兹兰克弹射号"
D.LocalClientValues[5861]="幼龙正从天空围攻我们的斥候。这些可怕的幼龙正在寻找下一餐的食物。加油，不要成为他们的午餐！"
D.LocalClientValues[5862]="我们需要找到一位精通召唤强大恶魔的术士。在阿苏纳进行侦察，留意任何有潜力的人。"
D.LocalClientValues[5863]="军团的力量横扫了暗夜要塞。在我们攻击夜之子要塞的心脏之前，先要派出部队前去进行调查。"
D.LocalClientValues[5864]="激活猎豹形态并快速冲刺，应对|C00b3ffff危害|R。"
D.LocalClientValues[5865]="教训双头飞龙"
D.LocalClientValues[5866]="环境灾难"
D.LocalClientValues[5867]="十字军指挥官"
D.LocalClientValues[5868]="崛起"
D.LocalClientValues[5869]="突袭传送门"
D.LocalClientValues[5870]="致命爪牙"
D.LocalClientValues[5871]="侦查"
D.LocalClientValues[5872]="烧焦的羽毛"
D.LocalClientValues[5873]="雷霆平原行者"
D.LocalClientValues[5874]="弘扬武学"
D.LocalClientValues[5875]="骑手萨拉纳尔需要猎手阿图门曾经的坐骑“午夜”的鞍座。在卡拉赞废墟的某处应该可以找到那个鞍座。"
D.LocalClientValues[5876]="月落之巢"
D.LocalClientValues[5877]="法师C部队"
D.LocalClientValues[5878]="顺我者昌"
D.LocalClientValues[5879]="恶鬼脆弱但敏捷，还能攀爬垂直的墙壁。它们常攀附在暗处，袭击毫无防备的目标。"
D.LocalClientValues[5880]="破碎群岛"
D.LocalClientValues[5881]="酸败的美酒"
D.LocalClientValues[5882]="战歌兽人捣毁了我们北边的营地，唯一的幸存者说他们往这儿来了。我们必须击退入侵者！"
D.LocalClientValues[5883]="再也没有比参加友好——或是不那么友好——的比赛，并捍卫本阵营的荣耀更激动人心的事了。派你的勇士们去探索战场吧。"
D.LocalClientValues[5884]="磨光的石块"
D.LocalClientValues[5885]="滩沙"
D.LocalClientValues[5886]="军团正在纳斯拉克斯要塞建造一件武器。让我们的勇士去侦察一下那究竟是什么武器，并了解摧毁这件武器的办法。"
D.LocalClientValues[5887]="一只凶残的野兽，刀喙，一直在阿苏纳的开阔林地中捕食逐日圣马。那些可怜的生物被吓坏了。"
D.LocalClientValues[5888]="奥术攻城武器"
D.LocalClientValues[5889]="托林·斯科瓦尔德"
D.LocalClientValues[5890]="催眠药水"
D.LocalClientValues[5891]="亡灵徽记"
D.LocalClientValues[5892]="奥术师淡鹬"
D.LocalClientValues[5893]="消失粉"
D.LocalClientValues[5894]="洛拉姆斯，是你吗？"
D.LocalClientValues[5895]="有小道消息称，一支运输舰队不久前在这片远离陆地的水域沉没。遗憾的是，我们不是唯一收到消息的人。"
D.LocalClientValues[5896]="被指派到珠宝店时可提供各种珠宝加工加成，并提高珠宝加工任务的成功率。"
D.LocalClientValues[5897]="破碎海滩"
D.LocalClientValues[5898]="Q-43噪音水雷"
D.LocalClientValues[5899]="将你传送到你的恶魔法阵，应对|C00b3ffff危害|R。"
D.LocalClientValues[5900]="钟乳石爱好者"
D.LocalClientValues[5901]="幽爪奔跑者"
D.LocalClientValues[5902]="我们认为最近发生的恐惧渡鸦袭击与鸦人有关。我们得调查一下它们，而你则要去追杀他们的爪牙。"
D.LocalClientValues[5903]="破碎之翼"
D.LocalClientValues[5904]="有人在达拉然各地砸窗户，留下一地破坏痕迹和碎玻璃渣。前去调查，找到幕后的罪犯。"
D.LocalClientValues[5905]="拉文凯斯的凝视"
D.LocalClientValues[5906]="我们的斥候报告说在黑鸦堡垒下方存在一个天然洞穴系统。我们应该去调查一下，看看那些洞穴是否像上面的城堡那样难以攻破。"
D.LocalClientValues[5907]="|cFFFFD200职业：|r死亡骑士|n|n|cFFFFD200任务：|r|n|n|cFFFFD200地区：|r阿苏纳"
D.LocalClientValues[5908]="腐化姐妹"
D.LocalClientValues[5909]="被亵渎的巡林者"
D.LocalClientValues[5910]="贝雷特"
D.LocalClientValues[5911]="额外舱房"
D.LocalClientValues[5912]="黑锋掠夺者身经百战、杀敌无数，是黑锋骑士团中最勇猛的士兵。"
D.LocalClientValues[5913]="你抓住友方目标的灵魂，使其立即移动到你面前，应对|C00b3ffff危害|R。"
D.LocalClientValues[5914]="召唤组织的祈祷，祝福你的勇士，提高他们任务的成功率。"
D.LocalClientValues[5915]="狂暴"
D.LocalClientValues[5916]="打断敌人施放的法术，应对|C00b3ffff法术|R。"
D.LocalClientValues[5917]="指引低语"
D.LocalClientValues[5918]="唤地者"
D.LocalClientValues[5919]="山地座狼"
D.LocalClientValues[5920]="经历了丧子之痛后，海军上将戴林·普罗德摩尔的心灵就被复仇的渴望蒙蔽了。前往暗影界，从他的灵魂中收集憎恨精华吧。"
D.LocalClientValues[5921]="|cFFFFD200职业：|r恶魔猎手|n|n|cFFFFD200任务：|r两位助手|n|n|cFFFFD200地区：|r邪能之槌号"
