D.LocalClientValues[5924]="恶毒女王"
D.LocalClientValues[5925]="恶魔学识术士"
D.LocalClientValues[5926]="提高战胜恶魔的几率。"
D.LocalClientValues[5927]="法兰纳尔曾藏有一大批美酒。派些部队去调查一下，看看他们能发现什么吧。"
D.LocalClientValues[5928]="神圣意志"
D.LocalClientValues[5929]="奇迹之袋"
D.LocalClientValues[5930]="灰掌"
D.LocalClientValues[5931]="骚动的流水之魂"
D.LocalClientValues[5932]="拉文霍德的私人卫兵。每当有“特殊”情况发生时，他们才会出动。"
D.LocalClientValues[5933]="坚韧的勇士，拥有行云流水、变化莫测的身法，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[5934]="灰谷"
D.LocalClientValues[5935]="一位刀塔酋长满不情愿地向我们提供了一条线索，据说堡垒地下的矿井中藏着一张古代地图。"
D.LocalClientValues[5936]="|cFFFFD200职业：|r猎人|n|n|cFFFFD200要塞任务：|r强力助手|n|n|cFFFFD200地区：|r神射手营地"
D.LocalClientValues[5937]="小打小闹"
D.LocalClientValues[5938]="逐晨者号"
D.LocalClientValues[5939]="大地的低语"
D.LocalClientValues[5940]="由潜行者施放，可压制一个危险的敌人（或者骚扰你一下）。"
D.LocalClientValues[5941]="欺诈斗篷"
D.LocalClientValues[5942]="散逸的魔网能量"
D.LocalClientValues[5943]="一艘钢铁部落的潜水艇闯入了我们的船坞，快去击沉它。"
D.LocalClientValues[5944]="堕夜构造体"
D.LocalClientValues[5945]="刀笔吏"
D.LocalClientValues[5946]="|cFFFFD200成就：|r里——诺艾……？|n|cFFFFD200地下城：|r黑石塔上层|n"
D.LocalClientValues[5947]="|cFFFFD200任务：|r杀死腐化的野兽|n|cFFFFD200地区：|r影月谷"
D.LocalClientValues[5948]="燃烧"
D.LocalClientValues[5949]="蠕行的亡灵花"
D.LocalClientValues[5950]="剑刃风暴"
D.LocalClientValues[5951]="当你在德拉诺的野外区域时，生命值低于35%时受到的所有伤害降低50%。并允许你参加悬槌竞技场的角斗士大赛。"
D.LocalClientValues[5952]="邪魂堡垒不适合我们的计划，但没有别的办法了。侦查邪焰隘口附近的区域，看看有没有希望。"
D.LocalClientValues[5953]="冰霜掠夺者"
D.LocalClientValues[5954]="魔焰地狱火"
D.LocalClientValues[5955]="山里有兽人！"
D.LocalClientValues[5956]="副指挥官帕普里斯"
D.LocalClientValues[5957]="一位坚韧的守护者，可以使用盾牌来应对|C00b3ffff首领|R。"
D.LocalClientValues[5958]="梦境林地已经建好了，但我们还需要帮助。莉莉丝是位有名的部队训练师，她捎来口信说自己正在途中，但遭受了攻击！"
D.LocalClientValues[5959]="探路者马鞍"
D.LocalClientValues[5960]="荧月海滩上的凶案"
D.LocalClientValues[5961]="信徒追猎刺客"
D.LocalClientValues[5962]="一位兽王正护送一批原油前往黑石山。快去阻止他！"
D.LocalClientValues[5963]="他们乘着坐骑冰封的双翼，将怒火和复仇降到受害者的头上。那些面对寒霜骑士的人很快就会开始畏惧头顶的天空。"
D.LocalClientValues[5964]="时光水晶"
D.LocalClientValues[5965]="由法师施放，可解决一个危险的敌人。"
D.LocalClientValues[5966]="大迁徙"
D.LocalClientValues[5967]="“钉刺”格拉修斯"
D.LocalClientValues[5968]="宾奇维斯的地精正在毒害当地的环境。我看不出任何理由不能从他们那里抢一些利润过来。"
D.LocalClientValues[5969]="一种奇怪的疾病正在戈尔隆德的古树间传播。被感染的古树都发了疯。在情况恶化之前，去消灭这些古树吧。"
D.LocalClientValues[5970]="至高岭的险峰将苏拉玛和古代北地隔绝开来。传说在这座孤山之中有一支古老的牛头人部族，他们的领袖掌握着一件拥有神力的遗物。"
D.LocalClientValues[5971]="饥渴的瓦拉卡"
D.LocalClientValues[5972]="超级炉渣兄弟"
D.LocalClientValues[5973]="暗水战士"
D.LocalClientValues[5974]="献祭"
D.LocalClientValues[5975]="调查邪魂堡垒"
D.LocalClientValues[5976]="|cFFFFD200任务：|r艾韵|n|cFFFFD200地区：|r戈尔隆德"
D.LocalClientValues[5977]="兽栏管理员奥兰"
D.LocalClientValues[5978]="堕落战马：无头骑士的鞍座"
D.LocalClientValues[5979]="梦魇已经腐蚀了这片森林中一度温顺的生物，就连鹿群也变得狂暴起来。结束它们的痛苦吧。"
D.LocalClientValues[5980]="田吉需要帮助"
D.LocalClientValues[5981]="敌人组建了施法者部队，对我们展开了可怕的邪能轰炸。我们需要更多的协助才能对抗这些攻击。"
D.LocalClientValues[5982]="无光之海"
D.LocalClientValues[5983]="食人魔在霜火岭发现了一大箱补给。有人想出去打几只食人魔玩吗？"
D.LocalClientValues[5984]="燃烧军团正在使用邪能灭绝者巩固欺诈者之痕的防御。趁这些火炮还没装好，快把它们破坏掉。"
D.LocalClientValues[5985]="裂世者斯库尔"
D.LocalClientValues[5986]="原兽平原"
D.LocalClientValues[5987]="风暴峡湾的峭壁曾是苏拉玛精灵放牧野兽的牧场，如今已经成为了一支古代维库部落的首都，他们是在大分裂后从北地逃到这里的。"
D.LocalClientValues[5988]="艾瑞达在堕入邪能前，都是精通奥术的大师。去搜索一下裁判所，寻找失落的魔法。"
D.LocalClientValues[5989]="突袭巢穴"
D.LocalClientValues[5990]="捕魂者麦芙拉"
D.LocalClientValues[5991]="我们不能让鸦人继续获取致命的埃匹希斯技术了。去突袭他们的挖掘场，把那里化为齑粉！"
D.LocalClientValues[5992]="药圃"
D.LocalClientValues[5993]="有人发现教团的一队祭司正在破碎海滩的登陆点附近搜索，在危险的恶魔中寻找生还者。"
D.LocalClientValues[5994]="锋利噬咬"
D.LocalClientValues[5995]="缚魂者哈尔多拉"
D.LocalClientValues[5996]="一部分邪能图腾现在由一只紫喉鹰身人率领着，他们正在聚集部队。让我们先发制人。"
D.LocalClientValues[5997]="勒纳尼海滩"
D.LocalClientValues[5998]="敌方潜艇突然对这一区域表现出了莫大的兴趣。他们可能是在搜寻一块元素符文。一旦让它落入坏人手中，可能会造成毁灭性的后果。"
D.LocalClientValues[5999]="在泣风崖的底部有一个不安分的水元素，它的存在让我们无法到达飞船的残骸地点。"
D.LocalClientValues[6000]="渔夫小屋可为那些想钓大鱼的人提供场所。"
D.LocalClientValues[6001]="布林顿的秘密宝库"
D.LocalClientValues[6002]="活化扫帚"
D.LocalClientValues[6003]="碎手氏族建造了一座名字非常讽刺的堡垒，刃拳堡。让我们好好嘲弄它一番吧。"
D.LocalClientValues[6004]="戒律"
D.LocalClientValues[6005]="我看见了死兽人"
