D.LocalClientValues[6008]="地区支援 - 部落"
D.LocalClientValues[6009]="黯水冥界鱿鱼"
D.LocalClientValues[6010]="艾瑞达监视者"
D.LocalClientValues[6011]="强效战斗的召唤"
D.LocalClientValues[6012]="宠物小窝可以让你训练和强化你的宠物。"
D.LocalClientValues[6013]="吞噬虚空"
D.LocalClientValues[6014]="猫抓热"
D.LocalClientValues[6015]="职业大厅"
D.LocalClientValues[6016]="格罗玛什极其自负和暴躁。只要狠狠打击战歌氏族，他就会被复仇冲昏头脑。我们得让他分心。"
D.LocalClientValues[6017]="汽痕部落祭司"
