D.LocalClientValues[6021]="果园"
D.LocalClientValues[6022]="废墟交响曲"
D.LocalClientValues[6023]="肮脏的战斗"
D.LocalClientValues[6024]="塑地者特鲁"
D.LocalClientValues[6025]="由于间谍的破坏，这些航母在开赴战场的途中沉没了。因为没能光荣地战死沙场，船上不甘的幽灵水手们正不断袭击其他船只作为报复。"
D.LocalClientValues[6026]="魔导师阿斯托乐丝"
D.LocalClientValues[6027]="野獸遭遇戰1"
D.LocalClientValues[6028]="野獸遭遇戰2"
D.LocalClientValues[6029]="死神的撕咬"
D.LocalClientValues[6030]="死亡的恩赐"
D.LocalClientValues[6031]="碾槌"
D.LocalClientValues[6032]="不怀好意的观众"
D.LocalClientValues[6033]="|cFFFFD200任务：|r为了孩子！|n"
D.LocalClientValues[6034]="魔蝠尖啸者"
D.LocalClientValues[6035]="肯瑞托召唤师是操控奥术和元素之力的精英施法者，他们在魔法方面的技艺无人能及，麦迪文的父亲聂拉斯·埃兰就是其中一员。"
D.LocalClientValues[6036]="咯啦呣嘎啦"
D.LocalClientValues[6037]="剑与巫术的交汇"
D.LocalClientValues[6038]="斯纳西弗"
D.LocalClientValues[6039]="梅里纳利"
D.LocalClientValues[6040]="在卓格巴尔的洞穴里，有个地下的蜗牛竞速跑道。最近那里爆发了一场残酷的打斗。我们需要进行相关调查。"
D.LocalClientValues[6041]="我们的斥候发现有一群食人魔奴贩聚集到了戈尔隆德。我们不能给他们立足的机会。进攻！"
D.LocalClientValues[6042]="乱世戈隆"
D.LocalClientValues[6043]="一次迅速的正面打击能够干脆利落地结束战斗。"
D.LocalClientValues[6044]="恶魔卫士入侵者"
D.LocalClientValues[6045]="召來一個強大的盟友，可支援勇士進行任務以提高成功率。"
D.LocalClientValues[6046]="猩红航帆"
D.LocalClientValues[6047]="古老的秘密"
D.LocalClientValues[6048]="7.0教学"
D.LocalClientValues[6049]="洛查伯"
D.LocalClientValues[6050]="无论你说上多少遍..."
D.LocalClientValues[6051]="黑暗腐化"
D.LocalClientValues[6052]="通缉：废灵者达库尔"
D.LocalClientValues[6053]="吸取邪能"
D.LocalClientValues[6054]="狂怒冲锋"
D.LocalClientValues[6055]="灭世者"
D.LocalClientValues[6056]="在这遥远的北方，部落部队似乎以为自己已经摆脱我们的舰船了。但思考从来都不是他们的强项。"
D.LocalClientValues[6057]="动荡不安"
D.LocalClientValues[6058]="|cFFFFD200任务：|r大量小戈隆|n|cFFFFD200地区：|r霜火岭"
D.LocalClientValues[6059]="好消息！我们发现了一块卡德加所需的元素符文。但坏消息是，它在黑石矿坑里。"
D.LocalClientValues[6060]="这三人组必须死，不过我们得尽全力对付他们。"
D.LocalClientValues[6061]="林地守护者"
D.LocalClientValues[6062]="莎达娜·血怒"
D.LocalClientValues[6063]="真正的蜜酒"
D.LocalClientValues[6064]="不堪重负"
D.LocalClientValues[6065]="测试任务完成及一切相关情况。"
D.LocalClientValues[6066]="暗夜精灵船员"
D.LocalClientValues[6067]="神圣壁垒"
D.LocalClientValues[6068]="犁爪"
D.LocalClientValues[6069]="卡拉赞"
D.LocalClientValues[6070]="卡巴罗斯"
D.LocalClientValues[6071]="引鸦出巢"
D.LocalClientValues[6072]="健壮的风暴幼龙"
D.LocalClientValues[6073]="黑鸦堡垒的墓地中有复活的亡者，我们认为是已逝的拉文凯斯家族成员。"
D.LocalClientValues[6074]="教团的圣贤能精准地驾驭圣光，多年以来，他们一直以刻苦研读典籍而闻名。"
D.LocalClientValues[6075]="快从壁炉旁拉一把椅子吧！"
D.LocalClientValues[6076]="我们最好别去招惹那些邪恶的鸦人，但占领他们在阿兰卡峰林的神殿可以让我们取得战略优势。"
D.LocalClientValues[6077]="吸魂者"
D.LocalClientValues[6078]="心灵尖刺"
D.LocalClientValues[6079]="躁动的幽灵"
D.LocalClientValues[6080]="生活在这里的所谓“飞龙”作为坐骑极其脆弱，但愚蠢的德莱尼却肯花大价钱来购买它们。去把他们最近运来的那批黄金抢过来。在我们手里，它们可以更好地发挥作用。"
D.LocalClientValues[6081]="朝圣之旅"
D.LocalClientValues[6082]="恶魔卫士蛮兵"
D.LocalClientValues[6083]="神圣牧师"
D.LocalClientValues[6084]="冷酷打击"
D.LocalClientValues[6085]="疱喉"
D.LocalClientValues[6086]="封锁线：赞加海"
D.LocalClientValues[6087]="影月谷的木精又卷土重来了，而且实力更胜往昔。去让他们看看我们的力量，顺便测试一下自己有没有进步吧。"
D.LocalClientValues[6088]="溅出的酒水"
D.LocalClientValues[6089]="脓花"
D.LocalClientValues[6090]="允许生产炼金物品并接受产品订单。"
D.LocalClientValues[6091]="恐翼指挥官"
D.LocalClientValues[6092]="兽人的布甲跟我们的一样柔软舒适。告诉你的法师，他们必须弄到这批货物，那就是他们的装备。没有例外，侏儒也得穿。快动手吧。"
D.LocalClientValues[6093]="派一名追随者执行这个任务，以在阿苏纳地区获得额外的支援。"
D.LocalClientValues[6094]="达戈·食岩"
D.LocalClientValues[6095]="弄潮女瑟瑞维丝"
D.LocalClientValues[6096]="魔法猎犬"
D.LocalClientValues[6097]="瓦尔莎拉曾是艾泽拉斯德鲁伊信仰的中心，世界之树莎拉达希尔耸立于正中间的位置。森林中隐藏着诸多失落已久的秘密，它们或许有助于我们对抗军团。"
D.LocalClientValues[6098]="|cFFFFD200职业：|r死亡骑士|n|n|cFFFFD200任务：|r天然盟友|n|n|cFFFFD200地区：|r阿彻鲁斯"
D.LocalClientValues[6099]="破碎墓穴"
D.LocalClientValues[6100]="华美皮装"
D.LocalClientValues[6101]="提高与矮人一起执行任务的成功率。"
D.LocalClientValues[6102]="高阶鸦人奴役了自己的流亡者同胞，并驱使他们挖掘这片埃匹希斯挖掘场，寻找古代神器。快去解放那些工人吧。"
D.LocalClientValues[6103]="提高与兽人一起执行任务的成功率。"
D.LocalClientValues[6104]="黑石军火"
D.LocalClientValues[6105]="炼金实验室"
D.LocalClientValues[6106]="流明石：瓦尔莎拉"
D.LocalClientValues[6107]="树木繁茂的土地。"
D.LocalClientValues[6108]="奥丁选择了让你来指挥他的军队，但我们需要训练出一支拥有战斗力的部队。派拉格瓦尔德出去，找到最强大的维库人队长。"
D.LocalClientValues[6109]="突袭大师索托尔"
D.LocalClientValues[6110]="完成任务可获得额外的经验值。"
D.LocalClientValues[6111]="荆棘大王菲里"
D.LocalClientValues[6112]="黑暗召唤号"
D.LocalClientValues[6113]="任务成功完成后可获得额外的埃匹希斯水晶。"
D.LocalClientValues[6114]="遗失的容器：阿苏纳"
D.LocalClientValues[6115]="布雷舰"
D.LocalClientValues[6116]="肃霜劳工"
D.LocalClientValues[6117]="麦托克劳带领一支德鲁伊队伍前往至高岭处理鹰身人的问题，但她被包围了。击败巢穴主母苏伯妮，把麦托克劳带回来！"
D.LocalClientValues[6118]="我们已经和一个至高岭的牛头人部族进行了接触。他们拥有多余的皮毛和皮革，但恶魔进攻阻碍了贸易。"
D.LocalClientValues[6119]="|cFFFFD200职业：|r恶魔猎手|n|n|cFFFFD200任务：|r水到渠成|n|n|cFFFFD200地区：|r邪能之槌号"
D.LocalClientValues[6120]="伊利达雷战士"
D.LocalClientValues[6121]="许多克罗库奴隶正在清道夫岗哨工作。尽量多救几个出来吧。"
D.LocalClientValues[6122]="暗影界"
D.LocalClientValues[6123]="我们需要向虚空之光神殿的牧师们派出一名大使。但沿途可能会有危险。派玛克斯韦尔·泰罗索斯去吧。"
D.LocalClientValues[6124]="|cFFFFD200商人出售：|r暗影猎手德恩加|n|cFFFFD200地区：|r塔纳安丛林|n|cFFFFD200阵营：|r沃金之锋 - 尊敬"
