D.LocalClientValues[6141]="末日就要降临了。"
D.LocalClientValues[6142]="不安的亡灵"
D.LocalClientValues[6143]="另一座法师之城"
D.LocalClientValues[6144]="深渊大师鲁迪"
D.LocalClientValues[6145]="毫无疑问，这些驶向海湾的船上搭载的都是热心的鸟类爱好者，而不是为钢铁部落奴役多头蛇的驯兽师。毫无疑问。"
