D.LocalClientValues[6272]="一山不容二虎"
D.LocalClientValues[6273]="加洛西歼灭者正在阿古斯废土上横行无忌，对我们的部队行动构成了重大威胁。一定要把它干掉。"
D.LocalClientValues[6274]="在安装了负电子控制单元后，生命体和机械之间就能建立起真正的感情！快去弄一个来！"
