D.LocalClientValues[6281]="你对目标迎头痛击，应对|C00b3ffff法术|R。"
D.LocalClientValues[6282]="喂食时间"
D.LocalClientValues[6283]="有棵古树正在疯狂袭击所有阻挡他的人和物。另外根据相关提示，我们正缺少木柴呢。"
D.LocalClientValues[6284]="风暴英雄"
D.LocalClientValues[6285]="艾瑞达召唤者从扭曲虚空召唤了巨型地狱火。快去破坏他们的传送门。"
D.LocalClientValues[6286]="至高岭的部族对威严的大角鹿的毛皮奉若至宝，他们会在最重要的仪式上使用这种稀有而灵活的生物的毛皮。追踪这头野兽。"
D.LocalClientValues[6287]="瓦尔莎拉的森林已被梦魇占据，而且这种恐惧已经逐渐渗入苏拉玛城。击退萨特和他们手下的亵渎者。"
D.LocalClientValues[6288]="拍卖行"
D.LocalClientValues[6289]="魁梧的野蛮战士，以破坏为乐。许多人认为他们没有脑子，其实对恶魔而言，他们相当聪明。"
D.LocalClientValues[6290]="平原旅人"
D.LocalClientValues[6291]="迫使敌人攻击战士。"
D.LocalClientValues[6292]="有些恶魔猎手似乎把“以火攻火”这话当成字面意思理解了。"
D.LocalClientValues[6293]="碎歌林地正在遭受燃烧军团的进攻。这是个绝佳的机会，我们可以实地测试下新的部队，并且了解关键信息。"
