D.LocalClientValues[6319]="淡水兽占据了碧影湿地。它们的领地观念极强而且非常彪悍。这阻碍了我们获取重要物资。"
D.LocalClientValues[6320]="传说灌木林地里有一棵被扭曲的古树。去找到这个“影皮”，然后解决他。"
D.LocalClientValues[6321]="月神殿被萨特和燃烧军团的爪牙包围了起来。丰收女巫塞莱斯廷正在想办法，但我们需要她到这里来。"
D.LocalClientValues[6322]="洪水切断了我们的补给线，而引发洪水的水元素似乎并没有停手的打算。快去把它们挂起来风干！"
D.LocalClientValues[6323]="掠食者的繁殖速度很快，而且什么都吃，就像蟋蟀一样。但它们还很残忍嗜杀，而且体型像马一样大。这一点就不像蟋蟀了。"
