D.LocalClientValues[6334]="攻破钢铁部落位于隔绝之海的防线，打开进入塔纳安周围水域的通道，从而开启地狱火堡垒的海军行动。"
D.LocalClientValues[6335]="卫兵索艾尔"
D.LocalClientValues[6336]="干掉那艘敌方的补给船，但行动一定要快，以防有人狗急跳墙。霜冻深渊这个名字可不是随便叫叫的。"
D.LocalClientValues[6337]="|cFFFFD200任务：|r主教之友|n|cFFFFD200地区：|r影月谷"
D.LocalClientValues[6338]="俗话说高风险，高回报。去试探一下戈尔隆德南部的暗刺洞穴的危险程度，看看你会有什么发现。"
D.LocalClientValues[6339]="小鬼是低阶恶魔，常常因为单体力量薄弱而被低估。但集群之后，它们前赴后继，最让人头疼的一点就是很难把它们赶尽杀绝。"
D.LocalClientValues[6340]="燃烧欲望"
D.LocalClientValues[6341]="邪能传说"
D.LocalClientValues[6342]="幸运"
D.LocalClientValues[6343]="显然鬣蜥人消化不了它们吞下的那些珍贵宝石，所以你的任务已经很明确了。"
D.LocalClientValues[6344]="霜火岭"
D.LocalClientValues[6345]="我们的斥候报告说苦水强盗发现了一个宝箱，可能是来自于艾萨拉的宝藏储藏室。我们得去看看能找到些什么。"
D.LocalClientValues[6346]="驯宠大师弗鲁莫斯向来不按牌理出牌。这次他得到了一只火蝠幼崽，居然想吃了它！将那只幼崽从厄运中拯救出来。"
D.LocalClientValues[6347]="贪婪的食腐者"
D.LocalClientValues[6348]="我们尚未收到前往风暴峡湾的塔尔扎和他的斥候传回的消息。考虑到那片区域中存在敌对的维库人，他们很可能遭到了伏击。"
