D.LocalClientValues[6363]="任务时长缩短3%。"
D.LocalClientValues[6364]="大地之环卫兵"
D.LocalClientValues[6365]="影卫虚灵给自己的武器灌注了暗影。只要搞懂他们的技术，就能为我们增添强大的防御手段。"
D.LocalClientValues[6366]="莎拉达希尔的样本已经准备好了。我们可以派纳拉雷克斯去进行研究。他需要花一些时间来仔细分析它们。"
D.LocalClientValues[6367]="飓风之怒"
D.LocalClientValues[6368]="鸦人将我们这些“地面居民”视为野兽。等我们把他们引以为傲的通天峰化为废墟之后，看他们还有什么话说吧。"
D.LocalClientValues[6369]="Mk II型钢铁猎手级潜水艇"
D.LocalClientValues[6370]="使潜水艇可躲过雷达扫描并秘密靠近敌方舰船。"
D.LocalClientValues[6371]="信徒唤日者"
D.LocalClientValues[6372]="糟糕的工作日"
D.LocalClientValues[6373]="狂缚母鹿"
D.LocalClientValues[6374]="我们需要定期清理荧光腐沼里的迁跃兽，以保证运输用精灵龙的稳定供应。"
D.LocalClientValues[6375]="冰怒元素"
D.LocalClientValues[6376]="原祖荆兽和它们的木精爪牙正在袭击经过塔拉多的车队。我们要让它们后悔发芽来到这个世界上。"
D.LocalClientValues[6377]="大幅提高战胜多种生物的几率。"
D.LocalClientValues[6378]="噩梦小鬼"
D.LocalClientValues[6379]="我们可以派一些精英去突袭巨灵之殁的雷神岗哨！快去夺取胜利吧。"
D.LocalClientValues[6380]="暗影魔法大师，专精吸取能量和持续伤害法术，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[6381]="骑手萨拉纳尔需要阿尔萨斯·米奈希尔曾经的坐骑“无敌”的鞍座。自从阿尔萨斯被击败后，鞍座就遗失在了冰冠冰川。"
D.LocalClientValues[6382]="暴躁的火焰之魂"
D.LocalClientValues[6383]="武艺无双的武者，尤其擅长拳脚功夫，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[6384]="联盟精锐驱逐舰"
D.LocalClientValues[6385]="希尔瓦娜斯·风行者在风暴峡湾中消失了。让军情七处的人以为我们对她的下落非常着急。我们确实很着急，但还是需要安排一个作为诱饵的特工，引起军情七处的注意。"
D.LocalClientValues[6386]="隨機專精[NYI]"
D.LocalClientValues[6387]="见习潜水艇"
D.LocalClientValues[6388]="在海拉的舰队中，达昆船长的手下全是些不得不在海上进行永恒航行的诅咒灵魂，令人闻风丧胆。消灭他。"
D.LocalClientValues[6389]="崩塌虚空"
D.LocalClientValues[6390]="进口铁颚狼"
D.LocalClientValues[6391]="古树之力"
D.LocalClientValues[6392]="戈尔隆德出现两只巨型毁灭者。还有比这更能证明实力的挑战吗？"
D.LocalClientValues[6393]="泰坦之怒"
D.LocalClientValues[6394]="魔荚吐疫者"
D.LocalClientValues[6395]="解锁铭文任务，并允许同时接受最多21份产品订单。"
D.LocalClientValues[6396]="遗忘海滩"
D.LocalClientValues[6397]="|cFFFFD200职业：|r恶魔猎手|n|n|cFFFFD200任务：|r崛起吧，勇士|n|n|cFFFFD200地区：|r邪能之槌号"
D.LocalClientValues[6398]="迫使目标攻击死亡骑士。"
D.LocalClientValues[6399]="生产一辆过载的攻城车。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n等制造完成后再回来验收货物。"
D.LocalClientValues[6400]="钢铁部落正打算用货车将一块元素符文运往黑石铸造厂。准备伏击。"
D.LocalClientValues[6401]="被腐蚀的野兽一直是诅咒林地中最大的祸害。坠星哨兵请求我们帮忙让这些可怜的生物从痛苦中解脱。"
D.LocalClientValues[6402]="避免怀疑"
D.LocalClientValues[6403]="追踪格里伏塔"
D.LocalClientValues[6404]="法术（减速）"
D.LocalClientValues[6405]="是时候去砍掉一些古树了。但提醒一下，你只能砍那些被恶魔腐蚀的古树。剩下的……如果你愿意，可以去抱抱他们。"
D.LocalClientValues[6406]="暴躁的火焰守护者"
D.LocalClientValues[6407]="风鹏湾"
D.LocalClientValues[6408]="边境增援"
D.LocalClientValues[6409]="泥沼"
D.LocalClientValues[6410]="缚火者卡格拉兹"
D.LocalClientValues[6411]="码头的压力"
D.LocalClientValues[6412]="指派到2级或3级兵营后可作为保镖陪伴你游历德拉诺。"
D.LocalClientValues[6413]="该任务涉及附魔专业。"
D.LocalClientValues[6414]="野蛮的波尔卡"
D.LocalClientValues[6415]="鸦过拔毛"
D.LocalClientValues[6416]="突袭邪火军械库"
D.LocalClientValues[6417]="在邪兽巢穴里，燃烧军团制造了新的魔法猎犬种类，它们的韧性异常恐怖。我们必须中断他们的行为，杀掉邪能哺育者阿格诺莎。"
D.LocalClientValues[6418]="想要与军团有一战之力，我们需要招募最无畏的恶魔猎手。"
D.LocalClientValues[6419]="大多数法师认为元素生物反复无常难以驾驭，但冰霜法师将水元素收为仆从已经有好几百年的历史了。"
D.LocalClientValues[6420]="邪能小鬼之牙"
D.LocalClientValues[6421]="开启要塞日常烹饪任务。"
D.LocalClientValues[6422]="狡猾的卡拉苏斯"
D.LocalClientValues[6423]="斯科瓦尔德仆从"
D.LocalClientValues[6424]="|cFFFFD200成就：|r利爪之王的传承"
D.LocalClientValues[6425]="骨喉"
D.LocalClientValues[6426]="我们在霜火岭发现了一辆老旧的食人魔篷车。不怀好意的野生动物已经包围了它。那辆车上装的好像是原油。"
D.LocalClientValues[6427]="传送门看护者"
D.LocalClientValues[6428]="叛徒们刚刚控制了这艘驱逐舰，风暴就来了，巨大的漩涡困住了这艘船。这可真不走运。有我们在，他们还会更加倒霉的。"
D.LocalClientValues[6429]="洛希恩灰熊的胃口极大，而崖翼之巢就在他们眼皮底下。对于饥饿的熊来说，实在是太过诱人。"
D.LocalClientValues[6430]="夜影扈从"
D.LocalClientValues[6431]="首领 (A)"
D.LocalClientValues[6432]="首领 (B)"
D.LocalClientValues[6433]="首领 (C)"
D.LocalClientValues[6434]="德拉诺黑血"
D.LocalClientValues[6435]="塔纳安丛林"
D.LocalClientValues[6436]="投石"
D.LocalClientValues[6437]="每周随机招募追随者。你可以指定你最感兴趣的专长和技能。"
D.LocalClientValues[6438]="魔誓防毒面具"
D.LocalClientValues[6439]="邪恶的瓦卡和她的船员曾经横行德拉诺诸海，肆无忌惮地抢劫船只，杀害船员。如今，这些因恶行而受到诅咒的家伙还在迁怒于生者。"
D.LocalClientValues[6440]="你可以下达工作订单，用职业大厅资源交易获得每周3个破碎命运印记中的1个。"
D.LocalClientValues[6441]="地区支援 - 风暴峡湾"
D.LocalClientValues[6442]="死兽人不需要靴子"
D.LocalClientValues[6443]="有人在夜间前往达拉然的墓地试图复活死者。我们必须进行调查，阻止这一切。"
D.LocalClientValues[6444]="熔炉可以生产出锻造所需的基本材料，以及战斗所需的护甲和武器。"
D.LocalClientValues[6445]="探查德拉诺：塔拉多"
D.LocalClientValues[6446]="风暴之翼雏龙"
D.LocalClientValues[6447]="特兰·蔑侧"
D.LocalClientValues[6448]="在白骨祭坛上交敌人的残骸，换取丰厚且强大的物品。\r\n\r\n你可以在要塞报告中查看生产进度。"
D.LocalClientValues[6449]="寒冷迷雾"
D.LocalClientValues[6450]="古老典籍"
D.LocalClientValues[6451]="先发制人"
D.LocalClientValues[6452]="冰浪"
D.LocalClientValues[6453]="绝不能让恶魔绕过我们位于恶魔小径的防御工事。快去增援侧翼。"
D.LocalClientValues[6454]="因暴露在恶魔能量下而慢慢退化的灰舌破碎者学会了不择手段生存下去，他们会在明处和暗处与敌人战斗。"
D.LocalClientValues[6455]="如果让虚空获胜，那与燃烧军团的战斗就毫无意义了。把玛凯雷的影卫虚灵赶出去。"
D.LocalClientValues[6456]="美妙的痛苦"
D.LocalClientValues[6457]="附魔研究室"
D.LocalClientValues[6458]="军团先锋"
D.LocalClientValues[6459]="至高岭的湖水中藏着一条巨鱼，让当地的部族惊恐不已。这条鱼也吓走了一些渔夫。"
D.LocalClientValues[6460]="部隊需要一頓大餐來慰勞一下，今天就宰山羊加菜好啦。"
D.LocalClientValues[6461]="就连冰封者乌戈洛克这么无能的食人魔都能靠奴隶攒起一大笔财富。但你得准备好承受他的魔法，万一它生效了呢。"
D.LocalClientValues[6462]="邪能图腾之友"
D.LocalClientValues[6463]="使你的追随者人数上限提升5，并可使用其他种族的卫士和战旗。"
D.LocalClientValues[6464]="奥古雷启迪者"
D.LocalClientValues[6465]="由武僧施放，可打断施法。"
D.LocalClientValues[6466]="最高阶的伊利达雷成员全身心接受了恶魔的力量和形态，变成了长翼的黑暗生物，能将敌人彻底消灭。"
D.LocalClientValues[6467]="一名农夫声称他知道许多塔拉多秘密宝藏的下落。如果我们帮他消灭破坏他家园的恶魔，他就愿意跟我们分享这些秘密。"
D.LocalClientValues[6468]="夜之子正在成群地屠杀月落角鹰兽，它们的巢穴正在受到攻击。我们必须阻止这一切。"
D.LocalClientValues[6469]="破碎天花板"
D.LocalClientValues[6470]="附魔武器"
D.LocalClientValues[6471]="图鲁克断崖的邪能图腾一直在伏击我们经过那里的部队。看来他们需要一点教训。"
D.LocalClientValues[6472]="首要任务"
D.LocalClientValues[6473]="神秘的魔鳞蜥蜴"
D.LocalClientValues[6474]="获得两块肥沃的土地，可以在上面播种和收割植物。每3天可以提供非常有用的物品，可在破碎群岛使用。"
D.LocalClientValues[6475]="使所有舰船完成任务所获得的经验值提高50%。"
D.LocalClientValues[6476]="霜火岭周围的严寒水域早已成为了应对冰封水域航行的训练场。"
D.LocalClientValues[6477]="好多新发现"
D.LocalClientValues[6478]="不眠之眼伊泽尔"
D.LocalClientValues[6479]="生存猎人"
D.LocalClientValues[6480]="追踪蔑潮：风暴幼龙"
D.LocalClientValues[6481]="至高岭的某处有一座强大的圣光信标。我们得找到它。"
D.LocalClientValues[6482]="我们在影月谷海岸的不同水深处准备了好几艘潜水艇。开上你的驱逐舰，去练习一下猎杀潜水艇的本领吧。"
D.LocalClientValues[6483]="武器回收"
D.LocalClientValues[6484]="|cFFFFD200职业：|r全职业|n|n|cFFFFD200任务：|r|n|n|cFFFFD200地区：|r卡拉赞"
D.LocalClientValues[6485]="虚空精魂"
D.LocalClientValues[6486]="废品站"
D.LocalClientValues[6487]="使完成任务后偶尔能回收到一些废品。"
D.LocalClientValues[6488]="听说有一个强大的新恶魔出现在了法罗纳尔。我们有必要去调查一下，以免它威胁到了我们对那个区域的控制力。"
D.LocalClientValues[6489]="谁主沉浮"
D.LocalClientValues[6490]="沃玛尔"
D.LocalClientValues[6491]="顺手牵羊"
D.LocalClientValues[6492]="上层精灵饰品"
D.LocalClientValues[6493]="比利·爆球"
D.LocalClientValues[6494]="|cFFFFD200职业：|r武僧|n|n|cFFFFD200任务：|r为胜利添砖加瓦|n|n|cFFFFD200地区：|r武僧战役"
D.LocalClientValues[6495]="砸脸"
D.LocalClientValues[6496]="如果不想老是“啊，如此弓……”的话，恶魔猎手们还是多用用这个技能比较好。"
D.LocalClientValues[6497]="大领主之军"
D.LocalClientValues[6498]="|cFFFFD200商人出售：|r贝斯卡·赤牙|n|cFFFFD200阵营：|r霜狼兽人 - 崇敬|n|cFFFFD200地区：|r阿什兰|n|cFFFFD200价格：|r5,000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t"
D.LocalClientValues[6499]="艾露恩的选择"
D.LocalClientValues[6500]="白鬼偷走了钢铁部落的一批武器。快赶在我们的敌人之前抢回这批军备吧，如有必要可以使用武力。"
D.LocalClientValues[6501]="能量吸取"
D.LocalClientValues[6502]="意外崩岩"
D.LocalClientValues[6503]="我们需要有人记录下德拉诺发生的灾难。快去纳格兰尽你所能地拍摄下一切吧。"
D.LocalClientValues[6504]="战歌的绝唱"
D.LocalClientValues[6505]="锋刃水晶"
D.LocalClientValues[6506]="危害（强大）"
D.LocalClientValues[6507]="恶魔，到处都是恶魔"
D.LocalClientValues[6508]="一艘可以在海上发动空中打击的战略性舰船，可用于海军行动。\r\n\r\n|cFFFFD200建造时间：2小时|r\r\n\r\n|cffb2f0ff应对舰船：|r\r\n|TInterface\\ICONS\\Ships_ABILITY_ArmorPiercingAmmo.blp:24:24:0:0|t |cffffffff战列舰|r"
D.LocalClientValues[6509]="军团大举入侵破碎海滩！我们需要立即派出援军对抗这一威胁。"
D.LocalClientValues[6510]="鲁克玛的化身"
D.LocalClientValues[6511]="一支长长的望远镜，但你透过它却什么都看不到，或许会派上用场。"
D.LocalClientValues[6512]="邪能战争"
D.LocalClientValues[6513]="战斗潜行者"
D.LocalClientValues[6514]="鸦人遗产"
D.LocalClientValues[6515]="钢铁部落正在从铁拳港运送重要的补给品。我们得派三个最强的士兵去干扰他们的行动。"
D.LocalClientValues[6516]="臭臭鱼"
D.LocalClientValues[6517]="燃烧军团先锋"
D.LocalClientValues[6518]="有棵名叫铁枝的被腐蚀的战争古树居住在沙拉尼尔被蹂躏的林地深处。其他梦魇生物都在朝它蜂拥而去。"
D.LocalClientValues[6519]="逆风小径"
D.LocalClientValues[6520]="希尔赛"
D.LocalClientValues[6521]="地区支援 - 联盟"
D.LocalClientValues[6522]="在埃索隆地区，玛凯雷与虚空之间的屏障很脆弱。别让影卫虚灵利用这个弱点。"
D.LocalClientValues[6523]="盐目钩刃战士"
D.LocalClientValues[6524]="制造灵魂之井"
D.LocalClientValues[6525]="复仇之灵"
D.LocalClientValues[6526]="用强风冲击干扰目标的注意力，应对|C00b3ffff法术|R。"
D.LocalClientValues[6527]="钢铁援兵"
D.LocalClientValues[6528]="燃烧军团的弹药都是在邪火军械库制造的。尽量多偷点出来。"
D.LocalClientValues[6529]="爆破专家麦加奇"
D.LocalClientValues[6530]="东瘟疫之地"
D.LocalClientValues[6531]="|cFFFFD200专业技能：|r钓鱼（700）|n|cFFFFD200任务：|r我们队里有渔夫|n|cFFFFD200地区：|r要塞，渔夫小屋"
D.LocalClientValues[6532]="水晶螃蟹"
D.LocalClientValues[6533]="为传送门供能：月光林地"
D.LocalClientValues[6534]="恐怖嚎叫"
D.LocalClientValues[6535]="附加在船后的渔网，由海象人友情赞助。可在任务成功后额外提供一批渔获。"
D.LocalClientValues[6536]="阴郁黎明"
D.LocalClientValues[6537]="|cFFFFD200职业：|r潜行者|n|n|cFFFFD200任务：|r雁过留痕|n|n|cFFFFD200地区：|r暗影大厅"
D.LocalClientValues[6538]="翔龙在天"
D.LocalClientValues[6539]="霜火岭有大量元素生物。鬣蜥人喜欢吃元素生物，而无论它们吃了什么，都能继承其力量。这可不大妙。"
D.LocalClientValues[6540]="亡灵术士"
D.LocalClientValues[6541]="瓦尔莎拉的德鲁伊正忙于应对萨特和梦魇。我们可以帮帮他们，摧毁疫病使者基兹法克斯所率领的萨特军团。"
D.LocalClientValues[6542]="蔓延的腐蚀"
D.LocalClientValues[6543]="我们从石怒崖救出的奴隶越多，血槌食人魔的力量就越衰落。"
D.LocalClientValues[6544]="紫兰妖花"
D.LocalClientValues[6545]="风暴幼龙"
D.LocalClientValues[6546]="我们的哨兵被吓坏了。夜里的时候，有些巨大的生物隐匿在黑暗之中，向他们发出尖啸和嚎叫。去找出这些在夜里制造恐怖的来源。"
D.LocalClientValues[6547]="风暴之锋"
D.LocalClientValues[6548]="动物园管理员"
D.LocalClientValues[6549]="不勝即亡！"
D.LocalClientValues[6550]="|cFFFFD200任务：|r海军上将泰勒|n|cFFFFD200地区：|r阿兰卡峰林"
D.LocalClientValues[6551]="拳手"
D.LocalClientValues[6552]="我们在战场上的士兵急需医疗补给，可沿途有战歌兽人的巡逻队。请护送车队安全抵达目的地吧。"
D.LocalClientValues[6553]="夜之子拥护者"
D.LocalClientValues[6554]="格罗姆卡先锋"
D.LocalClientValues[6555]="由猎人施放，可同时伤害许多敌人。"
D.LocalClientValues[6556]="我们可以使用影月氏族的武器来驾驭原始的魔力。快去突袭他们的营地，收集一些附魔武器回来。"
D.LocalClientValues[6557]="黑暗交易"
D.LocalClientValues[6558]="额外的矿工会在你的矿车里装满矿石和其它奇怪的东西。"
D.LocalClientValues[6559]="破碎的土地"
D.LocalClientValues[6560]="|cFFFFD200任务：|r深入敌后|n|cFFFFD200地区：|r传奇任务"
