D.LocalClientValues[6567]="侍从，过来！"
D.LocalClientValues[6568]="雷爪"
D.LocalClientValues[6569]="一艘毁灭性的潜水舰艇，可用于海军行动。\r\n\r\n|cFFFFD200建造时间：2小时|r\r\n\r\n|cffb2f0ff应对舰船：|r\r\n|TInterface\\ICONS\\Ships_ABILITY_Bombers.blp:24:24:0:0|t |cffffffff航母|r"
D.LocalClientValues[6570]="下水道怪兽兰希德斯"
D.LocalClientValues[6571]="邪铸毁灭者"
D.LocalClientValues[6572]="好奇害死虎"
D.LocalClientValues[6573]="我们在塔纳安的部队又搞到了一些装备，但就这么把它们运过来不太安全。派一艘运输舰和一艘驱逐舰去接应一下吧。"
D.LocalClientValues[6574]="恐怖幽魂"
D.LocalClientValues[6575]="皮装超模"
D.LocalClientValues[6576]="执行任务时有几率带回治疗石，用于为部队回复1点活力。"
D.LocalClientValues[6577]="军团大举入侵苏拉玛！我们需要立即派出援军对抗这一威胁。"
D.LocalClientValues[6578]="来自异世界的兽人入侵了我们的黑石山。真是讽刺。快去教训他们一下，让他们知道上一批入侵者的下场吧。"
D.LocalClientValues[6579]="巢母伊尔瓦"
D.LocalClientValues[6580]="剑圣姚素莱"
D.LocalClientValues[6581]="魔鳞蜥蜴大军"
D.LocalClientValues[6582]="白银之手圣殿骑士不仅武艺出类拔萃，举手投足更是正气凛然。只有同时拥有过人的勇武和纯洁的内心者才有资格晋升为勇士。"
D.LocalClientValues[6583]="布鲁泽"
D.LocalClientValues[6584]="即使在陨落之后，死亡之翼依然在身后留下无数毁灭的痕迹。卓格巴尔在山下大兴工事，他们可能获得了强大的神器。"
D.LocalClientValues[6585]="风暴猎犬"
D.LocalClientValues[6586]="启示之光"
D.LocalClientValues[6587]="非难的注视"
D.LocalClientValues[6588]="瓦拉加尔之力"
D.LocalClientValues[6589]="海妖萨塔薇丝"
D.LocalClientValues[6590]="叛徒之死"
D.LocalClientValues[6591]="你的斥候报告说我们在纳格兰的部队需要支援。"
D.LocalClientValues[6592]="能量爆发"
D.LocalClientValues[6593]="南海"
D.LocalClientValues[6594]="弯刀打击"
D.LocalClientValues[6595]="戈隆克星"
D.LocalClientValues[6596]="索克雷萨破坏行动"
