D.LocalClientValues[6601]="怨念精华"
D.LocalClientValues[6602]="你的勇士在成功完成任务后有几率带回勇士武器或装备。"
D.LocalClientValues[6603]="黏糊糊的工作"
D.LocalClientValues[6604]="驱逐舰是装甲厚实的高速舰船，擅长猎杀潜水艇。\r\n\r\n|cffb2f0ff应对舰船：|r\r\n|TInterface\\ICONS\\Ships_ABILITY_ArmorPiercingAmmo.blp:24:24:0:0|t |cffffffff战列舰|r"
D.LocalClientValues[6605]="森林余烬"
D.LocalClientValues[6606]="去死吧，燃烧军团！"
D.LocalClientValues[6607]="增加了额外的食品储备空间，可提高长途任务的成功率。"
D.LocalClientValues[6608]="复生猎犬"
D.LocalClientValues[6609]="奥特兰克山脉"
D.LocalClientValues[6610]="逆流从深渊中现身，将船只拖入海底。它正在摧毁我们位于塔纳安丛林和影月谷之间的联络线。"
D.LocalClientValues[6611]="碎地者伯格罗什"
D.LocalClientValues[6612]="突击队"
D.LocalClientValues[6613]="烂脸"
D.LocalClientValues[6614]="玛凯雷的破碎者虽然逃过了邪能的魔掌，却还是屈服于虚空的力量。少数灵媒克罗库虽然心智尚存，但还是无法摆脱与虚空的联系。"
D.LocalClientValues[6615]="提高与食人魔一起执行任务的成功率。"
D.LocalClientValues[6616]="据一枚古代卷轴记载，瓦尔莎拉的森林某处藏着一个泰坦通讯器，它能带给我们无价的知识。"
D.LocalClientValues[6617]="储备弹药"
D.LocalClientValues[6618]="统御意志"
D.LocalClientValues[6619]="战争横财"
D.LocalClientValues[6620]="碎手斩裂者"
D.LocalClientValues[6621]="深涌惩罚者"
D.LocalClientValues[6622]="释放囚犯"
D.LocalClientValues[6623]="沙漠里有食人魔！"
D.LocalClientValues[6624]="允许拥有炼金专长的追随者在此工作，提供特殊的奖励，并允许同时接受最多14份产品订单。"
D.LocalClientValues[6625]="只要稍加改装，这艘船运送的锁甲就能为我们所用了。"
D.LocalClientValues[6626]="我们的斥候报告说，戈尔隆德北部的一座山洞里住着一头名叫“蓝焰”戈尔高的古怪独眼魔。"
D.LocalClientValues[6627]="征调一队朱鹤弟子陪伴追随者执行任务，提高获得额外奖励的几率。\r\n\r\n|cFFFFD200建造时间：30分钟|r"
D.LocalClientValues[6628]="巨大且充满毁灭性的德拉诺巨人。"
D.LocalClientValues[6629]="积怨缚潮者"
D.LocalClientValues[6630]="隐秘通途"
D.LocalClientValues[6631]="兽栏可以为你的坐骑提供极大的增益。"
D.LocalClientValues[6632]="我们的斥候偶然发现了一支维库人的突击部队，他们都配备着流明石武器。我们可以对他们造成双重打击：消灭敌人，带走他们的武器为我们所用。"
D.LocalClientValues[6633]="独来独往"
D.LocalClientValues[6634]="一支庞大的军队正在备战。碾碎他们。"
D.LocalClientValues[6635]="阴云压城"
D.LocalClientValues[6636]="恶魔学识"
D.LocalClientValues[6637]="被俘的元素之怒"
D.LocalClientValues[6638]="踏风"
D.LocalClientValues[6639]="利奥达斯"
D.LocalClientValues[6640]="这座建筑可以存放并养护要塞的武器装备。"
D.LocalClientValues[6641]="切喉手"
D.LocalClientValues[6642]="入侵"
D.LocalClientValues[6643]="死亡标记"
D.LocalClientValues[6644]="惡魔遭遇戰1"
D.LocalClientValues[6645]="惡魔遭遇戰2"
D.LocalClientValues[6646]="传送门守护者拉佐洛斯"
D.LocalClientValues[6647]="缚魂者尼娅米的灵魂"
D.LocalClientValues[6648]="石槌氏族对岗哨废墟的突袭失败了，那里如今到处都是食人魔尸体。去他们身上寻找一块消魔之石吧！"
D.LocalClientValues[6649]="召唤末日守卫"
D.LocalClientValues[6650]="星辰之怒"
D.LocalClientValues[6651]="艾露恩印记"
D.LocalClientValues[6652]="矿井守卫"
D.LocalClientValues[6653]="像旋风一般挥舞手中的武器，应对|C00b3ffff爪牙|R。"
D.LocalClientValues[6654]="骷髅，尖刺，一切顺利"
D.LocalClientValues[6655]="虚空精华"
D.LocalClientValues[6656]="地狱咆哮在部落位于阿什兰的主基地附近布置了一艘潜水艇。去击沉它。虽然你是联盟，但也责无旁贷。相比大局，阵营仇恨就显得无足轻重了。"
D.LocalClientValues[6657]="俘虏招供说，古尔丹的旗舰最后一次出现，就是在这片危险的浅滩内。"
D.LocalClientValues[6658]="邪恶尖啸者"
D.LocalClientValues[6659]="恐魂毁灭者"
D.LocalClientValues[6660]="泰坦之血"
D.LocalClientValues[6661]="杀掉平原上的原兽。"
D.LocalClientValues[6662]="秘密通道"
D.LocalClientValues[6663]="我们的工程师最喜欢将攻城武器拆成零件了。快去弄一架回来让他们过过瘾吧。"
D.LocalClientValues[6664]="蜂拥的卓格巴尔"
D.LocalClientValues[6665]="宁静大师"
D.LocalClientValues[6666]="剧毒湖水"
D.LocalClientValues[6667]="由牧师施放，可移除一个有害魔法效果。"
D.LocalClientValues[6668]="一些火刃氏族的大人物想要跟钢铁部落的首领谈谈战略问题。如果他们无法见面，那该多么遗憾呐。"
D.LocalClientValues[6669]="暗礁领主拉希斯"
D.LocalClientValues[6670]="龙之决心"
D.LocalClientValues[6671]="沙兰"
D.LocalClientValues[6672]="地穴"
D.LocalClientValues[6673]="元素守护者"
D.LocalClientValues[6674]="被军官布莱德、雅克森和普米洛发现"
D.LocalClientValues[6675]="虫语集群"
D.LocalClientValues[6676]="不速之客"
D.LocalClientValues[6677]="幽魂之咬"
D.LocalClientValues[6678]="驯犬者伊莱"
D.LocalClientValues[6679]="火焰之息"
D.LocalClientValues[6680]="只要你的部队摧毁邪火军械库，圣光军团就可以拖慢燃烧军团的增援速度了。"
D.LocalClientValues[6681]="奇袭黑鸦堡"
D.LocalClientValues[6682]="阿古斯警卫"
D.LocalClientValues[6683]="多头威胁"
D.LocalClientValues[6684]="任务成功率提高。"
D.LocalClientValues[6685]="激浪"
D.LocalClientValues[6686]="肯瑞托卫士"
D.LocalClientValues[6687]="鸦人已经开始偷窃和储藏黄金了。是时候把它们偷回来了。"
D.LocalClientValues[6688]="霍亚拉"
D.LocalClientValues[6689]="据说泰坦监护者们会亲自观察风暴峡湾的所有居民，观察那些有资格进入神殿的人。证明我们的价值吧。"
D.LocalClientValues[6690]="危害（减速）"
D.LocalClientValues[6691]="奥术占卜"
D.LocalClientValues[6692]="无声的愤怒"
D.LocalClientValues[6693]="为了削弱雷神氏族，我们必须消灭他们最凶猛的战士——裂蹄牛骑兵。快去他们的营地放走他们的坐骑吧。"
D.LocalClientValues[6694]="严寒的极地。"
D.LocalClientValues[6695]="由术士施放，可抵挡大量伤害。"
D.LocalClientValues[6696]="要塞边界"
D.LocalClientValues[6697]="蓟槌"
D.LocalClientValues[6698]="黑暗收割议会珍藏"
D.LocalClientValues[6699]="巨魔遭遇戰1"
D.LocalClientValues[6700]="巨魔遭遇戰2"
D.LocalClientValues[6701]="埃匹希斯枢纽"
D.LocalClientValues[6702]="卑劣行径"
D.LocalClientValues[6703]="遗物猎人：鲁克玛护符"
D.LocalClientValues[6704]="辛菲儿在与古加尔的战斗中使用的法杖应该足以用于创造灵魂链接，但首先我们得找到它。"
D.LocalClientValues[6705]="德拉诺的元素生物。"
D.LocalClientValues[6706]="连结陷阱"
D.LocalClientValues[6707]="我偏要拿走你的蜡烛"
D.LocalClientValues[6708]="丛林补给"
D.LocalClientValues[6709]="百步穿杨"
D.LocalClientValues[6710]="酒醒入定"
D.LocalClientValues[6711]="一天一苹果，军团远离我"
D.LocalClientValues[6712]="幕后交易"
D.LocalClientValues[6713]="最近，奥鲁纳海岸的地狱咆哮部队越来越少了。如今，部落已经大着胆子把那里当成卸货点了。"
D.LocalClientValues[6714]="地区支援 - 瓦尔莎拉"
D.LocalClientValues[6715]="骨语切割者"
D.LocalClientValues[6716]="埃匹希斯风暴"
D.LocalClientValues[6717]="挑战任务"
D.LocalClientValues[6718]="燃皮吟咏者"
D.LocalClientValues[6719]="并不是所有人都有一对神器战刃。如果要进攻一个恶魔世界，那么伊利达雷的武器最好应该改良一番。"
D.LocalClientValues[6720]="炉石专家"
D.LocalClientValues[6721]="雷霆寂灭"
D.LocalClientValues[6722]="野性成长"
D.LocalClientValues[6723]="解锁一名提供虚空仓库和幻化服务的虚灵商人，并使所有建筑的活跃产品订单数提升15。"
D.LocalClientValues[6724]="部落部队计划攻击冰痕坟场。如果他们失败了，遇难者就会成为暗影议会的邪恶巫术的能量来源。我们要不惜一切代价阻止部落。"
D.LocalClientValues[6725]="巨大噪声！"
D.LocalClientValues[6726]="兹吉牌X3-9锯末机器人"
D.LocalClientValues[6727]="符文先知法尔加"
D.LocalClientValues[6728]="霜彘海礁毫无战略价值，根本不值得出动航母巡视。但部落发现了我们出口本地野猪的计划，情况就不一样了。"
D.LocalClientValues[6729]="阴森的守夜人"
D.LocalClientValues[6730]="古尔瓦步兵"
D.LocalClientValues[6731]="黑暗拷问者"
D.LocalClientValues[6732]="战锤议会是可怕的敌人。"
D.LocalClientValues[6733]="圣光之剑"
D.LocalClientValues[6734]="野生怪物入侵"
D.LocalClientValues[6735]="借个火？"
D.LocalClientValues[6736]="破碎之野的战斗最为激烈。快去帮部队占得上风。"
D.LocalClientValues[6737]="允许拥有裁缝专长的追随者在此工作，提供特殊的奖励，并允许同时接受最多14份产品订单。"
D.LocalClientValues[6738]="可怕的研究"
D.LocalClientValues[6739]="外域战术家"
D.LocalClientValues[6740]="狂奔怒吼"
D.LocalClientValues[6741]="曾效忠瓦丝琪和凯尔萨斯的纳迦部族库斯卡将他们的忠仆训练成强大勇猛的战士。"
D.LocalClientValues[6742]="刃牙虎人的伏击"
D.LocalClientValues[6743]="海拉的地狱犬本就是令人恐惧的捕食者了，而芬里这三头野兽是专为恐惧和绝望而生的。在冥狱深渊的深处找到他。"
D.LocalClientValues[6744]="提高与德莱尼一起执行任务的成功率。"
D.LocalClientValues[6745]="|cFFFFD200职业：|r死亡骑士|n|n|cFFFFD200任务：|r冲锋陷阵！|n|n|cFFFFD200地区：|r死亡骑士战役"
D.LocalClientValues[6746]="一个首领，一支军队，一个法术。"
D.LocalClientValues[6747]="净化不洁者"
D.LocalClientValues[6748]="见习战列舰"
D.LocalClientValues[6749]="勇气号角"
D.LocalClientValues[6750]="这是一座曾经废弃的矿井，但它的地下依然有着丰富的矿产在等待着人们的发掘。"
D.LocalClientValues[6751]="刃月木精"
D.LocalClientValues[6752]="燃皮问题"
D.LocalClientValues[6753]="猎人印记"
D.LocalClientValues[6754]="奴隶主奥克默克"
D.LocalClientValues[6755]="狼群守护者号"
D.LocalClientValues[6756]="向你的敌人投掷一把恶魔利刃，应对|C00b3ffff爪牙|R。"
D.LocalClientValues[6757]="患难见真情"
D.LocalClientValues[6758]="野心勃勃的通灵师艾维斯"
D.LocalClientValues[6759]="滥砍滥伐"
D.LocalClientValues[6760]="旅行者的背包"
D.LocalClientValues[6761]="至高山岭"
D.LocalClientValues[6762]="西瘟疫之地"
D.LocalClientValues[6763]="白虎高手经过勤学苦练，出手迅如闪电。他们知道克制自己等待完美的出手时机，远比用猛力强攻更为重要。"
D.LocalClientValues[6764]="沉默"
D.LocalClientValues[6765]="攻城大师沃兰"
D.LocalClientValues[6766]="魔古疯石"
D.LocalClientValues[6767]="熔火之核納沙"
D.LocalClientValues[6768]="燃烧军团在风暴峡湾的东海岸发动了一波攻击。我们的猎人可以从峭壁之上发起远程打击，保护下方的步兵。"
D.LocalClientValues[6769]="不需要蟹笼"
D.LocalClientValues[6770]="狼犬伙伴"
D.LocalClientValues[6771]="当你在德拉诺的野外区域时，可在水下无限呼吸并从高处安全降落。同时开启宿敌系列任务，要求你击败特定种族的玩家。"
D.LocalClientValues[6772]="结实的旅行靴"
D.LocalClientValues[6773]="鲁格多尔"
D.LocalClientValues[6774]="我们的伤员都被困在破碎海滩上了！派我们的勇士去把他们带回家吧。"
D.LocalClientValues[6775]="奥金顿内的一座传送门连通了德拉诺和恶魔的世界阿古斯。快去彻底摧毁传送门，切断燃烧军团的后援。"
D.LocalClientValues[6776]="破坏魔的踪迹"
D.LocalClientValues[6777]="抢走他们的蛋！"
D.LocalClientValues[6778]="打入尘埃"
D.LocalClientValues[6779]="我们正在接近弗蕾亚之泉，但这片区域是由一个卓格巴尔酋长看守，他自称为山丘之王。击败他们，我们就可以获得奖励！"
D.LocalClientValues[6780]="斗争局势"
D.LocalClientValues[6781]="食人魔药剂"
D.LocalClientValues[6782]="候选者的职责"
D.LocalClientValues[6783]="大坏蛋沃尔菲"
D.LocalClientValues[6784]="让圣光照亮炼魂熔炉，别再让燃烧军团的引擎吞噬更多的灵魂了。"
D.LocalClientValues[6785]="几个世纪以来，守夜人一直守护着纳萨拉斯的安全和美丽。现在，它已经落入纳迦之手，甚至他们自己的灵魂也背叛了他们。"
D.LocalClientValues[6786]="爪牙（强大）"
D.LocalClientValues[6787]="你的斥候报告说我们在霜火岭的部队需要支援。"
D.LocalClientValues[6788]="花费10份材料，随机招募一名拥有特殊专长、技能或职责的追随者。"
D.LocalClientValues[6789]="邪焰爪牙"
D.LocalClientValues[6790]="迁跃掠食者"
D.LocalClientValues[6791]="崇山之灵"
D.LocalClientValues[6792]="隐秘保护：保卫达拉然"
D.LocalClientValues[6793]="奥克泰尔·龙血"
D.LocalClientValues[6794]="麦罗克，图鲁克之子是新的邪能图腾部落的领袖，他向燃烧军团宣誓效忠。守望者请求我们解决他。"
D.LocalClientValues[6795]="元素外交"
D.LocalClientValues[6796]="在风暴天气中航行，你只需要担心三件事：狂风吹袭，电闪雷鸣以及凶猛的海浪。"
D.LocalClientValues[6797]="遗物猎人：古特里克的杀生刀"
D.LocalClientValues[6798]="在堕夜精灵攻击了护月要塞后，许多月落助祭依然被困在那里。派人过去，给他们提供帮助。"
D.LocalClientValues[6799]="防洪保护"
D.LocalClientValues[6800]="赛拉·月卫请求我们追踪一个名为斯库瓦克斯的萨特的下落，无论将其抓获或击杀均可。他最后出现的地点在潮汐沼泽。"
D.LocalClientValues[6801]="头部损伤"
D.LocalClientValues[6802]="天选之人"
D.LocalClientValues[6803]="由武僧施放，可显著降低所受的伤害。"
D.LocalClientValues[6804]="可以在要塞水域内钓到巨型德拉诺鱼类。并使你有一定几率在要塞水域内钓到特殊鱼类。这种鱼可以将神秘生物引到海滩上来。"
D.LocalClientValues[6805]="牛出没"
D.LocalClientValues[6806]="覆巢之下"
D.LocalClientValues[6807]="头发花白的老兵，对阿古斯了如指掌，可应对|C00b3ffff阿古斯精英|R。"
D.LocalClientValues[6808]="这是作弊！"
D.LocalClientValues[6809]="狗头人传说中，在至高岭的洞穴深处，有一个吞噬一切的黑暗存在。这也是狗头人那么怕黑的原因。"
D.LocalClientValues[6810]="正面强攻"
D.LocalClientValues[6811]="作为一名曾经的肯瑞托图书管理员，被驱逐的诺曼提斯绝对不会原谅玛里苟斯和蓝龙军团在诺森德所造成的破坏。"
D.LocalClientValues[6812]="飓风"
D.LocalClientValues[6813]="你在骑乘状态下穿过德拉诺的野外区域时，不会被敌人晕眩。"
D.LocalClientValues[6814]="在奥金顿的地下深处，纳鲁德欧里已经再生，成为纯净的圣光存在。到这座神圣之所看一看。"
D.LocalClientValues[6815]="建筑"
D.LocalClientValues[6816]="为传送门供能：灰谷"
D.LocalClientValues[6817]="别被骗了。它们看似可爱，却能够一拥而上，把你的脸咬烂。"
D.LocalClientValues[6818]="恐怖图腾的战士战斗的目的是消灭牛头人的敌人。对恐怖图腾来说，几乎所有种族都是牛头人的敌人。但是，只要玛加萨还留在大漩涡，恐怖图腾就会协助大地之环。"
D.LocalClientValues[6819]="断体劈砍"
