D.LocalClientValues[6821]="每周免费获得三种既定命运印记中的一种（团队额外拾取机会）。"
D.LocalClientValues[6822]="永茂林地"
D.LocalClientValues[6823]="一帮鱼人在沉船海湾的废墟中建立了营地。清理掉它们。"
D.LocalClientValues[6824]="虚空脉冲"
D.LocalClientValues[6825]="瓦尔莎拉的森林并不适合独自闲逛。每棵树后面可能都会潜伏着危险，有的时候危险就在眼前。"
D.LocalClientValues[6826]="蠢蠢欲动的梦魇"
D.LocalClientValues[6827]="工业间谍"
D.LocalClientValues[6828]="如果我們要返回破碎海岸，就需要更多支援。去找其他職業的領袖，尋求他們協助。"
D.LocalClientValues[6829]="钢铁部落发现了一艘偷偷靠近他们堡垒的潜水艇，就迫不及待地扑了上去。遗憾的是，那只是一只淡水兽。"
