D.LocalClientValues[6884]="夜之子一直在织星圣殿中抽取能量，召唤恐怖的纯能量形态的生物。"
D.LocalClientValues[6885]="我们在一个墓地附近扎营，但鬼怪在夜里复活了，开始攻击我们！"
