D.LocalClientValues[6888]="阿格拉玛的化身"
D.LocalClientValues[6889]="碎手步兵"
D.LocalClientValues[6890]="鞭尾"
D.LocalClientValues[6891]="虫爪女巫"
D.LocalClientValues[6892]="在通天峰的顶上，高阶鸦人正在制造可充当战争武器的机械构装体。快去阻止他们，但要小心他们的恐惧渡鸦守卫。"
D.LocalClientValues[6893]="枯法狂热者"
D.LocalClientValues[6894]="每天可以使用一次银色军马马桩，使用后召唤一匹军马，使你能在短时间内在坐骑上作战。"
D.LocalClientValues[6895]="鹰身人正在至高岭散布邪恶的诅咒。只有死亡才能阻止她们。"
D.LocalClientValues[6896]="邪悲恶棍"
D.LocalClientValues[6897]="分选者泰瑞克"
D.LocalClientValues[6898]="从嘲颅氏族的传奇杀手那里夺取被诅咒的颅骨面具。"
