D.LocalClientValues[6901]="铁齿铜牙"
D.LocalClientValues[6902]="清理沼泽"
D.LocalClientValues[6903]="食腐鸟正在啄食那些死者。快去干掉它们，以便我们自己回收一些物资。"
D.LocalClientValues[6904]="黑潮工程师"
D.LocalClientValues[6905]="血鬃氏族残忍的战争虎王偷走了流亡者的圣卷，《塞泰克之梦》。"
D.LocalClientValues[6906]="夜之子卡德乌斯在苏拉玛倒塌的塔楼废墟中游荡，威胁着道路和附近的旅行者。"
D.LocalClientValues[6907]="异种酊剂"
D.LocalClientValues[6908]="7.0 提示假人 - 装备 - 蓝色 - 世界任务金币"
D.LocalClientValues[6909]="减速"
D.LocalClientValues[6910]="生命吸取"
D.LocalClientValues[6911]="我们这儿需要一位战术大师。此外，我们可能还想要一些签名。"
D.LocalClientValues[6912]="被指派到矿井时可提高产品订单的产量。"
D.LocalClientValues[6913]="荆棘大师萨尔顿"
D.LocalClientValues[6914]="军队训练假人"
D.LocalClientValues[6915]="恶魔猎手的技能，用于同时控制多个危险的敌人。"
D.LocalClientValues[6916]="这艘潜水艇好不容易才返回基地准备修缮，却发现港口已经几近废弃。我们来拖住其他地方的敌人，你去干掉那艘潜艇。"
D.LocalClientValues[6917]="巫师萨奇尔是最早学会召唤和控制恶魔的艾瑞达人之一。如果我们能找到他的颅骨下落，那将成为强大的武器。"
D.LocalClientValues[6918]="信仰飞跃"
D.LocalClientValues[6919]="便携式传送器"
D.LocalClientValues[6920]="移动药圃"
D.LocalClientValues[6921]="腐蚀地面，造成暗影伤害，应对|C00b3ffff爪牙|R。"
D.LocalClientValues[6922]="沉睡"
D.LocalClientValues[6923]="你的勇士听说有个永不落幕的战场。在那里，局势瞬息万变。派他们去深入调查一下吧。"
D.LocalClientValues[6924]="狂暴的猎风者"
D.LocalClientValues[6925]="由于在戈尔隆德的栖息地发生变化，多头蛇开始蚕食德莱尼的定居点了。这很遗憾，但我们必须消灭这些绝望的野兽。"
D.LocalClientValues[6926]="怒爪"
D.LocalClientValues[6927]="暗翼低语者"
D.LocalClientValues[6928]="夜之子复国者分队"
D.LocalClientValues[6929]="黑石情报"
D.LocalClientValues[6930]="安全地带"
D.LocalClientValues[6931]="钢铁烈焰先知"
D.LocalClientValues[6932]="钢铁部落正在破碎之脊挖掘失落已久的食人魔神器——快去赶走他们，将他们的收获据为己有。"
D.LocalClientValues[6933]="鹰身人搬进了泰安诺的废墟，用他们污秽的巢穴毁灭了那些曾经美丽的建筑。消灭他们。"
D.LocalClientValues[6934]="咆哮的主母"
D.LocalClientValues[6935]="在遗忘王者的领地，奥克泰尔·龙血不再呆在墓穴中安息。他是第一批骑乘巨龙的人之一。击败他。"
D.LocalClientValues[6936]="欧妮娅拉需要帮助"
D.LocalClientValues[6937]="打断敌人施法，应对|C00b3ffff法术|R。"
D.LocalClientValues[6938]="悬槌特使护卫"
D.LocalClientValues[6939]="至高岭牛头人向我们请求援军，帮他们保护雷霆图腾免受卓格巴尔的入侵。我们要帮助他们守住边境。"
D.LocalClientValues[6940]="火车就是势不可挡的象征，可你从不相信命运。这很好：有一座巨型公共设施正等着你去摧毁。"
D.LocalClientValues[6941]="我们收到报告说，热砂保护协会在废弃的战歌岗哨开辟了一个新的挖掘场。既然有现成的便宜可捡，干嘛还要等他们来动手呢？"
D.LocalClientValues[6942]="黑暗迷失之爪"
D.LocalClientValues[6943]="商人每天到访一次，出售各种货物，并允许你用生产材料换取要塞物资。"
D.LocalClientValues[6944]="坠月旅店"
D.LocalClientValues[6945]="占领风暴峡湾的大门"
D.LocalClientValues[6946]="提高与巨魔一起执行任务的成功率。"
D.LocalClientValues[6947]="燃烧军团的战舰都停靠在终端船坞，等装载好士兵和物资后再出发袭击艾泽拉斯。去把这些战舰打下来。"
D.LocalClientValues[6948]="极致恐惧"
