D.LocalClientValues[6952]="利爪克星"
D.LocalClientValues[6953]="搜索登陆点"
D.LocalClientValues[6954]="腐臭实验室正在通过邪恶的实验制造更加强大的恶魔。去把那些安托兰塑灵师消灭掉，就能中断他们的实验了。"
