D.LocalClientValues[6960]="重击"
D.LocalClientValues[6961]="野生枯皮公牛"
D.LocalClientValues[6962]="原祖荆兽和木精的硬化外壳可以强化我们的护甲。无论采用何种手段，去帮我们搞一些来吧。"
D.LocalClientValues[6963]="只要有潜水设备和一点运气，水下攻击可能是我们潜入守卫森严的钢铁码头的最好办法。"
