D.LocalClientValues[6982]="鼠王子"
D.LocalClientValues[6983]="要是我们偷走这批运往联盟的靴子，让光脚的联盟法师绊倒摔死，这算不算是部落的胜利呢？而且，那些可是新靴子。"
