D.LocalClientValues[6987]="光铸者铁匠很乐意为我们的勇士打造装备。快去帮他们收集必须的材料吧。"
D.LocalClientValues[6988]="鲜血狩猎"
D.LocalClientValues[6989]="植物造反"
D.LocalClientValues[6990]="“我们抓来的维库囚犯用怪异而悲伤的眼神看着死去的同伴。就好像他们羡慕死者一样。”——瓦里安·乌瑞恩国王"
