D.LocalClientValues[6994]="暮皮啸狼群"
D.LocalClientValues[6995]="重铸最野蛮的角斗士的武器，在鲜血之环大打一场。"
D.LocalClientValues[6996]="来自奸商的利润"
D.LocalClientValues[6997]="暗礁巨人"
D.LocalClientValues[6998]="废品站可以把别人的垃圾变成你的宝物。"
D.LocalClientValues[6999]="敌人之血：瓦尔莎拉"
D.LocalClientValues[7000]="茉艾拉之锤号"
D.LocalClientValues[7001]="我们抓获的一名小鬼俘虏供认说他的主人们正计划攻打至高岭的一处牛头人村落。我们得搞清楚是哪一处。"
D.LocalClientValues[7002]="西北边的术士正在摄取大地中的生命力，想用这些力量召唤出一个恶魔领主。所以呢？别再干站着了！"
