D.LocalClientValues[7066]="成群结队！"
D.LocalClientValues[7067]="|cFFFFD200任务：|r团结一致|n|cFFFFD200地区：|r阿兰卡峰林"
D.LocalClientValues[7068]="你发现了古尔丹的旗舰！快利用风向干掉护航的航母……"
D.LocalClientValues[7069]="如果你真想加入热砂保护协会，那你一定得仔细留意悬槌神器。"
D.LocalClientValues[7070]="操纵奥术之力，以压倒性的能量毁灭敌人，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[7071]="现在我们已经招募了一些新兵，可以把他们投入到战场中了。愤怒卫士瓦里托斯带领恶魔攻击了壁炉谷。我们派遣勇士去支援当地的人民吧。"
