D.LocalClientValues[7078]="信徒太阳祭司"
D.LocalClientValues[7079]="阿古斯废土上有些偏远区域，就连燃烧军团也很少去那里。去侦察一下那些地区，看看能不能弄到一些没被邪能腐化的资源。"
