D.LocalClientValues[7084]="恶魔依然从苏拉玛的地底不断涌出。我们必须挡住他们。"
D.LocalClientValues[7085]="我们已经招募了一些部队，可以用来为勇士提供增援。积怨纳迦惊扰了一个巨型水元素。"
D.LocalClientValues[7086]="沃克·黑舌"
D.LocalClientValues[7087]="每一年，大群裂蹄牛都会穿越戈尔隆德，使大地震动，尘土飞扬。我们必须让它们远离我们的营地。"
D.LocalClientValues[7088]="影月氏族的施法者正在特鲁纳观星台附近实验不稳定的虚空魔法。因此我们必须阻止他们。"
