D.LocalClientValues[7091]="到此为止"
D.LocalClientValues[7092]="酒仙"
D.LocalClientValues[7093]="利用採礦得到的德拉諾之石生產一份礦石。\r\n\r\n你可以在要塞報告裡檢視產品進度。\r\n\r\n當完成時即可返回要塞領取產品。"
D.LocalClientValues[7094]="恶上加恶"
D.LocalClientValues[7095]="我们正在留意那些可能会对组织有所贡献的猎人。征募官乐娜拉是位著名的部队训练师，但她遭受了攻击！派罗伦·雷蹄去帮助她。"
D.LocalClientValues[7096]="教团的助祭往往刚踏上他们的修行之路，他们有着强烈的求知欲，满怀热情地接受指导和执行任务。"
D.LocalClientValues[7097]="魔鳞主母"
D.LocalClientValues[7098]="冷酷主母"
D.LocalClientValues[7099]="转化"
D.LocalClientValues[7100]="皮里克斯"
D.LocalClientValues[7101]="生产一辆过载的攻城坦克。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n等制造完成后再回来验收货物。"
D.LocalClientValues[7102]="光铸纪念品"
D.LocalClientValues[7103]="允许拥有草药学专长的追随者在此工作，提供特殊的奖励。同时并提高药圃的草药产量，并允许同时接受最多14份产品订单。"
D.LocalClientValues[7104]="昏暗光芒"
D.LocalClientValues[7105]="尽管单个食尸鬼在力量和智能方面都很弱，但它们能够凭借压倒性的数量，充当黑锋骑士团的战力之一。"
D.LocalClientValues[7106]="戈尔隆德的原祖荆兽正在它们的领地内大肆捕猎，并抢劫附近的德莱尼营地里的食物。去攻击它们，将它们引走吧。"
D.LocalClientValues[7107]="突破要塞"
D.LocalClientValues[7108]="海洋巨人的奴役"
D.LocalClientValues[7109]="大法师瓦格斯的旅行：最好的朋友"
D.LocalClientValues[7110]="纳萨拉斯学院曾经是个求学氛围浓厚的地方。虽然现在已经成为了废墟，但我们知道大法师瓦格斯最近到访过这里。"
D.LocalClientValues[7111]="|cFFFFD200搏击俱乐部|r5级"
D.LocalClientValues[7112]="钢牙"
D.LocalClientValues[7113]="燃烧哨兵"
D.LocalClientValues[7114]="在黑鸦堡垒的深处，就连军队用的刃豹也被复活了。刃豹的主母黑暗之影正看护着她可怕的子嗣。"
D.LocalClientValues[7115]="被指派到熔炉时可降低你的物品耐久损失，提高产品订单的产量，以及锻造任务的成功率。"
D.LocalClientValues[7116]="上交食人魔道标石，换取埃匹希斯水晶以及加急任务指令。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n等生产完成后，记得回来接收货物。"
D.LocalClientValues[7117]="即使是在影子形态下，萨维斯也能将他的力量延伸到沙拉达希尔，折磨我们的盟友。我们必须调查腐蚀的情况。"
D.LocalClientValues[7118]="直取要害"
D.LocalClientValues[7119]="一只浸水的箱子被冲上了海岸。快冲破钢铁部落的封锁，把它弄回来。"
D.LocalClientValues[7120]="永燃末日使者"
D.LocalClientValues[7121]="至高岭的鹰身人会抓住一切机会骚扰和诅咒我们的盟友，偷走我们的补给。我们应该把他们的巢穴作为目标。"
D.LocalClientValues[7122]="入侵准备：抓捕"
D.LocalClientValues[7123]="一片多山的区域。"
D.LocalClientValues[7124]="要塞守卫将巡视你的矿井，驱逐充满敌意的鬣蜥人。"
D.LocalClientValues[7125]="泽诺比亚"
D.LocalClientValues[7126]="释放力量"
D.LocalClientValues[7127]="一条邪恶的风蛇似乎在其幕后主子的指使下削弱我们的防御。去找出并解决这个威胁。"
D.LocalClientValues[7128]="你已经逼得古尔丹的旗舰搁浅了，可现在它所有的火炮都对准了海面。你要做好最坏的打算。"
D.LocalClientValues[7129]="梦魇将曾经美丽的生物转化为了扭曲的幻象。怒爪曾经是只威猛的角鹰兽，现在却把我们的盟友当作猎物。"
D.LocalClientValues[7130]="幽灵争斗者"
D.LocalClientValues[7131]="搜索档案"
D.LocalClientValues[7132]="你的斥候报告说我们在阿兰卡峰林的部队需要支援。"
