D.LocalClientValues[7148]="暗影突袭"
D.LocalClientValues[7149]="熔岩蛛网"
D.LocalClientValues[7150]="先到先得"
D.LocalClientValues[7151]="有一群戈隆和独眼魔来袭击我们，结果这群笨蛋却自己打起来了。快去干掉他们，终止这场闹剧吧。"
