D.LocalClientValues[7153]="避重就轻"
D.LocalClientValues[7154]="脏手"
D.LocalClientValues[7155]="据说，再来一杯的鲁希安痛失了一批异香奶酪。显然那位送货员是在穿越达拉然下水道时遭遇了不测。"
