D.LocalClientValues[7158]="钢铁部落及其爪牙已经“强势”拒绝了撤出我们的黑石山。那就从他们的尸体上收点租金回来吧。"
D.LocalClientValues[7159]="治疗之泉图腾"
D.LocalClientValues[7160]="引导组织的怒火，为裂隙之核充能，让你可以部署裂隙火炮，完成一个世界任务。"
