D.LocalClientValues[7189]="不朽的灵魂潜藏风暴峡湾的峭壁之中。尽管他们已经故去多年，依然在那里守望着。让他们从守望中解脱吧。"
D.LocalClientValues[7190]="仗剑为生"
D.LocalClientValues[7191]="一艘能够发现并攻击附近敌对舰船的飞艇，可提高任务的成功率。"
