D.LocalClientValues[7213]="艾里塔克"
D.LocalClientValues[7214]="根据兽栏管理员的说法，只有特定的夜之子贵族受到了此次狩猎的邀请。派出你的勇士，前去询问尼姆罗德领主关于此次狩猎的情况。"
