D.LocalClientValues[7224]="食人魔那巨大、沉重的长剑久负盛名。将这些武器分解可以得到大量魔法尘。"
D.LocalClientValues[7225]="一艘敌方航母守住了海峡入口。如果我们干掉它的话，就能突袭北边的沙蟹海滩，切断联盟通向南方的补给线了。"
D.LocalClientValues[7226]="专注战备"
