D.LocalClientValues[7280]="以不竭的动力乘风破浪，飞速前行。赶上它你就成功了一半，另一半就得靠真刀真枪了。"
D.LocalClientValues[7281]="格拉哈姆·银爪是一位具有巨大潜力的年轻德鲁伊，他带领我们的斥候前往了苏拉玛的边缘地区。但他碰到了军团的捕猎活动，需要支援。"
