D.LocalClientValues[7323]="珠宝店"
D.LocalClientValues[7324]="恶魔卫士毁灭者"
D.LocalClientValues[7325]="风暴幼龙通常是群居生活，或者被维库人驯服，但有只孤独的幼龙却并非如此，它捕食所有的猎物。"
D.LocalClientValues[7326]="通常我们并不会太在意一只以鱼人为食的海巨人。但是囤积者博达什开始把所有接近他栖息地的目标当作食物了。"
D.LocalClientValues[7327]="死亡之雾"
D.LocalClientValues[7328]="运气也是实力的一部分"
D.LocalClientValues[7329]="我们在法罗纳尔的魔能熔池遗失了一些重要的信件。把它们取回来。"
