D.LocalClientValues[7355]="虽然瓦尔莎拉的大部分地区都已遭到蹂躏，但那些被腐蚀的植物可能会提供珍贵的信息，让我们得以了解梦魇的特性。"
D.LocalClientValues[7356]="塔尔加斯的战舰就在基尔加丹平台上方。有它在，燃烧军团就能控制这片区域。设法把它解决掉。"
D.LocalClientValues[7357]="黑锋寒霜骑士"
D.LocalClientValues[7358]="从银色黎明的时代开始，圣光之愿礼拜堂就一直是圣光在艾泽拉斯大陆上的信标和灯塔。前去那里收集一块圣光的碎片。"
D.LocalClientValues[7359]="艾瑞达法师他们正在使用军团传送门将援军召唤到破碎海滩上。如果不阻止他们，我们永远都别想建立稳定的阵地。"
D.LocalClientValues[7360]="邪能图腾魔裔恶犬"
D.LocalClientValues[7361]="苏拉玛"
D.LocalClientValues[7362]="诱导转向"
D.LocalClientValues[7363]="一个鬼母把鲑鱼溪当成了育婴所，在附近的地区养育了无数的小鬼。在她的子嗣继续增长之前，将其击败。"
D.LocalClientValues[7364]="平衡德鲁伊"
