D.LocalClientValues[7367]="壁炉谷"
D.LocalClientValues[7368]="克索诺斯邪教徒"
D.LocalClientValues[7369]="白银之手的大多数圣骑士都会骑马上阵杀敌，而持盾卫士则精通防御性战斗技巧，他们能在战场上立起坚不可摧的防护之墙。"
D.LocalClientValues[7370]="最后的遗物：秘密"
D.LocalClientValues[7371]="曾经如田园般的琥珀谷花园里现在已经全是枯法行尸。其中最强大的行尸名叫沙兰。"
D.LocalClientValues[7372]="屠夫汉瓦尔"
D.LocalClientValues[7373]="通常猎风者幼龙会捕食风暴峡湾的牡鹿，但有只牡鹿反客为主，杀死了巨龙。消灭那只野兽。"
D.LocalClientValues[7374]="只要黑石氏族的战争机器有设计缺陷，我们就能破坏它们。快潜入敌方营地，检查他们的战争机器，寻找其弱点吧。"
D.LocalClientValues[7375]="有人在这座森林的上空目击到了军团的侦察部队。"
D.LocalClientValues[7376]="破碎命运印记物资"
D.LocalClientValues[7377]="骷髅爪牙"
D.LocalClientValues[7378]="苏拉玛的月落庇护所附近，蜘蛛们占据了花园。我们得清除那些蜘蛛网，让我们的部队可以驻扎在这个区域。"
D.LocalClientValues[7379]="诺米会为你研究新的食谱。"
D.LocalClientValues[7380]="在黑鸦堡垒的渡鸦之耀竞技场，我们的勇士可以证明自己的价值，并为我们的事业赢得尊重。派他们去参加争斗。"
