D.LocalClientValues[7621]="为了偷袭毫无防备的航母，我们特意设计出了潜水艇。我们已经在暗礁区准备了一艘航母供你练手。"
D.LocalClientValues[7622]="至高岭的牛头人知道如何应付危险的地理环境。但是威胁着他们的部族的不仅仅是峭壁和山峰。"
