D.LocalClientValues[7625]="海象人渔网"
D.LocalClientValues[7626]="教团的狂热者是虔诚的神职人员，他们的修行方式对肉体十分严苛，其中包括痛苦的自我鞭笞。但为了寻求灵魂的开悟，他们甘愿忍受痛苦。"
