D.LocalClientValues[7639]="我们得想办法进入法罗纳尔，但这一路上都是恶魔。让我们看看能否找到别的路径。"
D.LocalClientValues[7640]="元素生物天性混乱，最好别去招惹它们。但这个元素生物有我们需要的东西：物资。去好好劝劝它，让它无法拒绝我们的要求吧。"
