D.LocalClientValues[7687]="需要将物资或部队运送到地面位置的目标。\r\n\r\n|cffb2f0ff应对舰船：|r\r\n|TInterface\\ICONS\\Ships_ABILITY_BoardingPartyALLIANCE.blp:24:24:0:0|t |cffffffff运输舰|r"
D.LocalClientValues[7688]="一批钢铁部落的货物正在横渡塔纳安海域，其中包括纳格兰海底的藏宝图。如果你能将它拦截下来，就可以将这批地图收归己用了。"
D.LocalClientValues[7689]="燃烧军团的巫师在使用恶魔之血进行污秽的仪式。去断绝他们的物资供应吧。"
D.LocalClientValues[7690]="提高战胜食人魔的几率。"
D.LocalClientValues[7691]="只要失去首领，就能破坏高等食人魔袭击我们密探进行警告的图谋。派个刺客去干掉他们藏身于纳格兰的督军吧。"
D.LocalClientValues[7692]="有害材料"
D.LocalClientValues[7693]="我们在破碎群岛上的资源捉襟见肘，就连瓦尔莎拉的熊怪部族都开始扩张领地了。"
D.LocalClientValues[7694]="厚皮"
D.LocalClientValues[7695]="随着地狱火和恶魔卫士对塔拉多的入侵，其余的燃烧军团部队也不远了。去击败他们，并试着找出这些恶魔的来源。"
D.LocalClientValues[7696]="燃烧军团的密探正在追杀来自沙塔斯的德莱尼难民。快去收拢难民，将他们送去安全的地方。"
D.LocalClientValues[7697]="阻塞堡垒"
D.LocalClientValues[7698]="一群鬣蜥人占领了附近的一座珍贵的矿场。如果我们还想用这座矿场的话，就得把他们赶走。"
D.LocalClientValues[7699]="變異怪遭遇戰1"
D.LocalClientValues[7700]="猛击敌人的咽喉，应对|C00b3ffff法术|R。"
D.LocalClientValues[7701]="群体焚化"
D.LocalClientValues[7702]="急浪船员"
D.LocalClientValues[7703]="魔血蛆虫"
D.LocalClientValues[7704]="一个愤怒的熔池领主带领着一群恶魔，想要夺回安尼赫兰熔池。快设下陷阱欢迎他们“回家”。"
D.LocalClientValues[7705]="刻苦锻炼、日益精进才是弘扬我派的唯一途径。有一名老师傅可能会愿意分享他的武学经验。我们必定能从他那里学到不少东西。"
D.LocalClientValues[7706]="莫多维乔"
D.LocalClientValues[7707]="“蓝焰”戈尔高"
D.LocalClientValues[7708]="刀塔食人魔从要塞抓走了一批工人。快潜入他们的要塞，释放那些工人。"
D.LocalClientValues[7709]="钻石原石"
D.LocalClientValues[7710]="远古列王之弓"
D.LocalClientValues[7711]="酸液喷射"
D.LocalClientValues[7712]="扭曲之尘"
D.LocalClientValues[7713]="刀扇"
D.LocalClientValues[7714]="保护死亡骑士不受有害魔法效果的伤害。"
D.LocalClientValues[7715]="冷遇"
D.LocalClientValues[7716]="造餐术"
D.LocalClientValues[7717]="加尔佐斯"
D.LocalClientValues[7718]="白鬼兽人偷走了一个强大的饰品，并逃入了群山之中。现在，他们还发誓要杀掉所有靠近“宝贝”的人。接受这个挑战吧！"
D.LocalClientValues[7719]="现在我们的舰船装备更精良了，再去见见老对手吧。它还是在老地方等着。"
D.LocalClientValues[7720]="萨格雷和他们的盟友还在继续亵渎奥金顿。我建议执行我们的“叛徒必须死”政策。"
D.LocalClientValues[7721]="暮光归来"
D.LocalClientValues[7722]="碎刃"
D.LocalClientValues[7723]="恶魔霸主"
D.LocalClientValues[7724]="阴郁沼泽的大魔王"
D.LocalClientValues[7725]="熔炉"
D.LocalClientValues[7726]="至高岭著名的搏击冠军向所有人发起了挑战：谁能在和他的对决中撑3个回合，将会获得丰厚的奖励。"
D.LocalClientValues[7727]="痛楚堡垒内的墓穴上的远古雕刻或许可以让我们发现许多影月谷的秘密。我们必须想办法杀进去。"
D.LocalClientValues[7728]="Mikros - 7.0测试任务"
D.LocalClientValues[7729]="死忠的谄媚者"
D.LocalClientValues[7730]="风暴之门"
D.LocalClientValues[7731]="鲨鱼水箱"
D.LocalClientValues[7732]="召唤一支部队，可以陪勇士一起进行任务，从而提高成功率。"
D.LocalClientValues[7733]="超强的控场战"
D.LocalClientValues[7734]="每天，你的旅店中将出现一位访客并为你提供一个回报丰厚的地下城任务，持续一天。"
D.LocalClientValues[7735]="使完成任务后获得埃匹希斯水晶提高100%。"
D.LocalClientValues[7736]="我们的萨满准备了一个仪式，可以让影月氏族召唤的灵魂重新安息。快去墓地举行这个仪式吧。"
D.LocalClientValues[7737]="|cFFFFD200职业：|r猎人|n|n|cFFFFD200任务：|r勇士：猎手布雷克|n|n|cFFFFD200地区：|r风暴峡湾"
D.LocalClientValues[7738]="由精锐船员驾驶的舰船，擅长精妙的海战。专业船长没有直接的应对办法，但要想成功就不能忽视了他们。"
D.LocalClientValues[7739]="魔女萨拉西娅"
D.LocalClientValues[7740]="使命必达"
D.LocalClientValues[7741]="黑石大厨"
D.LocalClientValues[7742]="真气波"
D.LocalClientValues[7743]="散布消息"
D.LocalClientValues[7744]="巨大的囤积者"
D.LocalClientValues[7745]="死木羽刃战士"
D.LocalClientValues[7746]="邪能图腾好战者大军"
D.LocalClientValues[7747]="奥金尼狂热者"
D.LocalClientValues[7748]="恐惧之眼"
D.LocalClientValues[7749]="我们需要找到一位精通召唤强大恶魔的术士。在瓦尔莎拉进行侦察，留意任何有潜力的人。"
