D.LocalClientValues[7754]="嚎镇八方"
D.LocalClientValues[7755]="“我们不知道它们从哪儿冒出来的。我刚刚还在对敌人降下火雨，一转眼就发现一大群这种小鬼东西到处乱丢邪能箭。”——露露贝拉·菲兹班"
D.LocalClientValues[7756]="冰冻末日的使者，能够引导符文能量并使用武器狠毒地打击敌人，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[7757]="大殿"
D.LocalClientValues[7758]="使用这些超级照明灯洞穿迷雾（或许还有某些人的视网膜）。"
D.LocalClientValues[7759]="由德鲁伊施放，可移除一个有害魔法效果。"
D.LocalClientValues[7760]="并非所有的维库人都会前往英灵殿。据说，那些受到诅咒的维库人会前往噬魂之喉，一艘航行在无尽之海上的恐怖航船。"
D.LocalClientValues[7761]="赏金格斗"
D.LocalClientValues[7762]="调查英灵殿"
D.LocalClientValues[7763]="谎言寻觅者"
D.LocalClientValues[7764]="海咒奴隶"
D.LocalClientValues[7765]="梦魇令蜂群变得致命而狂暴。蜂群中最厉害的是马哈吉克，它体型巨大，只需一次钉刺即可杀死目标。消灭马哈吉克。"
D.LocalClientValues[7766]="纳格兰有一些特别巨大的裂蹄牛。趁它们没被陷阱捕杀殆尽之前，快去抓一头来吧。"
D.LocalClientValues[7767]="生产一批妖纹布。\r\n\r\n你可以在要塞报告中查看生产进度。\r\n\r\n当建筑达到2级或以上时，你可以通过建筑设计桌指派一名追随者在其中工作，以提高产量。"
D.LocalClientValues[7768]="来自炽燃冰川的双头飞龙攻击了我们的补给车队。我们必须保证物流通畅！"
D.LocalClientValues[7769]="永远不要相信法师"
D.LocalClientValues[7770]="寻宝"
D.LocalClientValues[7771]="魔血大锅"
D.LocalClientValues[7772]="雌鸟哈米，她就是盘旋在天空中的那群灾星的母亲。去找到她，击败她，让天空重获自由。"
D.LocalClientValues[7773]="探查德拉诺：霜火岭"
D.LocalClientValues[7774]="避开守卫"
D.LocalClientValues[7775]="由于鬣蜥人的好胃口，塔拉多一处定居点地下的洞穴开始变得不稳定了。我们必须保护地面上的居民。"
D.LocalClientValues[7776]="魔刃豹主母"
D.LocalClientValues[7777]="想要与军团有一战之力，我们需要找到更多的圣骑士盟友。"
D.LocalClientValues[7778]="艾露恩的花园落入了恐怖的暗影生物手中，其中有一个暗夜精灵巫师，也就是现在人们所称的神谕者。"
D.LocalClientValues[7779]="战列舰克制驱逐舰，航母克制战列舰，潜水艇克制航母，而驱逐舰又克制潜水艇。总而言之，这将是一场由运气主宰的战斗。"
D.LocalClientValues[7780]="进行短距离翻滚，应对|C00b3ffff危害|R。"
