D.LocalClientValues[7797]="雷霆突击"
D.LocalClientValues[7798]="任务时长增加。"
D.LocalClientValues[7799]="向前方传送一小段距离，应对|C00b3ffff危害|R。"
D.LocalClientValues[7800]="一个容器的碎片落于怨恨的阿格希尔德之手，她是一个落选的瓦尔基拉候选者。从她那里把容器找回来，这样我们才能布置针对哈卡的陷阱。"
D.LocalClientValues[7801]="无法安息的先祖"
D.LocalClientValues[7802]="一群效忠于奥丁的强大战士被海巨人抓住了，他们被迫在地下角斗场进行战斗。释放他们！"
