D.LocalClientValues[7804]="玛拉纳的威胁"
D.LocalClientValues[7805]="神鹤引项踢"
D.LocalClientValues[7806]="阿苏纳似乎是一座遍布野生动物的世外桃源。然而一系列关于该区域充斥着魔法活动的报告，似乎证明事情不像想象的那么简单。"
D.LocalClientValues[7807]="洞穴探险"
D.LocalClientValues[7808]="成功完成任务有几率带回真言圣物。可以将真言圣物给予勇士，增加成功几率。"
