D.LocalClientValues[7818]="野性的复仇"
D.LocalClientValues[7819]="在苏拉玛城的中心，有些夜之子对军团的“恩赐”抱有比其他人更大的兴趣。必须阻止米娅苏。"
D.LocalClientValues[7820]="由萨满祭司施放，可解决一个危险的敌人，还能让他们变笨。"
