D.LocalClientValues[7824]="导师塔拉娜"
D.LocalClientValues[7825]="欢愉女士"
D.LocalClientValues[7826]="风暴降生"
D.LocalClientValues[7827]="墓地中的幽灵无法安息。去追寻他们的知识和力量，用它们彻底破坏耐奥祖的阴谋。"
