D.LocalClientValues[7829]="剧毒织网者"
D.LocalClientValues[7830]="由圣骑士施放，可显著提高爆发性伤害。"
D.LocalClientValues[7831]="我们面对的不仅是鱼人的问题，还有一个鱼人偷走了维库人的护甲。去看看你们有没有办法阻止征服者格古尔。"
D.LocalClientValues[7832]="一挑三十！联盟的懦夫会管这叫冒险。但在部落，我们管这叫目标充裕！"
