D.LocalClientValues[7835]="戈隆攻击了一位炼金师的货车。现在，它们已经迷上了力量药水。在它们发现隐形药水之前，快去解决它们吧。"
D.LocalClientValues[7836]="大地图腾"
D.LocalClientValues[7837]="恶魔传送门"
D.LocalClientValues[7838]="血槌食人魔用奴隶作为劳动力。如果我们解放了那些矿工，就能干扰他们的工作了。这真是最贴切的双赢局面。"
