D.LocalClientValues[7865]="在彻底调查破碎海滩前，我们必须肃清燃烧军团的空中威胁。"
D.LocalClientValues[7866]="铁须船长是这片海域上的一大祸害，可他沉迷于某个子虚乌有的海怪传说。快去分散他的注意力，然后发动一次偷袭吧。"
