D.LocalClientValues[7886]="毁灭的征兆"
D.LocalClientValues[7887]="二十七头蛇"
D.LocalClientValues[7888]="尖叫的魔蝠"
D.LocalClientValues[7889]="食人魔奴贩们捕捉了许多因钢铁部落入侵而失去家园的德莱尼。派个人去他们的营地解放这些俘虏吧。"
