D.LocalClientValues[7894]="这艘敌方潜水艇装满了黄金，所以肯定跑不过我们。它躲进了一片暗礁与漩涡之间，企图将我们诱入绝境。"
D.LocalClientValues[7895]="现在我们的人手已经得到了扩充，该展现我们的力量，把部队投入战场了。海巨人是合适的目标，可以用来检验他们的技能。"
D.LocalClientValues[7896]="快跑！！"
D.LocalClientValues[7897]="灵媒阿尔诺之花"
D.LocalClientValues[7898]="一个矮人都不能少"
D.LocalClientValues[7899]="在地面上放置一个火焰陷阱，当敌人接近时会爆炸，应对|C00b3ffff爪牙|R。"
D.LocalClientValues[7900]="命令怒吼"
D.LocalClientValues[7901]="亡灵卫兵亚当斯"
D.LocalClientValues[7902]="这里肯定有人知道创世之柱的下落。我们必须找到他们。"
D.LocalClientValues[7903]="暮光召唤者乌恩"
D.LocalClientValues[7904]="月花谷"
D.LocalClientValues[7905]="符文祭师"
D.LocalClientValues[7906]="是时候除掉咸鱼斯提里了。"
D.LocalClientValues[7907]="元素领袖"
D.LocalClientValues[7908]="巨轮瓦斯卡在海洋中沉没后，强大的武器也随之遗失了。派出你的部队去找回那些武器，强化我们自己的部队！"
D.LocalClientValues[7909]="斥候报告说奥金顿附近有陌生的身影出没。这打扰了陵墓的清静。我们必须消灭一切带有邪能痕迹的东西。"
D.LocalClientValues[7910]="赶走熟睡的巨熊..."
D.LocalClientValues[7911]="大批受擾的祖先"
D.LocalClientValues[7912]="钢铁装配车间"
D.LocalClientValues[7913]="瓦尔莎拉的熊怪好像受到了恶魔的影响。我们必须立刻进行调查。"
D.LocalClientValues[7914]="邪恶回响"
D.LocalClientValues[7915]="啸天者托瓦拉"
D.LocalClientValues[7916]="林地守护者是塞纳留斯的后代，他们拥有一半精灵一半雄鹿的身形，一只手像是由树根编制而成的利爪。他们在自然界中拥有无比强大的力量。"
D.LocalClientValues[7917]="法罗纳尔是燃烧军团在阿苏纳保护最森严的堡垒之一。如果我们能干掉几个强大恶魔，就能夺得一些优势。"
D.LocalClientValues[7918]="能造成大量伤害的技能。"
D.LocalClientValues[7919]="安尼赫兰典狱官"
D.LocalClientValues[7920]="可怜的房子"
D.LocalClientValues[7921]="水之护盾"
D.LocalClientValues[7922]="溺死的守夜人"
D.LocalClientValues[7923]="木精已经将岗哨废墟里废弃的食人魔堡垒当成了新的育苗房。在他们蔓延到整个戈尔隆德之前，快去阻止他们吧。"
D.LocalClientValues[7924]="瓶装理智"
D.LocalClientValues[7925]="野兽克星"
D.LocalClientValues[7926]="一支燃烧军团部队威胁要把维迪卡尔永远赶出安托兰废土。别让他们得逞。"
D.LocalClientValues[7927]="恶臭的沼泽水花"
D.LocalClientValues[7928]="废土行动"
D.LocalClientValues[7929]="艾黛拉丝夫人"
D.LocalClientValues[7930]="腐臭蜂群"
D.LocalClientValues[7931]="唤潮者泰德鲁斯"
D.LocalClientValues[7932]="黑鸦堡垒已经被受诅咒者的灵魂所占领了。早已死去多时的泰莉西亚从墓穴中复活，开始攻击所有人。"
D.LocalClientValues[7933]="兽王达卡"
D.LocalClientValues[7934]="守望先锋"
D.LocalClientValues[7935]="抢夺历史"
D.LocalClientValues[7936]="怒刃奴仆"
D.LocalClientValues[7937]="部落封鎖了他們要塞週遭的海域。突破他們的封鎖線，襲擊部落的海軍船艦。"
D.LocalClientValues[7938]="清洁术"
D.LocalClientValues[7939]="一座巨型熔炉，可以超负荷供应动力。"
D.LocalClientValues[7940]="残忍的伊格罗夫领主"
D.LocalClientValues[7941]="伸出援手"
D.LocalClientValues[7942]="基尔加丹平台下面的传送门看护者对燃烧军团快速增援玛凯雷起到了关键作用。把这些传送门看护者送回扭曲虚空吧。"
D.LocalClientValues[7943]="霜甲术"
D.LocalClientValues[7944]="剧毒之花"
D.LocalClientValues[7945]="不要猫咪"
D.LocalClientValues[7946]="公海上的伏击"
D.LocalClientValues[7947]="吉斯林奈唤潮者"
D.LocalClientValues[7948]="守奴人库鲁斯托"
D.LocalClientValues[7949]="我们收到情报说，一队碎手兽人已经出发，前去支援塔拉多的钢铁部落。可惜他们永远别想到达目的地了。"
D.LocalClientValues[7950]="食人魔穆戈尔和几位角斗士发生了摩擦，可他不想杀害同胞。因此他决定付钱让我们帮他干脏活。"
D.LocalClientValues[7951]="软泥喷射"
D.LocalClientValues[7952]="神器 - 恶魔猎手任务"
D.LocalClientValues[7953]="每次运到的货物可提供更多的真铁矿石原料。"
D.LocalClientValues[7954]="有价值的目标"
D.LocalClientValues[7955]="提高所有追随者完成任务后获得的经验值。"
D.LocalClientValues[7956]="一种生长在塔拉多水域中的稀有莲花。我们的炼金师说它比寒霜草的效果要强得多。"
D.LocalClientValues[7957]="阿呆与阿瓜"
D.LocalClientValues[7958]="召唤一个放在魔化护命匣里的地狱火，可以释放它以完成一个世界任务。"
D.LocalClientValues[7959]="人在旅途"
D.LocalClientValues[7960]="盾牌冲锋"
D.LocalClientValues[7961]="末日使者扎索斯"
D.LocalClientValues[7962]="一种严酷而危险的环境。"
D.LocalClientValues[7963]="移除每天第一个需要5名追随者参与的任务的行动时间。"
D.LocalClientValues[7964]="大笑的战斧"
D.LocalClientValues[7965]="鬼母戈索尔"
D.LocalClientValues[7966]="老调重弹"
D.LocalClientValues[7967]="狂野地狱火护卫"
D.LocalClientValues[7968]="灼热之焰"
D.LocalClientValues[7969]="在邪魂堡垒中，巨型地狱火和魔蝠会攻击任何靠近的人。干掉几个这样的敌人，收集它们的鲜血供我们使用。"
D.LocalClientValues[7970]="索米尔夫人"
D.LocalClientValues[7971]="群星回响"
D.LocalClientValues[7972]="影月通灵师"
D.LocalClientValues[7973]="沙兹古尔"
D.LocalClientValues[7974]="救援雪鬃村"
D.LocalClientValues[7975]="清算"
D.LocalClientValues[7976]="血槌食人魔奴役其他种族，并依靠剥削奴隶的劳动力为生。为了鼓舞那些被践踏的奴隶，去跟他们的压迫者狠狠大战一场吧。"
D.LocalClientValues[7977]="限时战斗"
D.LocalClientValues[7978]="猎风头龙"
D.LocalClientValues[7979]="学徒实验室"
D.LocalClientValues[7980]="达拉然的紫罗兰监狱中囚禁着一些史上最危险的生物。我们不能让监狱落在燃烧军团的手上。快去调查！"
D.LocalClientValues[7981]="允许拥有看家护院专长的追随者在德拉诺充当你的护卫。"
D.LocalClientValues[7982]="为传送门供能：瓦尔莎拉"
D.LocalClientValues[7983]="白银之手的骑士每天不仅虔诚地祈祷，练武也从不懈怠，他们为了保护无辜和弱者而苦练本领。"
D.LocalClientValues[7984]="邪能魔法腐蚀了影月谷的一些古树。我们必须砍倒它们，终止其疯狂的破坏行为。"
D.LocalClientValues[7985]="冰霜与死亡"
D.LocalClientValues[7986]="祝福仪式"
D.LocalClientValues[7987]="心灵尖啸"
D.LocalClientValues[7988]="一些嗜虐成性的刃牙虎人以为德拉诺的混乱意味着他们可以随意虐杀无辜者，而不用害怕被惩罚。快去纠正他们的错误观念吧。"
D.LocalClientValues[7989]="咆哮的虚空"
D.LocalClientValues[7990]="斯洛安·麦考伊"
D.LocalClientValues[7991]="龙翼翱翔"
D.LocalClientValues[7992]="蒂亚娜夫人"
D.LocalClientValues[7993]="火刃烈焰先知"
D.LocalClientValues[7994]="黑暗收割议会中很少有助祭能晋升为祈祷者，因为他们常常会被自己在晋升仪式中召唤出来的黑暗能量吞噬。"
D.LocalClientValues[7995]="我们在阿兰卡峰林的盟友请求我们帮忙对付一群暴怒的野蜂，蜂群已经威胁到了他们的原油开采工作。"
D.LocalClientValues[7996]="我们听到传闻，有一名恶魔正试图劝诱至高岭的牛头人接受黑暗力量。"
D.LocalClientValues[7997]="光铸盾卫"
D.LocalClientValues[7998]="不能就这么回家"
D.LocalClientValues[7999]="塔拉多"
D.LocalClientValues[8000]="古尔丹之手号"
D.LocalClientValues[8001]="大灾变区域"
D.LocalClientValues[8002]="侦察：风暴峡湾"
D.LocalClientValues[8003]="一艘拥有大口径火炮的强力舰船，可用于海军行动。\r\n\r\n|cFFFFD200建造时间：1小时|r\r\n\r\n|cffb2f0ff应对舰船：|r\r\n|TInterface\\ICONS\\Ships_ABILITY_DepthCharges.blp:24:24:0:0|t |cffffffff驱逐舰|r"
D.LocalClientValues[8004]="恐惧渡鸦正在通天峰下收集碎片。他们正在建造更多的构装体或巢穴。必须阻止他们。"
D.LocalClientValues[8005]="守卫斯考德-艾希尔的是白色哨兵，它是个泰坦构造体，用于驱逐那些无能者。我们必须证明我们的英雄比它更强。"
D.LocalClientValues[8006]="为我们的到来做好准备"
D.LocalClientValues[8007]="经过证实，我们在碎手氏族中的线人都是双面间谍。去安排一次秘密接头，然后把他们一网打尽吧。"
D.LocalClientValues[8008]="为了砧板上的鲜肉，屠夫汉瓦尔屠杀了许多野兽和人类。在风暴峡湾的群山中找到他，结束他的血腥盛宴。"
D.LocalClientValues[8009]="水面上漂浮着巨大的冰块。在冰块间迷宫般的水道中航行容易使你的舰船遭到攻击。"
D.LocalClientValues[8010]="骨语缚墨者"
D.LocalClientValues[8011]="去戈尔隆德的北部荒野上掘地三尺寻找洛克尔吧。为了要塞的荣耀，去找到并击败他。"
D.LocalClientValues[8012]="陶森"
D.LocalClientValues[8013]="生命魔典"
D.LocalClientValues[8014]="要想创造更多警卫，就需要启迪者飞地里收藏的知识。快派你的勇士去找找。"
D.LocalClientValues[8015]="通缉：逆流"
D.LocalClientValues[8016]="战旗"
D.LocalClientValues[8017]="沸燃使徒"
D.LocalClientValues[8018]="卡德加的全视之眼"
D.LocalClientValues[8019]="“力量与气力的差别，就如日月般一目了然。”——白虎雪怒"
D.LocalClientValues[8020]="冰封爪牙"
D.LocalClientValues[8021]="骨语符文斧兵"
D.LocalClientValues[8022]="助祭"
D.LocalClientValues[8023]="醉人的力量"
D.LocalClientValues[8024]="鹰身人羽毛"
