D.LocalClientValues[8026]="刃喉虐待者"
D.LocalClientValues[8027]="该任务涉及制皮专业。"
D.LocalClientValues[8028]="大肉排"
D.LocalClientValues[8029]="由猎人施放，可打断施法。"
D.LocalClientValues[8030]="邪污之血"
D.LocalClientValues[8031]="梦魇仪式"
D.LocalClientValues[8032]="虚空守望者瓦苏拉"
D.LocalClientValues[8033]="部落潜水艇"
D.LocalClientValues[8034]="下面的石头"
D.LocalClientValues[8035]="首领在大杀特杀，阻止他们。"
D.LocalClientValues[8036]="本地的植物又开始不安分了。肯瑞托请求我们帮忙搞些“园艺”工作。"
D.LocalClientValues[8037]="地区支援 - 苏拉玛"
D.LocalClientValues[8038]="大手握大剑"
D.LocalClientValues[8039]="通天峰行动"
