D.LocalClientValues[8043]="镰牙迅猛龙"
D.LocalClientValues[8044]="登船突击队"
D.LocalClientValues[8045]="断角村"
D.LocalClientValues[8046]="拜邪能图腾的入侵所赐，虫语者正在至高岭牛头人的墓地里搜寻腐肉。给它们点教训，让它们学会尊重死者。"
D.LocalClientValues[8047]="虽然大分裂的余波仍在，大地之环还是响应号召来到了破碎群岛。燃烧军团的威胁太强大了，需要团结一切可团结的力量。"
D.LocalClientValues[8048]="迪菲亚兄弟会这些久经考验的法外狂徒以反抗贵族的腐败统治为己任，他们通常戴着红色的面罩，象征着受压迫者的鲜血。"
D.LocalClientValues[8049]="地狱火之怒"
D.LocalClientValues[8050]="|CFFFFFFF0部队|R\r\n这支部队拥有强大的护甲。若无法应对，则会增加任务时长。"
D.LocalClientValues[8051]="人类死亡骑士"
D.LocalClientValues[8052]="刀塔蛮兵"
D.LocalClientValues[8053]="起泡的瘟疫"
D.LocalClientValues[8054]="大群老鼠"
D.LocalClientValues[8055]="高阶贤者维里克斯"
D.LocalClientValues[8056]="加尔顿的需求"
D.LocalClientValues[8057]="黑石兽人正在用本地无辜的动物试验他们的战争机器。这种暴行绝对不能容忍！"
D.LocalClientValues[8058]="恢复萨满祭司"
D.LocalClientValues[8059]="征服纳格兰"
D.LocalClientValues[8060]="斥候报告说，现在对索克雷萨高地发起突袭的话，就能搜刮到额外的埃匹希斯水晶。"
D.LocalClientValues[8061]="刃喉秘法师"
D.LocalClientValues[8062]="无法安息的高贵灵魂"
D.LocalClientValues[8063]="影月谷當地有個私掠者已經在替我們攻擊聯盟，而你只需把貨物走私過鋼鐵部落在南海設下的封鎖線。"
D.LocalClientValues[8064]="沉默的守卫"
D.LocalClientValues[8065]="恶毒者泰勒斯塔"
D.LocalClientValues[8066]="驱魔人"
D.LocalClientValues[8067]="燃烧抢劫者"
D.LocalClientValues[8068]="深渊领主獠牙"
D.LocalClientValues[8069]="黑鸦刺客团体"
D.LocalClientValues[8070]="|cFFFFD200任务：|r庆祝的正当理由|n|cFFFFD200地区：|r塔拉多"
D.LocalClientValues[8071]="发射穿甲弹，击穿对方的装甲。"
D.LocalClientValues[8072]="暗影牧师"
D.LocalClientValues[8073]="野生夜刃豹"
D.LocalClientValues[8074]="裂魂之刃"
D.LocalClientValues[8075]="铭文师之家可以生产各种魔法墨水、颜料和纸张，还可以制作雕文和其他魔法物品。"
D.LocalClientValues[8076]="最后的圣坛"
D.LocalClientValues[8077]="解锁珠宝加工任务，并允许同时接受最多21份产品订单。"
D.LocalClientValues[8078]="污染小径直通燃烧裂口。先去侦察一下前面的路吧。"
D.LocalClientValues[8079]="血染大海"
D.LocalClientValues[8080]="邪能图腾部族用他们可怕的仪式给至高岭的水路下了毒，毒害了野外的动物。阻止他们！"
D.LocalClientValues[8081]="上蜡皮革"
D.LocalClientValues[8082]="传播变形"
D.LocalClientValues[8083]="圣光装备"
D.LocalClientValues[8084]="测试任务安德斯"
D.LocalClientValues[8085]="给极寒大陆架命名的兽人已经表明，那里的气候并不是周期性的降温，而是常年都处在能冻掉你下巴的状态下。"
D.LocalClientValues[8086]="狼母加鲁尔驯养了最凶猛的战歌座狼。弄些它们的毛皮来，这可以削弱战歌氏族的战力，还可以卖一大笔钱。"
D.LocalClientValues[8087]="弗鲁洛克"
D.LocalClientValues[8088]="食人魔犯境"
D.LocalClientValues[8089]="一群碎手强盗被打散了。虽然现在十分惶恐，但他们很快就会找到新的受害者了。"
D.LocalClientValues[8090]="守夜人"
D.LocalClientValues[8091]="警觉之眼"
D.LocalClientValues[8092]="极难"
D.LocalClientValues[8093]="黑暗裂隙"
D.LocalClientValues[8094]="执行该任务的部队将会阵亡。"
D.LocalClientValues[8095]="塔纳安丛林是一片严酷的土地，那里居住着这个世界上最强大野兽。"
D.LocalClientValues[8096]="搜寻猎物"
D.LocalClientValues[8097]="魔刃豹"
D.LocalClientValues[8098]="影卫深渊召唤者想在幽影之地再召唤一个虚空领主。阻止仪式，别让他们成功。"
D.LocalClientValues[8099]="允许生产制皮物品并接受产品订单。"
D.LocalClientValues[8100]="破坏法阵"
D.LocalClientValues[8101]="刃月的秘密"
D.LocalClientValues[8102]="魔钢盾墙"
D.LocalClientValues[8103]="提高与亡灵一起执行任务的成功率。"
D.LocalClientValues[8104]="动荡冥河卷轴"
D.LocalClientValues[8105]="你的照片确实很出色，但现在我们需要更有创意的照片。快回到野外去，看看你有什么想法吧！"
D.LocalClientValues[8106]="历史的教训"
D.LocalClientValues[8107]="豪能酒"
D.LocalClientValues[8108]="用精灵语命名的烈焰之击原本是逐日者家族所使用的战斗武器。这把剑最终遗失在诺森德。"
D.LocalClientValues[8109]="7.0 提示假人 - 装备 - 紫色 - 职业大厅资源"
D.LocalClientValues[8110]="在这么高的山顶，元素生物本身就是我们最大的敌人。风元素和冰元素在山峰四处游荡。击败他们，继续前行！"
D.LocalClientValues[8111]="宇宙密使"
D.LocalClientValues[8112]="乌瑟尔·光明使者是白银之手骑士团的第一个圣骑士，他对圣光的信仰从未动摇。他的墓地对圣光的追随者来说无比神圣，但也会吸引一些邪恶的灵魂。"
D.LocalClientValues[8113]="法术（扰乱）"
