D.LocalClientValues[8177]="窒息"
D.LocalClientValues[8178]="苏拉玛被分为两部分，一部分是摇摇欲坠的废墟，一部分是闪闪发光的高度文明。但两者都不安全。调查一下，看哪里最需要我们的帮助。"
D.LocalClientValues[8179]="一批消魔之石正被运往格罗玛什尔。我们必须进行拦截。就算没有这批魔法宝石，钢铁部落也已经够麻烦的了。"
