D.LocalClientValues[8258]="夕阳海岸"
D.LocalClientValues[8259]="打打杀杀的事情可以之后再处理，眼下我们需要找个见多识广的家伙。正好我知道有个人参加了过去几十年里每一场战争，而且还不是光懂打架。"
D.LocalClientValues[8260]="这里曾经是个宁静祥和之地，现在已经成为了梦魇的国度。恐怖的生物正在瓦尔莎拉四处散布着黑暗和污秽。"
