D.LocalClientValues[8555]="刀喙"
D.LocalClientValues[8556]="征调一群黑暗收割祈祷者来为你执行任务。\r\n\r\n|cFFFFD200建造时间：30分钟|r"
D.LocalClientValues[8557]="两个强大的食人魔占据了一部分矿区，那里正巧有一批珍贵的燃料。"
D.LocalClientValues[8558]="失心蛞蝓"
D.LocalClientValues[8559]="定点轰炸演习"
D.LocalClientValues[8560]="艾瑞达塑灵师正在石化森林里制造可憎的乌祖尔。一定要阻止他们。"
D.LocalClientValues[8561]="醉拳"
D.LocalClientValues[8562]="堕落者的命运"
D.LocalClientValues[8563]="与联盟结盟的德莱尼首领就住在艾洛多尔的市区里。去给他们一个教训吧：抢走他们运送的一批黄金。"
D.LocalClientValues[8564]="圣骑士C部队"
D.LocalClientValues[8565]="巨龙泽瑞西亚已经被杀死，但暮光之锤并没有彻底放弃他们在深岩之洲的努力。我们应该派出一支突击小队。"
D.LocalClientValues[8566]="你在看什么。"
D.LocalClientValues[8567]="我们收到报告说影月氏族正在幽影林地里活动，用污秽的魔法笼罩了那片土地。一定要不惜一切代价打断他们的黑暗仪式。"
D.LocalClientValues[8568]="杀掉沙漠里的食人魔。"
D.LocalClientValues[8569]="化犁为剑"
D.LocalClientValues[8570]="不让一个骑士掉队"
D.LocalClientValues[8571]="喋喋不休的恶魔"
D.LocalClientValues[8572]="杜卡斯·钢喉"
D.LocalClientValues[8573]="黑手的熔炉"
D.LocalClientValues[8574]="拾荒者"
D.LocalClientValues[8575]="扔酒"
D.LocalClientValues[8576]="公共生活"
D.LocalClientValues[8577]="鹰身人的谋杀"
D.LocalClientValues[8578]="奔向自由！"
D.LocalClientValues[8579]="远古尸骸"
D.LocalClientValues[8580]="脑子……"
D.LocalClientValues[8581]="真言圣物"
D.LocalClientValues[8582]="范围打击技能，必须躲开或逃走。"
D.LocalClientValues[8583]="女巫道恩"
D.LocalClientValues[8584]="真铁"
D.LocalClientValues[8585]="一座火山中的堡垒既是天才的设想也是愚蠢的念头。它确实无法被攻破，可一个萨满就能引起火山喷发，从而将它淹没。"
D.LocalClientValues[8586]="迷人目光"
D.LocalClientValues[8587]="苏生卷轴"
D.LocalClientValues[8588]="由萨满祭司施放，可治疗一群盟友。"
D.LocalClientValues[8589]="战歌侦查骑兵"
D.LocalClientValues[8590]="令你可以使用私人银行，并使所有建筑的活跃产品订单数提升5。"
D.LocalClientValues[8591]="刺脊之鳞"
D.LocalClientValues[8592]="如果这是当天的第一个任务，那么应该会大幅提升你的成功率。还会给你一个超酷的物品！"
D.LocalClientValues[8593]="黑暗的地下。"
D.LocalClientValues[8594]="使用神圣的魔法为自己和盟友提供防护，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[8595]="莫提法洛斯"
D.LocalClientValues[8596]="一边是巨额的财富，一边是凶猛的行尸。噢，来吧，我们都知道你会同意的。"
D.LocalClientValues[8597]="黑锋之门"
D.LocalClientValues[8598]="死亡之握"
D.LocalClientValues[8599]="死亡之蹄"
D.LocalClientValues[8600]="破坏黑石补给"
D.LocalClientValues[8601]="一船来自影月谷的裁缝产品正驶向暴风之盾。拦下它，把战利品分了。"
D.LocalClientValues[8602]="远古魔法"
D.LocalClientValues[8603]="征服戈尔隆德"
D.LocalClientValues[8604]="若能找到可使用的军团传送门，我们就能对一个军团世界发动攻击，并将它据为己有。"
D.LocalClientValues[8605]="倒霉的英雄"
D.LocalClientValues[8606]="多刺的投矛手"
D.LocalClientValues[8607]="战争古树"
D.LocalClientValues[8608]="被激怒的斯通加尔开始攻击元素王座附近的萨满了。我们得派出援军。"
D.LocalClientValues[8609]="木精护林者"
D.LocalClientValues[8610]="黑暗骑士"
D.LocalClientValues[8611]="祝福祭坛"
D.LocalClientValues[8612]="人离乡贱"
D.LocalClientValues[8613]="蛛后阿兰妮艾"
D.LocalClientValues[8614]="虚空收割器正在影卫入侵营地里收集大量的虚空能量。一定要把它们毁掉！"
D.LocalClientValues[8615]="鸦人奴役了更多的流亡者，并重新开始了挖掘工作。我们需要再次挫败他们的行动。"
D.LocalClientValues[8616]="|cFFFFD200成就：|r利爪之王的传承|n"
D.LocalClientValues[8617]="潮汐之力"
D.LocalClientValues[8618]="|cFFFFD200职业：|r潜行者|n|n|cFFFFD200任务：|r提拔勇士|n|n|cFFFFD200地区：|r邪能之槌号"
D.LocalClientValues[8619]="冥狱使者萨罗斯"
D.LocalClientValues[8620]="部落的船只正盼着联盟来袭呢。他们肯定很喜欢抢夺战利品，以及海滩上的漫步。他们对蓝色和紫色的忍耐度可是很高的。"
D.LocalClientValues[8621]="邪舌腐化者"
D.LocalClientValues[8622]="巴达丁大师"
D.LocalClientValues[8623]="一个出人意料的敌人，其侵略性必须得到遏制。"
D.LocalClientValues[8624]="用一面骨盾保护死亡骑士。"
D.LocalClientValues[8625]="使你可以从德拉诺的食人魔身上收集到食人魔道标石。这些道标石可以用来给你在德拉诺选定的食人魔传送门充能。在战斗中偶尔也会触发能量符文。"
D.LocalClientValues[8626]="不再等待"
D.LocalClientValues[8627]="解锁巡逻任务。巡逻任务的经验奖励比普通追随者任务的奖励更高。"
D.LocalClientValues[8628]="卡扎杜姆"
D.LocalClientValues[8629]="传送"
D.LocalClientValues[8630]="宠物对战"
D.LocalClientValues[8631]="急转弯！"
D.LocalClientValues[8632]="你可以进入扭曲虚空传送门，召唤强大的恶魔。你和你的盟友可以击败恶魔，获得强化奖励，还可能获得宝物。"
D.LocalClientValues[8633]="迫在眉睫"
D.LocalClientValues[8634]="暗影猎手阿拉克纳"
D.LocalClientValues[8635]="灵痕克罗库在奥罗纳尔废墟囤积了很多阿古尼特水晶，打算用它们完成某些不可告人的目的。去把他们的宝库抢过来吧。"
D.LocalClientValues[8636]="遗忘学识"
D.LocalClientValues[8637]="调查艾萨拉之眼"
D.LocalClientValues[8638]="作为太阳神的化身，鲁克玛要求绝对的忠诚和服从。她可不是那么好对付的。"
D.LocalClientValues[8639]="废料场里到处都是死者。搜寻这片区域，寻找强力的物品。"
D.LocalClientValues[8640]="信徒暴风使者"
D.LocalClientValues[8641]="深涌潮汐咏者"
D.LocalClientValues[8642]="逃脱的虚空之灵"
D.LocalClientValues[8643]="通天峰"
D.LocalClientValues[8644]="毒害之云"
D.LocalClientValues[8645]="|cFFFFD200地区：|r影月谷|n"
D.LocalClientValues[8646]="货栈是要塞与德拉诺原住民们进行交易的贸易中心。"
D.LocalClientValues[8647]="这两艘船正顶着飓风驶向南方。如果不是有紧急任务的话，就算是疯狂如地狱咆哮也不会派它们出来的。我们必须拦下它们。"
D.LocalClientValues[8648]="地狱咆哮现在应该已经明白了，元素是不会甘愿臣服于钢铁部落的。强迫它们屈服的做法并不明智。"
D.LocalClientValues[8649]="咸水海沟"
D.LocalClientValues[8650]="奴役魔典"
D.LocalClientValues[8651]="由牧师施放，可显著提高爆发性伤害和法力回复速度。"
D.LocalClientValues[8652]="被诅咒的水手。"
D.LocalClientValues[8653]="邪能烟幕发射器"
D.LocalClientValues[8654]="缚魂者尼娅米是一名阴谋家和叛徒，她生前掌握着强大的暗影魔法。在死后，她成了暗影精华的完美载体。前往暗影界，从她的灵魂中收集暗影精华吧。"
D.LocalClientValues[8655]="枯法法力怨灵"
D.LocalClientValues[8656]="食人魔正迫使我们的盟友在他们的竞技场里战斗。快假装成角斗士去救出那些不情愿的斗士吧。"
D.LocalClientValues[8657]="萨格雷警戒者"
D.LocalClientValues[8658]="蔑魔狂热者集群"
D.LocalClientValues[8659]="就连其他夜之子也都十分畏惧可怕的莉莉丝，她和恐怖的渗透者一起潜伏在黑夜中。直面所有的恐惧，解决掉莉莉丝。"
D.LocalClientValues[8660]="稀有的花"
D.LocalClientValues[8661]="监视者艾瓦"
D.LocalClientValues[8662]="恶魔蛮兵"
D.LocalClientValues[8663]="刀塔氏族制定了一个“防火防盗防蠢蛋”的防御计划。为了破坏这个计划，快去干掉他们的精英，把“蠢蛋”留下。"
D.LocalClientValues[8664]="骚动的灌木丛"
D.LocalClientValues[8665]="皇家咒法师"
D.LocalClientValues[8666]="刃舞者弗尔加"
D.LocalClientValues[8667]="阿古斯精英"
D.LocalClientValues[8668]="征调一群邪能愤怒卫士恶魔来为你执行任务。\r\n\r\n|cFFFFD200建造时间：1小时|r"
D.LocalClientValues[8669]="我们遭到了鹰身人的无情攻击。守住这次攻击，干掉他们的领袖。"
D.LocalClientValues[8670]="玛拉纳战士"
D.LocalClientValues[8671]="钢铁部落在黑石矿坑的发掘工作偶尔能挖到一些稀有的钻石。去抢一颗来，我们需要它。"
D.LocalClientValues[8672]="有来无回！"
D.LocalClientValues[8673]="马革裹尸"
D.LocalClientValues[8674]="指挥官萨森纳尔"
D.LocalClientValues[8675]="泡沫经济"
D.LocalClientValues[8676]="格拉尔船长"
D.LocalClientValues[8677]="在嗜血欲望的驱使下，兽人畜生们盯上了我们的航母，即使是远离霜火岭水域的也不放过。面对这种挑衅，我们是不会逆来顺受的。我们要反击。"
D.LocalClientValues[8678]="许多获救的德莱尼俘虏失踪了，罪魁祸首应该是刃牙虎人。先将自己武装到牙齿，然后去调查一下吧。"
D.LocalClientValues[8679]="阿苏纳法力浮龙"
D.LocalClientValues[8680]="征调一队[单位]为你执行任务。\r\n\r\n|cFFFFD200建造时间：30分钟|r"
D.LocalClientValues[8681]="在斯考德-艾希尔墙壁外面，一个名叫拉格萨的堕落女武神正妄图强行在瓦尔基拉中夺取一个位置。"
D.LocalClientValues[8682]="乌鸦烧烤"
D.LocalClientValues[8683]="联盟精锐潜水艇"
D.LocalClientValues[8684]="传说影月谷的南部边界上游荡着一头幽灵塔布羊。我们得去调查一下。"
D.LocalClientValues[8685]="哀叹往昔"
D.LocalClientValues[8686]="迫使目标攻击德鲁伊。"
D.LocalClientValues[8687]="降低任务成功率。没有应对方法。"
D.LocalClientValues[8688]="残寺派已经建立了，但我们还需要更多的帮手。田吉是玄牛派中有名的部队训练师，刚刚发来消息说她遭到了攻击！"
D.LocalClientValues[8689]="使完成任务后获得的要塞物资提高100%。"
D.LocalClientValues[8690]="塔隆戈尔低语号"
D.LocalClientValues[8691]="黑暗的守护者，控制和腐蚀生命能量的能力使其能够直面敌人的猛攻，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[8692]="邪能坩埚"
D.LocalClientValues[8693]="凶残的斯奎什"
D.LocalClientValues[8694]="完成任务后获得的要塞物资提高200%。"
D.LocalClientValues[8695]="溺亡之握"
D.LocalClientValues[8696]="|cFFFFD200成就：|r送铁上门|n"
D.LocalClientValues[8697]="巨兽之眼"
D.LocalClientValues[8698]="寻找圣光"
D.LocalClientValues[8699]="为了征调更多的凶犯加入到无冕者中，舰队上将特塞斯想要从我们中最厉害的好手开始。扬希·格里尔森这位海盗就是最好的人选。"
D.LocalClientValues[8700]="海湾猎手"
D.LocalClientValues[8701]="“如果你能支配敌人脚下的土地，那他们想击败你简直是异想天开。”——地卜师贾卡拉"
D.LocalClientValues[8702]="驱逐舰的外层装甲非常厚实，普通弹药根本不可能打穿它。为了能够击穿驱逐舰的装甲，我们特意建造出了战列舰。"
D.LocalClientValues[8703]="临时首领"
D.LocalClientValues[8704]="过载的攻城坦克"
D.LocalClientValues[8705]="燃烬风暴"
D.LocalClientValues[8706]="地狱犬"
D.LocalClientValues[8707]="据说我们的岗哨附近有一座钢铁部落的矿井，那里有一座富矿。我们不能让他们占有这么好的地方。冲进去，占领那座矿井吧。"
D.LocalClientValues[8708]="把战利品给我"
D.LocalClientValues[8709]="恶魔法阵"
D.LocalClientValues[8710]="小戈隆一直在干扰我们在戈尔隆德的扩张计划。如果想要在那里站稳脚跟的话，我们就得减少它们的数量。"
D.LocalClientValues[8711]="团体的祝福"
D.LocalClientValues[8712]="备战！"
D.LocalClientValues[8713]="工人之友"
D.LocalClientValues[8714]="刀塔督军"
D.LocalClientValues[8715]="晋升"
D.LocalClientValues[8716]="地区支援 - 萨尔达纳斯"
D.LocalClientValues[8717]="大地之钳"
D.LocalClientValues[8718]="强化巨龙枷锁"
D.LocalClientValues[8719]="孤独的龙"
D.LocalClientValues[8720]="人类船员"
D.LocalClientValues[8721]="一位前往霜火岭的部落战士不小心在船上丢下了一条魔法项链。快去帮他和他的船解脱吧。"
D.LocalClientValues[8722]="由猎人施放，可解决一个危险的敌人。小心脚下！"
D.LocalClientValues[8723]="测试追随者技能介绍"
D.LocalClientValues[8724]="恐怖收割"
D.LocalClientValues[8725]="至高岭的熊是让人头疼的问题。并非普通的熊，而是被鹰身人诅咒和腐蚀了熊。我们必须杀掉它们，结束它们的痛苦。"
D.LocalClientValues[8726]="普通"
D.LocalClientValues[8727]="莉莉丝和她的夜之子"
D.LocalClientValues[8728]="黑石氏族需要源源不断的金属补给才能维持战争机器的生产。让我们去给他们制造点麻烦吧。"
D.LocalClientValues[8729]="我们抓到了一名潜伏在城墙外的汽痕虎人。他许诺说，如果我们放他走，他就告诉我们一个敌对萨满的下落。据说他绘制了一张包含许多隐秘宝藏的藏宝图。"
D.LocalClientValues[8730]="德拉诺的一些种族愿意为那些大蘑菇出大价钱。也就是说，如果我们不插手的话，短视的部落很快就会将它们一扫而空的。"
D.LocalClientValues[8731]="先祖之地周围发生了风暴。这可能是沿海的敌方船只搞的鬼，难怪大部分萨满都很讨厌钢铁部落。"
D.LocalClientValues[8732]="恐蹄"
D.LocalClientValues[8733]="兵营可以容纳你的要塞部队和追随者。"
D.LocalClientValues[8734]="木精栽培者"
D.LocalClientValues[8735]="唤起圣光的能量来保护盟友，可以应对某些|C00b3ffff首领|R。"
D.LocalClientValues[8736]="由战士施放，可显著降低所受伤害。"
D.LocalClientValues[8737]="霜翼尖啸者"
D.LocalClientValues[8738]="驱赶影卫"
D.LocalClientValues[8739]="战争颜料"
D.LocalClientValues[8740]="有个巨型召唤法阵正在将恶魔从扭曲虚空召唤回阿古斯。破坏这个法阵，拖住燃烧军团的援军。"
D.LocalClientValues[8741]="我们的斥候报告说燃烧军团正在试验萨格拉斯的血液成分，想要强化他们的军队。我们必须派勇士去夺取那些血液，以为我们所用。"
D.LocalClientValues[8742]="很多蔑魔者聚集在英灵殿的大门前，其中包括一个魁梧的蛮兵，斩杀者诺萨米尔。杀了他，收集他的血液。"
D.LocalClientValues[8743]="出乎意料"
D.LocalClientValues[8744]="除掉双头巨人。"
D.LocalClientValues[8745]="召唤者斯塔诺斯"
D.LocalClientValues[8746]="圣光圣化武器"
D.LocalClientValues[8747]="征调一头冰霜巨龙用来释放。"
D.LocalClientValues[8748]="通缉：艾默松"
D.LocalClientValues[8749]="折跃力场"
D.LocalClientValues[8750]="极限拾荒"
D.LocalClientValues[8751]="玛格莫拉图斯"
D.LocalClientValues[8752]="夜之子宝库位于苏拉玛的燃烧军团所进攻区域的深处。如果大法师瓦格斯已经到过那里，我们应该可以找到他的痕迹。"
D.LocalClientValues[8753]="恐怖的美酒"
D.LocalClientValues[8754]="小戈隆对这一地区构成了威胁。我们应该与霜狼氏族合作，削减他们的数量。某个人甚至可能因此加入我们的事业……"
D.LocalClientValues[8755]="时机成熟"
D.LocalClientValues[8756]="阿比莎"
D.LocalClientValues[8757]="鲜血竞技场"
D.LocalClientValues[8758]="血主"
D.LocalClientValues[8759]="石怒崖的血槌食人魔是一群臭名昭著的奴隶贩子，十分野蛮。去解放那些的奴隶，不要对他们手软。"
D.LocalClientValues[8760]="任务消耗降低10%"
D.LocalClientValues[8761]="烈焰打击"
D.LocalClientValues[8762]="重金属"
D.LocalClientValues[8763]="蔑魔天选者"
D.LocalClientValues[8764]="剥魂者"
D.LocalClientValues[8765]="穆戈尔的困境"
D.LocalClientValues[8766]="列王守卫"
