D.LocalClientValues[8982]="传家宝"
D.LocalClientValues[8983]="骑手萨拉纳尔需要黑暗骑士曾用过的暗影缰绳。只能通过击败一名黑暗骑士来获取。"
D.LocalClientValues[8984]="我们的职业大厅已经建好了，但还需要更多的帮助。一位有名的元素召唤师摩恩传来消息说他遭受了攻击！"
D.LocalClientValues[8985]="我们好像失去了线索。只能背水一战了。潜入到军情七处总部，看看迪瑟洛克有没有留下任何线索。"
D.LocalClientValues[8986]="平原行者戈隆"
D.LocalClientValues[8987]="根据捕获的动物类型生产一批鲜肉、皮革或毛皮。\r\n\r\n当建筑达到2级或以上时，你可以通过建筑设计桌指派一名追随者在其中工作，以提高产量。"
D.LocalClientValues[8988]="看来部队投入实战的时机比预想的早。海达希亚水元素刚刚从阿苏纳发出了求救信号。"
D.LocalClientValues[8989]="随着时间流逝，苏拉玛的自然魔网能量和法力场使野外动物逐渐发生了变化。魔刃豹米奥妮克丝已经变成一只恐怖的野兽。"
