D.LocalClientValues[9002]="活性邪焰元素"
D.LocalClientValues[9003]="刃牙虎人有着高度成熟的宗教仪式和社会风俗。去和他们生活一段时间，学习他们的处世之道，并从中汲取力量吧。"
D.LocalClientValues[9004]="药剂"
D.LocalClientValues[9005]="吸取能量的流水之魂恰好克制了我们的施法者。是时候向他们伸出援手了。"
D.LocalClientValues[9006]="向水中投下炸弹，摧毁水下目标。"
D.LocalClientValues[9007]="激怒"
D.LocalClientValues[9008]="至高无上的荆棘大王"
D.LocalClientValues[9009]="真的勇士就要在坏天气里猎杀潜水艇，脚踩冰水，搏击激流，一样都不能少。"
